Object.assign(window.PTO_CSA_SOURCE.dependencies, {"hc_pre.py": "# Copyright (c) PyPTO Contributors.\n# This program is free software, you can redistribute it and/or modify it under the terms and conditions of\n# CANN Open Software License Agreement Version 2.0 (the \"License\").\n# Please refer to the License for details. You may not use this file except in compliance with the License.\n# THIS SOFTWARE IS PROVIDED ON AN \"AS IS\" BASIS, WITHOUT WARRANTIES OF ANY KIND, EITHER EXPRESS OR IMPLIED,\n# INCLUDING BUT NOT LIMITED TO NON-INFRINGEMENT, MERCHANTABILITY, OR FITNESS FOR A PARTICULAR PURPOSE.\n# See LICENSE in the root of the software repository for the full text of the License.\n# -----------------------------------------------------------------------------------------------------------\n\"\"\"DeepSeek-V4 hc_pre -- hyper-connection pre-mix, unified over decode and prefill.\"\"\"\n\n\nimport pypto.language as pl\n\nfrom config import FLASH as M, DECODE_BATCH, DECODE_SEQ, TP, PREFILL_BATCH, PREFILL_SEQ\n\n\n# Dynamic shape variables.\nT_DYN = pl.dynamic(\"T_DYN\")  # T = B * S\n\n# model config\nD = M.hidden_size\nHC_MULT = M.hc_mult\nMIX_HC = M.mix_hc\nHC_DIM = M.hc_dim\nHC_DIM_INV = 1.0 / HC_DIM\nHC_SINKHORN_ITER = M.hc_sinkhorn_iters\nHC_EPS = M.hc_eps\nNORM_EPS = M.rms_norm_eps\n\n# tiling\nMIX_PAD = 32  # mix_hc (24) padded to a 32-wide cube N / vector row\nHC_PAD = 8  # hc (4) padded for 32B-aligned vector ops\nT_TILE = 8  # other values miscompare\nLINEAR_T_TILE = 16  # cube matmul rows must be a 16-row boxed tile\nCOMB_T_TILE = 8\nRMS_K_TILE = 512\nLINEAR_K_TILE = 256\nD_TILE = 256\nD_SPMD = 4096\nLINEAR_OK = 4\nLINEAR_K_PER_SPLIT = HC_DIM // LINEAR_OK\n\n# pre0..pre3 / row0..row3 are hand-unrolled over the hc lanes.\nassert HC_MULT == 4, f\"hc_pre is specialized to HC_MULT == 4, got {HC_MULT}\"\n\n\n@pl.jit.inline\ndef hc_pre(\n    x: pl.Tensor[[T_DYN, HC_MULT, D], pl.FP32],\n    hc_fn: pl.Tensor[[MIX_HC, HC_DIM], pl.FP32],\n    hc_scale: pl.Tensor[[3], pl.FP32],\n    hc_base: pl.Tensor[[MIX_HC], pl.FP32],\n    x_mixed: pl.Tensor[[T_DYN, D], pl.BF16],\n    post: pl.Tensor[[T_DYN, HC_MULT], pl.FP32],\n    comb: pl.Tensor[[T_DYN, HC_MULT * HC_MULT], pl.FP32],\n):\n    \"\"\"One pl.spmd task per work-type, ordered by their GM read/write dependencies.\n\n    rms -> linear -> linear_reduce -> split_pre_post / comb_sinkhorn / mix_x. Cross-scope\n    buffers are sized to t_linear, the token count padded up to whole 16-row cube tiles.\n    \"\"\"\n    t_dim = pl.tensor.dim(x, 0)\n    token_tiles = (t_dim + T_TILE - 1) // T_TILE\n    t_linear = ((t_dim + LINEAR_T_TILE - 1) // LINEAR_T_TILE) * LINEAR_T_TILE  # pad t_dim up to whole 16-row cube tiles\n    x_flat = pl.reshape(x, [t_dim, HC_DIM])\n    scale0 = pl.read(hc_scale, [0])\n    scale1 = pl.read(hc_scale, [1])\n    scale2 = pl.read(hc_scale, [2])\n    hc_base_2d = pl.reshape(hc_base, [1, MIX_HC])  # for per-group comb base loads in comb_sinkhorn\n\n    inv_rms = pl.create_tensor([t_linear, 1], dtype=pl.FP32)\n\n    # rms: full-K sum-of-squares per token-tile -> inv_rms.\n    for t in pl.spmd(token_tiles, name_hint=\"hc_pre_rms\", allow_early_resolve=True):\n        t0 = t * T_TILE\n        valid_rows = pl.min(T_TILE, t_dim - t0)\n        sq_sum = pl.full([1, T_TILE], dtype=pl.FP32, value=0.0)\n        for kb in pl.pipeline(HC_DIM // RMS_K_TILE, stage=4):\n            k0 = kb * RMS_K_TILE\n            if valid_rows == T_TILE:\n                x_chunk_full = x_flat[t0:t0 + T_TILE, k0:k0 + RMS_K_TILE]\n                x_sq_full = pl.mul(x_chunk_full, x_chunk_full)\n                x_sq_row_full = pl.reshape(pl.row_sum(x_sq_full), [1, T_TILE])\n                sq_sum = pl.add(sq_sum, x_sq_row_full)\n            else:\n                x_chunk_tail = pl.slice(x_flat, [T_TILE, RMS_K_TILE], [t0, k0], valid_shape=[valid_rows, RMS_K_TILE])\n                x_sq_tail = pl.mul(x_chunk_tail, x_chunk_tail)\n                x_sq_row_tail = pl.reshape(pl.row_sum(x_sq_tail), [1, T_TILE])\n                sq_sum = pl.add(sq_sum, x_sq_row_tail)\n        sq_mean = pl.add(pl.mul(sq_sum, HC_DIM_INV), NORM_EPS)\n        inv = pl.reshape(pl.rsqrt(sq_mean, high_precision=True), [T_TILE, 1])\n        inv_rms[t0:t0 + T_TILE, 0:1] = inv\n\n    # linear: split-K matmul -> per-split partials. The t_dim..t_linear pad rows are\n    # zero-filled by valid_shape, never materialized.\n    mixes_partials = pl.create_tensor([LINEAR_OK * t_linear, MIX_PAD], dtype=pl.FP32)\n    for task in pl.spmd((t_linear // LINEAR_T_TILE) * LINEAR_OK, name_hint=\"hc_pre_linear\", allow_early_resolve=True):\n        t0 = (task // LINEAR_OK) * LINEAR_T_TILE\n        linear_split = task % LINEAR_OK\n        k_base = linear_split * LINEAR_K_PER_SPLIT\n        t_rows = pl.min(LINEAR_T_TILE, t_dim - t0)  # last row-block spills past t_dim; valid_shape zero-fills the tail\n        acc = pl.create_tensor([LINEAR_T_TILE, MIX_PAD], dtype=pl.FP32)\n        for kb in pl.pipeline(0, LINEAR_K_PER_SPLIT // LINEAR_K_TILE, stage=2):\n            k0 = k_base + kb * LINEAR_K_TILE\n            x_linear_chunk = pl.slice(x_flat, [LINEAR_T_TILE, LINEAR_K_TILE], [t0, k0], valid_shape=[t_rows, LINEAR_K_TILE])\n            w_chunk = pl.slice(hc_fn, [MIX_PAD, LINEAR_K_TILE], [0, k0], valid_shape=[MIX_HC, LINEAR_K_TILE])\n            if kb == 0:\n                acc = pl.matmul(x_linear_chunk, w_chunk, b_trans=True, out_dtype=pl.FP32)\n            else:\n                acc = pl.matmul_acc(acc, x_linear_chunk, w_chunk, b_trans=True)\n        partial_row0 = linear_split * t_linear + t0\n        mixes_partials[partial_row0 : partial_row0 + LINEAR_T_TILE, 0:MIX_PAD] = acc\n\n    # Partials are reduced in ascending K order.\n    mixes_raw = pl.create_tensor([t_linear, MIX_PAD], dtype=pl.FP32)\n    for linear_block in pl.spmd(t_linear // LINEAR_T_TILE, name_hint=\"hc_pre_linear_reduce\", allow_early_resolve=True):\n        linear_t0 = linear_block * LINEAR_T_TILE\n        mixes_total = mixes_partials[linear_t0 : linear_t0 + LINEAR_T_TILE, 0:MIX_PAD]\n        for linear_split in pl.range(1, LINEAR_OK):\n            partial_t0 = linear_split * t_linear + linear_t0\n            partial_tile = mixes_partials[partial_t0 : partial_t0 + LINEAR_T_TILE, 0:MIX_PAD]\n            mixes_total = pl.add(mixes_total, partial_tile)\n        mixes_raw[linear_t0 : linear_t0 + LINEAR_T_TILE, 0:MIX_PAD] = mixes_total\n\n    # split_pre_post: inv_rms-scaled pre gate -> pre_val_store (for mix_x), post gate -> post.\n    # Both compute at HC_PAD width; post narrows to HC_MULT via a valid-shape slice (an 8-wide\n    # 32B tile, 4 cols valid -- a bare 4-wide slice allocs a 16B tile ptoas rejects). comb gate\n    # lives in comb_sinkhorn.\n    pre_val_store = pl.create_tensor([t_linear, HC_PAD], dtype=pl.FP32)\n    # Only the final partial token tile uses these fixed-size staging buffers.\n    post_tail_store = pl.create_tensor([T_TILE, HC_PAD], dtype=pl.FP32)\n    for ob in pl.spmd(token_tiles, name_hint=\"split_pre_post\", allow_early_resolve=True):\n        t0 = ob * T_TILE\n        valid_rows = pl.min(T_TILE, t_dim - t0)\n        inv_col = inv_rms[t0:t0 + T_TILE, 0:1]\n\n        pre_base = pl.reshape(hc_base[0:HC_PAD], [1, HC_PAD])\n        pre_scaled = pl.mul(pl.row_expand_mul(mixes_raw[t0:t0 + T_TILE, 0:HC_PAD], inv_col), scale0)\n        pre_logits = pl.add(pre_scaled, pl.col_expand(pre_scaled, pre_base))\n        pre_sig = pl.recip(pl.add(pl.exp(pl.neg(pre_logits)), 1.0))\n        pre_val = pl.add(pre_sig, HC_EPS)\n        pre_val_store[t0:t0 + T_TILE, 0:HC_PAD] = pre_val\n\n        post_base = pl.reshape(hc_base[HC_MULT:HC_MULT + HC_PAD], [1, HC_PAD])\n        post_scaled = pl.mul(pl.row_expand_mul(mixes_raw[t0:t0 + T_TILE, HC_MULT:HC_MULT + HC_PAD], inv_col), scale1)\n        post_logits = pl.add(post_scaled, pl.col_expand(post_scaled, post_base))\n        post_sig = pl.recip(pl.add(pl.exp(pl.neg(post_logits)), 1.0))\n        post_pad = pl.mul(post_sig, 2.0)\n        if valid_rows == T_TILE:\n            post[t0:t0 + T_TILE, 0:HC_MULT] = pl.slice(post_pad, [T_TILE, HC_PAD], [0, 0], valid_shape=[T_TILE, HC_MULT])\n        else:\n            post_tail_store[0:T_TILE, 0:HC_PAD] = post_pad\n            post_tile = pl.load(post_tail_store, [0, 0], [T_TILE, HC_PAD], valid_shape=[valid_rows, HC_MULT], target_memory=pl.MemorySpace.Vec)\n            pl.store(post_tile, [t0, 0], post)\n\n    # comb_sinkhorn: comb gate from mixes_raw cols 8/12/16/20, softmax, then a\n    # column-first 20-iteration Sinkhorn -> comb.\n    comb_tail_store = pl.create_tensor([COMB_T_TILE, HC_PAD * HC_MULT], dtype=pl.FP32)\n    for ob in pl.spmd(token_tiles, name_hint=\"comb_sinkhorn\", allow_early_resolve=True):\n        t0 = ob * COMB_T_TILE\n        valid_rows = pl.min(COMB_T_TILE, t_dim - t0)\n        inv_col_t = pl.load(inv_rms, [t0, 0], [COMB_T_TILE, 1], valid_shape=[valid_rows, 1], target_memory=pl.MemorySpace.Vec)\n        comb_off = HC_MULT * 2\n        mix_g0 = pl.load(mixes_raw, [t0, comb_off + 0 * HC_MULT], [COMB_T_TILE, HC_PAD], valid_shape=[valid_rows, HC_MULT], target_memory=pl.MemorySpace.Vec)\n        mix_g1 = pl.load(mixes_raw, [t0, comb_off + 1 * HC_MULT], [COMB_T_TILE, HC_PAD], valid_shape=[valid_rows, HC_MULT], target_memory=pl.MemorySpace.Vec)\n        mix_g2 = pl.load(mixes_raw, [t0, comb_off + 2 * HC_MULT], [COMB_T_TILE, HC_PAD], valid_shape=[valid_rows, HC_MULT], target_memory=pl.MemorySpace.Vec)\n        mix_g3 = pl.load(mixes_raw, [t0, comb_off + 3 * HC_MULT], [COMB_T_TILE, HC_PAD], valid_shape=[valid_rows, HC_MULT], target_memory=pl.MemorySpace.Vec)\n        cb0 = pl.load(hc_base_2d, [0, comb_off + 0 * HC_MULT], [1, HC_PAD], valid_shape=[1, HC_MULT], target_memory=pl.MemorySpace.Vec)\n        cb1 = pl.load(hc_base_2d, [0, comb_off + 1 * HC_MULT], [1, HC_PAD], valid_shape=[1, HC_MULT], target_memory=pl.MemorySpace.Vec)\n        cb2 = pl.load(hc_base_2d, [0, comb_off + 2 * HC_MULT], [1, HC_PAD], valid_shape=[1, HC_MULT], target_memory=pl.MemorySpace.Vec)\n        cb3 = pl.load(hc_base_2d, [0, comb_off + 3 * HC_MULT], [1, HC_PAD], valid_shape=[1, HC_MULT], target_memory=pl.MemorySpace.Vec)\n        row0 = pl.add(pl.mul(pl.row_expand_mul(mix_g0, inv_col_t), scale2), pl.col_expand(mix_g0, cb0))\n        row1 = pl.add(pl.mul(pl.row_expand_mul(mix_g1, inv_col_t), scale2), pl.col_expand(mix_g1, cb1))\n        row2 = pl.add(pl.mul(pl.row_expand_mul(mix_g2, inv_col_t), scale2), pl.col_expand(mix_g2, cb2))\n        row3 = pl.add(pl.mul(pl.row_expand_mul(mix_g3, inv_col_t), scale2), pl.col_expand(mix_g3, cb3))\n        row0_p = pl.fillpad(row0, pad_value=pl.PadValue.min)\n        row1_p = pl.fillpad(row1, pad_value=pl.PadValue.min)\n        row2_p = pl.fillpad(row2, pad_value=pl.PadValue.min)\n        row3_p = pl.fillpad(row3, pad_value=pl.PadValue.min)\n\n        row_max_tmp = pl.create_tile([COMB_T_TILE, HC_PAD], dtype=pl.FP32, target_memory=pl.MemorySpace.Vec)\n        row_sum_tmp = pl.create_tile([COMB_T_TILE, HC_PAD], dtype=pl.FP32, target_memory=pl.MemorySpace.Vec)\n        row0_max = pl.row_max(row0_p, row_max_tmp)\n        row1_max = pl.row_max(row1_p, row_max_tmp)\n        row2_max = pl.row_max(row2_p, row_max_tmp)\n        row3_max = pl.row_max(row3_p, row_max_tmp)\n        row0_exp = pl.exp(pl.row_expand_sub(row0_p, row0_max))\n        row1_exp = pl.exp(pl.row_expand_sub(row1_p, row1_max))\n        row2_exp = pl.exp(pl.row_expand_sub(row2_p, row2_max))\n        row3_exp = pl.exp(pl.row_expand_sub(row3_p, row3_max))\n        row0_sum = pl.row_sum(row0_exp, row_sum_tmp)\n        row1_sum = pl.row_sum(row1_exp, row_sum_tmp)\n        row2_sum = pl.row_sum(row2_exp, row_sum_tmp)\n        row3_sum = pl.row_sum(row3_exp, row_sum_tmp)\n        row0_soft = pl.add(pl.row_expand_div(row0_exp, row0_sum), HC_EPS)\n        row1_soft = pl.add(pl.row_expand_div(row1_exp, row1_sum), HC_EPS)\n        row2_soft = pl.add(pl.row_expand_div(row2_exp, row2_sum), HC_EPS)\n        row3_soft = pl.add(pl.row_expand_div(row3_exp, row3_sum), HC_EPS)\n\n        row0_valid = pl.set_validshape(row0_soft, COMB_T_TILE, HC_MULT)\n        row1_valid = pl.set_validshape(row1_soft, COMB_T_TILE, HC_MULT)\n        row2_valid = pl.set_validshape(row2_soft, COMB_T_TILE, HC_MULT)\n        row3_valid = pl.set_validshape(row3_soft, COMB_T_TILE, HC_MULT)\n        row0_eff = pl.fillpad(row0_valid, pad_value=pl.PadValue.zero)\n        row1_eff = pl.fillpad(row1_valid, pad_value=pl.PadValue.zero)\n        row2_eff = pl.fillpad(row2_valid, pad_value=pl.PadValue.zero)\n        row3_eff = pl.fillpad(row3_valid, pad_value=pl.PadValue.zero)\n\n        row_sum_tmp_iter = pl.create_tile([COMB_T_TILE, HC_PAD], dtype=pl.FP32, target_memory=pl.MemorySpace.Vec)\n        col_sum = pl.add(pl.add(row0_eff, row1_eff), pl.add(row2_eff, row3_eff))\n        col_sum = pl.add(col_sum, HC_EPS)\n        row0_cur = pl.div(row0_eff, col_sum)\n        row1_cur = pl.div(row1_eff, col_sum)\n        row2_cur = pl.div(row2_eff, col_sum)\n        row3_cur = pl.div(row3_eff, col_sum)\n\n        for _sk_it in pl.pipeline(HC_SINKHORN_ITER - 1, stage=2):\n            row0_rowsum = pl.add(pl.row_sum(row0_cur, row_sum_tmp_iter), HC_EPS)\n            row1_rowsum = pl.add(pl.row_sum(row1_cur, row_sum_tmp_iter), HC_EPS)\n            row2_rowsum = pl.add(pl.row_sum(row2_cur, row_sum_tmp_iter), HC_EPS)\n            row3_rowsum = pl.add(pl.row_sum(row3_cur, row_sum_tmp_iter), HC_EPS)\n            row0_norm = pl.row_expand_div(row0_cur, row0_rowsum)\n            row1_norm = pl.row_expand_div(row1_cur, row1_rowsum)\n            row2_norm = pl.row_expand_div(row2_cur, row2_rowsum)\n            row3_norm = pl.row_expand_div(row3_cur, row3_rowsum)\n            col_sum = pl.add(pl.add(row0_norm, row1_norm), pl.add(row2_norm, row3_norm))\n            col_sum = pl.add(col_sum, HC_EPS)\n            row0_cur = pl.div(row0_norm, col_sum)\n            row1_cur = pl.div(row1_norm, col_sum)\n            row2_cur = pl.div(row2_norm, col_sum)\n            row3_cur = pl.div(row3_norm, col_sum)\n\n        if valid_rows == COMB_T_TILE:\n            row0_out = pl.set_validshape(row0_cur, COMB_T_TILE, HC_MULT)\n            row1_out = pl.set_validshape(row1_cur, COMB_T_TILE, HC_MULT)\n            row2_out = pl.set_validshape(row2_cur, COMB_T_TILE, HC_MULT)\n            row3_out = pl.set_validshape(row3_cur, COMB_T_TILE, HC_MULT)\n            pl.store(row0_out, [t0, 0 * HC_MULT], comb)\n            pl.store(row1_out, [t0, 1 * HC_MULT], comb)\n            pl.store(row2_out, [t0, 2 * HC_MULT], comb)\n            pl.store(row3_out, [t0, 3 * HC_MULT], comb)\n        else:\n            pl.store(row0_cur, [0, 0 * HC_PAD], comb_tail_store)\n            pl.store(row1_cur, [0, 1 * HC_PAD], comb_tail_store)\n            pl.store(row2_cur, [0, 2 * HC_PAD], comb_tail_store)\n            pl.store(row3_cur, [0, 3 * HC_PAD], comb_tail_store)\n            row0_tail = pl.load(comb_tail_store, [0, 0 * HC_PAD], [COMB_T_TILE, HC_PAD], valid_shape=[valid_rows, HC_MULT], target_memory=pl.MemorySpace.Vec)\n            row1_tail = pl.load(comb_tail_store, [0, 1 * HC_PAD], [COMB_T_TILE, HC_PAD], valid_shape=[valid_rows, HC_MULT], target_memory=pl.MemorySpace.Vec)\n            row2_tail = pl.load(comb_tail_store, [0, 2 * HC_PAD], [COMB_T_TILE, HC_PAD], valid_shape=[valid_rows, HC_MULT], target_memory=pl.MemorySpace.Vec)\n            row3_tail = pl.load(comb_tail_store, [0, 3 * HC_PAD], [COMB_T_TILE, HC_PAD], valid_shape=[valid_rows, HC_MULT], target_memory=pl.MemorySpace.Vec)\n            pl.store(row0_tail, [t0, 0 * HC_MULT], comb)\n            pl.store(row1_tail, [t0, 1 * HC_MULT], comb)\n            pl.store(row2_tail, [t0, 2 * HC_MULT], comb)\n            pl.store(row3_tail, [t0, 3 * HC_MULT], comb)\n\n    # mix_x: x_mixed = sum_h pre[:,h]*x[:,h,:], fanned over D/D_SPMD blocks per token tile.\n    x_mixed_tail_store = pl.create_tensor([T_TILE, D], dtype=pl.BF16)\n    for blk in pl.spmd(token_tiles * (D // D_SPMD), name_hint=\"mix_x\", allow_early_resolve=True):\n        t0 = (blk // (D // D_SPMD)) * T_TILE\n        d_base = (blk % (D // D_SPMD)) * D_SPMD\n        valid_rows = pl.min(T_TILE, t_dim - t0)\n        pre_tile_t = pl.transpose(pre_val_store[t0:t0 + T_TILE, 0:HC_PAD], axis1=0, axis2=1)\n        pre0 = pl.reshape(pre_tile_t[0:1, 0:T_TILE], [T_TILE, 1])\n        pre1 = pl.reshape(pre_tile_t[1:2, 0:T_TILE], [T_TILE, 1])\n        pre2 = pl.reshape(pre_tile_t[2:3, 0:T_TILE], [T_TILE, 1])\n        pre3 = pl.reshape(pre_tile_t[3:4, 0:T_TILE], [T_TILE, 1])\n        for db in pl.pipeline(D_SPMD // D_TILE, stage=2):\n            d0 = d_base + db * D_TILE\n            x0 = pl.slice(x_flat, [T_TILE, D_TILE], [t0, 0 * D + d0], valid_shape=[valid_rows, D_TILE])\n            x1 = pl.slice(x_flat, [T_TILE, D_TILE], [t0, 1 * D + d0], valid_shape=[valid_rows, D_TILE])\n            x2 = pl.slice(x_flat, [T_TILE, D_TILE], [t0, 2 * D + d0], valid_shape=[valid_rows, D_TILE])\n            x3 = pl.slice(x_flat, [T_TILE, D_TILE], [t0, 3 * D + d0], valid_shape=[valid_rows, D_TILE])\n            y0 = pl.row_expand_mul(x0, pre0)\n            y1 = pl.row_expand_mul(x1, pre1)\n            y2 = pl.row_expand_mul(x2, pre2)\n            y3 = pl.row_expand_mul(x3, pre3)\n            y_tile = pl.add(pl.add(y0, y1), pl.add(y2, y3))\n            y_bf16 = pl.cast(y_tile, target_type=pl.BF16, mode=\"rint\")\n            if valid_rows == T_TILE:\n                x_mixed[t0:t0 + T_TILE, d0:d0 + D_TILE] = y_bf16\n            else:\n                x_mixed_tail_store[0:T_TILE, d0:d0 + D_TILE] = y_bf16\n                y_out = pl.load(x_mixed_tail_store, [0, d0], [T_TILE, D_TILE], valid_shape=[valid_rows, D_TILE], target_memory=pl.MemorySpace.Vec)\n                pl.store(y_out, [t0, d0], x_mixed)\n    return x_mixed\n\n\n\n\n@pl.jit\ndef hc_pre_test(\n    x: pl.Tensor[[T_DYN, HC_MULT, D], pl.FP32],\n    hc_fn: pl.Tensor[[MIX_HC, HC_DIM], pl.FP32],\n    hc_scale: pl.Tensor[[3], pl.FP32],\n    hc_base: pl.Tensor[[MIX_HC], pl.FP32],\n    x_mixed: pl.Out[pl.Tensor[[T_DYN, D], pl.BF16]],\n    post: pl.Out[pl.Tensor[[T_DYN, HC_MULT], pl.FP32]],\n    comb: pl.Out[pl.Tensor[[T_DYN, HC_MULT * HC_MULT], pl.FP32]],\n):\n    x.bind_dynamic(0, T_DYN)\n    x_mixed.bind_dynamic(0, T_DYN)\n    post.bind_dynamic(0, T_DYN)\n    comb.bind_dynamic(0, T_DYN)\n\n    hc_pre(x, hc_fn, hc_scale, hc_base, x_mixed, post, comb)\n    return x_mixed\n\n\ndef _golden_a2a3_cube_linear(x_flat_2d, hc_fn):\n    \"\"\"Emulate the A2/A3 f32 Cube MAD reduction used by the HC projection.\"\"\"\n    import torch\n\n    cube_acc_k = 4\n    group_block = 64\n    assert LINEAR_K_PER_SPLIT % cube_acc_k == 0\n    groups_per_split = LINEAR_K_PER_SPLIT // cube_acc_k\n\n    t_dim = x_flat_2d.shape[0]\n    x_groups = x_flat_2d.reshape(t_dim, 1, LINEAR_OK, groups_per_split, cube_acc_k)\n    w_groups = hc_fn.reshape(1, MIX_HC, LINEAR_OK, groups_per_split, cube_acc_k)\n    split_mixes = torch.zeros(t_dim, MIX_HC, LINEAR_OK, dtype=torch.float32)\n    for group0 in range(0, groups_per_split, group_block):\n        x_block = x_groups[..., group0:group0 + group_block, :].double()\n        w_block = w_groups[..., group0:group0 + group_block, :].double()\n        group_dots = (x_block * w_block).sum(dim=-1)\n        for group in range(group_dots.shape[-1]):\n            split_mixes = (split_mixes.double() + group_dots[..., group]).float()\n\n    # Match the kernel's ascending split order.\n    mixes = torch.zeros(t_dim, MIX_HC, dtype=torch.float32)\n    for split in range(LINEAR_OK):\n        mixes += split_mixes[..., split]\n    return mixes\n\n\ndef golden_hc_pre(tensors):\n    \"\"\"Torch reference matching the target HC-pre reduction and nonlinearities.\"\"\"\n    import torch\n\n    x = tensors[\"x\"].float()  # [T, hc, D]\n    hc_fn = tensors[\"hc_fn\"].float()  # [mix_hc, hc*D]\n    hc_scale = tensors[\"hc_scale\"].float()  # [3]\n    hc_base = tensors[\"hc_base\"].float()  # [mix_hc]\n\n    t_dim = x.shape[0]\n    x_flat_2d = x.reshape(t_dim, HC_DIM)\n\n    sq_sum = torch.zeros(t_dim, 1, dtype=torch.float32)\n    for k0 in range(0, HC_DIM, RMS_K_TILE):\n        x_chunk = x_flat_2d[:, k0:k0 + RMS_K_TILE]\n        sq_sum += (x_chunk * x_chunk).sum(dim=1, keepdim=True)\n    rsqrt = torch.rsqrt(sq_sum * HC_DIM_INV + NORM_EPS)\n\n    # A2/A3 f32 Cube MAD accumulates four consecutive products before rounding\n    # the updated accumulator to FP32.  Reproduce that target-defined reduction\n    # instead of using Torch's different reduction tree.\n    mixes = _golden_a2a3_cube_linear(x_flat_2d, hc_fn)\n    mixes *= rsqrt\n\n    pre = torch.sigmoid(mixes[..., :HC_MULT] * hc_scale[0] + hc_base[:HC_MULT]) + HC_EPS\n    post_t = 2 * torch.sigmoid(mixes[..., HC_MULT:HC_MULT * 2] * hc_scale[1]\n                               + hc_base[HC_MULT:HC_MULT * 2])\n    comb_t = (mixes[..., HC_MULT * 2:] * hc_scale[2] + hc_base[HC_MULT * 2:]\n              ).view(t_dim, HC_MULT, HC_MULT)\n\n    comb_t = torch.softmax(comb_t, dim=-1) + HC_EPS\n    comb_t = comb_t / (comb_t.sum(-2, keepdim=True) + HC_EPS)\n    for _ in range(HC_SINKHORN_ITER - 1):\n        comb_t = comb_t / (comb_t.sum(-1, keepdim=True) + HC_EPS)\n        comb_t = comb_t / (comb_t.sum(-2, keepdim=True) + HC_EPS)\n\n    y0 = x[:, 0, :] * pre[:, 0:1]\n    y1 = x[:, 1, :] * pre[:, 1:2]\n    y2 = x[:, 2, :] * pre[:, 2:3]\n    y3 = x[:, 3, :] * pre[:, 3:4]\n    y = (y0 + y1) + (y2 + y3)\n\n    # Match the kernel's mode=\"rint\" cast (round to nearest, ties to even).\n    tensors[\"x_mixed\"][:] = y.to(torch.bfloat16).reshape(t_dim, D)\n    tensors[\"post\"][:] = post_t.reshape(t_dim, HC_MULT)\n    tensors[\"comb\"][:] = comb_t.reshape(t_dim, HC_MULT * HC_MULT)\n\n\ndef build_tensor_specs(B, S):\n    import torch\n    from golden import TensorSpec\n\n    T = B * S\n\n    # hc_fn / hc_scale / hc_base copied from DeepSeek-V4-Flash-0731 layer 8.\n    def init_x():\n        return torch.randn(T, HC_MULT, D) * 0.05\n    def init_hc_fn():\n        return torch.randn(MIX_HC, HC_DIM) * 0.0509\n    def init_hc_scale():\n        return torch.tensor([0.075997, 0.032345, 0.226238])\n    def init_hc_base():\n        return torch.tensor([\n            5.9169, -3.6226, -2.9309, -3.3122,\n            -3.9082, -0.9381, -3.3257, -2.5300,\n            2.0703, -2.5724, 0.1430, -3.9461,\n            -3.8868, 3.4623, -3.3815, -2.6056,\n            -2.7185, -2.4849, 2.0391, -0.4999,\n            -3.5994, -2.7508, -3.3496, 3.1573,\n        ])\n\n    return [\n        TensorSpec(\"x\", [T, HC_MULT, D], torch.float32, init_value=init_x),\n        TensorSpec(\"hc_fn\", [MIX_HC, HC_DIM], torch.float32, init_value=init_hc_fn),\n        TensorSpec(\"hc_scale\", [3], torch.float32, init_value=init_hc_scale),\n        TensorSpec(\"hc_base\", [MIX_HC], torch.float32, init_value=init_hc_base),\n        TensorSpec(\"x_mixed\", [T, D], torch.bfloat16),\n        TensorSpec(\"post\", [T, HC_MULT], torch.float32),\n        TensorSpec(\"comb\", [T, HC_MULT * HC_MULT], torch.float32),\n    ]\n\n\nif __name__ == \"__main__\":\n    import argparse\n    from golden import ratio_allclose, run\n\n    MODES = {\n        \"decode\":  (DECODE_BATCH // TP, DECODE_SEQ),\n        \"prefill\": (PREFILL_BATCH, PREFILL_SEQ),\n    }\n\n    parser = argparse.ArgumentParser()\n    parser.add_argument(\"-p\", \"--platform\", type=str, default=\"a2a3\", choices=[\"a2a3\", \"a2a3sim\", \"a5\", \"a5sim\"])\n    parser.add_argument(\"-d\", \"--device\", type=int, default=0)\n    parser.add_argument(\"--mode\", choices=[\"decode\", \"prefill\", \"all\"], default=\"all\", help=\"decode / prefill batch sizes, or both.\")\n    parser.add_argument(\"--enable-chip-swimlane\", action=\"store_true\", default=False)\n    parser.add_argument(\"--runtime-dir\", type=str, default=None)\n    parser.add_argument(\"--golden-data\", type=str, default=None)\n    parser.add_argument(\"--compile-only\", action=\"store_true\", default=False)\n    parser.add_argument(\"--dump-passes\", action=\"store_true\", default=False)\n    args = parser.parse_args()\n\n    modes_to_run = list(MODES.keys()) if args.mode == \"all\" else [args.mode]\n\n    for mode_name in modes_to_run:\n        B, S = MODES[mode_name]\n        print(f\"--- hc_pre {mode_name}: B={B}, S={S} ---\")\n        result = run(\n            fn=hc_pre_test,\n            specs=build_tensor_specs(B, S),\n            golden_fn=golden_hc_pre,\n            runtime_dir=args.runtime_dir,\n            golden_data=args.golden_data,\n            compile_cfg=dict(dump_passes=args.dump_passes),\n            runtime_cfg=dict(\n                platform=args.platform,\n                device_id=args.device,\n                enable_chip_swimlane=args.enable_chip_swimlane,\n            ),\n            rtol=1e-3,\n            atol=1e-3,\n            compare_fn={\n                \"x_mixed\": ratio_allclose(atol=1e-4, rtol=1.0 / 128),\n                \"post\":    ratio_allclose(atol=2.5e-5, rtol=5e-3),\n                \"comb\":    ratio_allclose(atol=2.5e-5, rtol=5e-3),\n            },\n            compile_only=args.compile_only,\n        )\n        if not result.passed:\n            if result.error:\n                print(result.error)\n            raise SystemExit(1)\n", "hc_post.py": "# Copyright (c) PyPTO Contributors.\n# This program is free software, you can redistribute it and/or modify it under the terms and conditions of\n# CANN Open Software License Agreement Version 2.0 (the \"License\").\n# Please refer to the License for details. You may not use this file except in compliance with the License.\n# THIS SOFTWARE IS PROVIDED ON AN \"AS IS\" BASIS, WITHOUT WARRANTIES OF ANY KIND, EITHER EXPRESS OR IMPLIED,\n# INCLUDING BUT NOT LIMITED TO NON-INFRINGEMENT, MERCHANTABILITY, OR FITNESS FOR A PARTICULAR PURPOSE.\n# See LICENSE in the root of the software repository for the full text of the License.\n# -----------------------------------------------------------------------------------------------------------\n\"\"\"DeepSeek-V4 Hyper-Connections post-mix (dynamic shape): combines a sublayer\noutput with its hc-residual into the next hc-stack via post and comb weights.\nSupports both decode and prefill batch/sequence sizes via dynamic-shape tensors.\"\"\"\n\n# ``hc_post`` processes a dynamic tensor whose rows are all valid (decode/MoE).\n# ``hc_post_prefill`` processes only the active prefix of a static prefill tensor\n# and deterministically zero-fills its inactive tail.\n\nimport pypto.language as pl\n\nfrom config import FLASH as M, DECODE_BATCH, DECODE_SEQ, TP, PREFILL_BATCH, PREFILL_SEQ\n\n# Dynamic shape variables.\nT_DYN = pl.dynamic(\"T_DYN\")  # T = B * S\n\n# model config\nD = M.hidden_size\nHC_MULT = M.hc_mult\nHC_DIM = M.hc_dim\n\n# tiling\nT_TILE = 4\nINACTIVE_FILL_T_TILE = 16\nINACTIVE_FILL_D_TILE = 256\nassert (DECODE_BATCH // TP * DECODE_SEQ) % T_TILE == 0\nassert (PREFILL_BATCH * PREFILL_SEQ) % T_TILE == 0\n\n\n@pl.jit.inline\ndef hc_post(\n    x: pl.Tensor[[T_DYN, D], pl.BF16],\n    residual: pl.Tensor[[T_DYN, HC_MULT, D], pl.FP32],\n    post: pl.Tensor[[T_DYN, HC_MULT], pl.FP32],\n    comb: pl.Tensor[[T_DYN, HC_MULT * HC_MULT], pl.FP32],\n    y: pl.Out[pl.Tensor[[T_DYN, HC_MULT, D], pl.FP32]],\n):\n    t_dim = pl.tensor.dim(x, 0)\n\n    residual_flat = pl.reshape(residual, [t_dim, HC_DIM])\n    y_flat = pl.reshape(y, [t_dim, HC_DIM])\n\n    token_tiles = (t_dim + T_TILE - 1) // T_TILE\n    for token_block in pl.spmd(token_tiles, name_hint=\"hc_post\"):\n        t0 = token_block * T_TILE\n        for t in pl.pipeline(t0, t0 + T_TILE, stage=2):\n            if t < t_dim:\n                # One cast per token: all HC_MULT outputs share the x row.\n                x_row = pl.cast(x[t : t + 1, 0:D], target_type=pl.FP32)\n                for out_h in pl.unroll(HC_MULT):\n                    post_w = pl.read(post, [t, out_h])\n                    y_row = pl.mul(x_row, post_w)\n                    for in_h in pl.pipeline(HC_MULT, stage=4):\n                        comb_w = pl.read(comb, [t, in_h * HC_MULT + out_h])\n                        res_d = in_h * D\n                        # residual is already FP32 (hc stream is FP32 end-to-end): no cast, read straight.\n                        res_row = residual_flat[t : t + 1, res_d : res_d + D]\n                        weighted = pl.mul(res_row, comb_w)\n                        y_row = pl.add(y_row, weighted)\n                    # y is FP32 (feeds the next layer's hc_pre directly): no BF16 output cast.\n                    y_flat[t : t + 1, out_h * D : out_h * D + D] = y_row\n    return y\n\n\n@pl.jit.inline\ndef hc_post_prefill(\n    x: pl.Tensor[[T_DYN, D], pl.BF16],\n    residual: pl.Tensor[[T_DYN, HC_MULT, D], pl.FP32],\n    post: pl.Tensor[[T_DYN, HC_MULT], pl.FP32],\n    comb: pl.Tensor[[T_DYN, HC_MULT * HC_MULT], pl.FP32],\n    y: pl.Out[pl.Tensor[[T_DYN, HC_MULT, D], pl.FP32]],\n    num_tokens: pl.Scalar[pl.INT32],\n):\n    \"\"\"Compute prefill active rows and deterministically pad the static tail.\"\"\"\n    t_dim = pl.tensor.dim(x, 0)\n    active_tokens = pl.cast(num_tokens, pl.INDEX)\n    if active_tokens < 0:\n        active_tokens = pl.cast(0, pl.INDEX)\n    if active_tokens > t_dim:\n        active_tokens = t_dim\n\n    residual_flat = pl.reshape(residual, [t_dim, HC_DIM])\n    y_flat = pl.reshape(y, [t_dim, HC_DIM])\n    active_tiles = (active_tokens + T_TILE - 1) // T_TILE\n\n    if active_tokens > 0:\n        for block in pl.spmd(active_tiles * HC_MULT, name_hint=\"hc_post_prefill\"):\n            token_block = block // HC_MULT\n            out_h = block % HC_MULT\n            t0 = token_block * T_TILE\n            for t in pl.pipeline(t0, t0 + T_TILE, stage=2):\n                if t < active_tokens:\n                    post_w = pl.read(post, [t, out_h])\n                    x_row = pl.cast(x[t : t + 1, 0:D], target_type=pl.FP32)\n                    y_row = pl.mul(x_row, post_w)\n                    for in_h in pl.pipeline(HC_MULT, stage=4):\n                        comb_w = pl.read(comb, [t, in_h * HC_MULT + out_h])\n                        res_d = in_h * D\n                        res_row = residual_flat[t : t + 1, res_d : res_d + D]\n                        y_row = pl.add(y_row, pl.mul(res_row, comb_w))\n                    y_flat[t : t + 1, out_h * D : out_h * D + D] = y_row\n\n    inactive_tokens = t_dim - active_tokens\n    if inactive_tokens > 0:\n        inactive_tiles = (inactive_tokens + INACTIVE_FILL_T_TILE - 1) // INACTIVE_FILL_T_TILE\n        for fill_block in pl.spmd(inactive_tiles * HC_MULT, name_hint=\"hc_post_inactive_pad\"):\n            fill_tile = fill_block // HC_MULT\n            out_h = fill_block % HC_MULT\n            fill_t0 = active_tokens + fill_tile * INACTIVE_FILL_T_TILE\n            zero = pl.full([1, INACTIVE_FILL_D_TILE], dtype=pl.FP32, value=0.0)\n            for fill_dt in pl.range(INACTIVE_FILL_T_TILE):\n                fill_t = fill_t0 + fill_dt\n                if fill_t < t_dim:\n                    for fill_d0 in pl.range(0, D, INACTIVE_FILL_D_TILE):\n                        out_d0 = out_h * D + fill_d0\n                        y_flat[fill_t : fill_t + 1, out_d0 : out_d0 + INACTIVE_FILL_D_TILE] = zero\n    return y\n\n\n@pl.jit\ndef hc_post_test(\n    x: pl.Tensor[[T_DYN, D], pl.BF16],\n    residual: pl.Tensor[[T_DYN, HC_MULT, D], pl.FP32],\n    post: pl.Tensor[[T_DYN, HC_MULT], pl.FP32],\n    comb: pl.Tensor[[T_DYN, HC_MULT * HC_MULT], pl.FP32],\n    y: pl.Out[pl.Tensor[[T_DYN, HC_MULT, D], pl.FP32]],\n):\n    x.bind_dynamic(0, T_DYN)\n    residual.bind_dynamic(0, T_DYN)\n    post.bind_dynamic(0, T_DYN)\n    comb.bind_dynamic(0, T_DYN)\n    y.bind_dynamic(0, T_DYN)\n\n    hc_post(x, residual, post, comb, y)\n    return y\n\n\ndef golden_hc_post(tensors):\n    \"\"\"Torch reference, direct port of model.py Block.hc_post 684-687.\"\"\"\n    import torch\n\n    x        = tensors[\"x\"].float()\n    residual = tensors[\"residual\"].float()\n    post     = tensors[\"post\"].float()\n    comb     = tensors[\"comb\"].float().reshape(-1, HC_MULT, HC_MULT)  # [B, S, HC, HC]\n\n    T = x.shape[0]\n    y_fp32 = torch.zeros(T, HC_MULT, D, dtype=torch.float32)\n    for out_h in range(HC_MULT):\n        y_row = x * post[:, out_h:out_h + 1]\n        for in_h in range(HC_MULT):\n            y_row = y_row + residual[:, in_h, :] * comb[:, in_h, out_h:out_h + 1]\n        y_fp32[:, out_h, :] = y_row\n    y = y_fp32  # hc residual stream is FP32 end-to-end: no BF16 rounding\n\n    tensors[\"y\"][:] = y\n\n\ndef golden_hc_post_prefill(tensors):\n    \"\"\"Prefill reference: compute active rows and zero the static tail.\"\"\"\n    golden_hc_post(tensors)\n    num_tokens = int(tensors[\"num_tokens\"])\n    tensors[\"y\"][num_tokens:] = 0\n\n\ndef build_tensor_specs(B, S):\n    import torch\n    from golden import TensorSpec\n\n    T = B * S\n\n    def init_x():\n        return torch.randn(T, D) * 0.05\n    def init_residual():\n        return torch.randn(T, HC_MULT, D) * 0.05\n    def init_post():\n        return 2.0 * torch.sigmoid(torch.randn(T, HC_MULT))\n    def init_comb():\n        c = torch.rand(B, S, HC_MULT, HC_MULT) + 0.1\n        return (c / c.sum(dim=-1, keepdim=True)).reshape(T, HC_MULT * HC_MULT)\n    return [\n        TensorSpec(\"x\",        [T, D],                    torch.bfloat16, init_value=init_x),\n        TensorSpec(\"residual\", [T, HC_MULT, D],           torch.float32,  init_value=init_residual),\n        TensorSpec(\"post\",     [T, HC_MULT],              torch.float32,  init_value=init_post),\n        TensorSpec(\"comb\",     [T, HC_MULT * HC_MULT],    torch.float32,  init_value=init_comb),\n        TensorSpec(\"y\",        [T, HC_MULT, D],           torch.float32),\n    ]\n\n\nif __name__ == \"__main__\":\n    import argparse\n    from golden import run\n\n    MODES = {\n        \"decode\":  (DECODE_BATCH // TP, DECODE_SEQ),\n        \"prefill\": (PREFILL_BATCH, PREFILL_SEQ),\n    }\n\n    parser = argparse.ArgumentParser()\n    parser.add_argument(\"-p\", \"--platform\", type=str, default=\"a2a3\",\n                        choices=[\"a2a3\", \"a2a3sim\", \"a5\", \"a5sim\"])\n    parser.add_argument(\"-d\", \"--device\", type=int, default=0)\n    parser.add_argument(\"--mode\", choices=[\"decode\", \"prefill\", \"all\"], default=\"decode\",\n                        help=\"Use decode or prefill batch sizes, or 'all' to test both.\")\n    parser.add_argument(\"--enable-chip-swimlane\", type=int, nargs=\"?\", const=1, default=0, choices=(0, 1, 2))\n    parser.add_argument(\"--compile-only\", action=\"store_true\", default=False)\n    parser.add_argument(\"--dump-passes\", action=\"store_true\", default=False)\n    args = parser.parse_args()\n\n    modes_to_run = list(MODES.keys()) if args.mode == \"all\" else [args.mode]\n\n    for mode_name in modes_to_run:\n        B, S = MODES[mode_name]\n        print(f\"--- hc_post {mode_name}: B={B}, S={S} ---\")\n        result = run(\n            fn=hc_post_test,\n            specs=build_tensor_specs(B, S),\n            golden_fn=golden_hc_post,\n            compile_cfg=dict(dump_passes=args.dump_passes),\n            runtime_cfg=dict(\n                platform=args.platform,\n                device_id=args.device,\n                enable_chip_swimlane=args.enable_chip_swimlane,\n            ),\n            rtol=1e-3,\n            atol=1e-3,\n            compile_only=args.compile_only,\n        )\n        if not result.passed:\n            if result.error:\n                print(result.error)\n            raise SystemExit(1)\n", "rmsnorm.py": "# Copyright (c) PyPTO Contributors.\n# This program is free software, you can redistribute it and/or modify it under the terms and conditions of\n# CANN Open Software License Agreement Version 2.0 (the \"License\").\n# Please refer to the License for details. You may not use this file except in compliance with the License.\n# THIS SOFTWARE IS PROVIDED ON AN \"AS IS\" BASIS, WITHOUT WARRANTIES OF ANY KIND, EITHER EXPRESS OR IMPLIED,\n# INCLUDING BUT NOT LIMITED TO NON-INFRINGEMENT, MERCHANTABILITY, OR FITNESS FOR A PARTICULAR PURPOSE.\n# See LICENSE in the root of the software repository for the full text of the License.\n# -----------------------------------------------------------------------------------------------------------\n\"\"\"DeepSeek-V4 attention RMSNorm (dynamic shape): normalizes token-major\nactivations for both decode and prefill attention paths.\"\"\"\n\nimport pypto.language as pl\n\nfrom config import FLASH as M, DECODE_BATCH, DECODE_SEQ, TP, PREFILL_BATCH, PREFILL_SEQ\n\n\n# Dynamic shape variables.\nT_DYN = pl.dynamic(\"RMS_NORM_T_DYN\")  # T = B * S\n\n\n# model config\nD = M.hidden_size\nEPS = M.rms_norm_eps\n\n# tiling\nD_TILE = 128\nT_TILE = 8\nassert D % D_TILE == 0, \"D must be divisible by D_TILE\"\nassert (DECODE_BATCH // TP * DECODE_SEQ) % T_TILE == 0\nassert (PREFILL_BATCH * PREFILL_SEQ) % T_TILE == 0\n\n\n@pl.jit.inline\ndef _rms_norm_full_tile(\n    x: pl.Tensor[[T_DYN, D], pl.BF16],\n    norm_w: pl.Tensor[[D], pl.BF16],\n    x_normed: pl.Tensor[[T_DYN, D], pl.BF16],\n):\n    \"\"\"Run the aligned token tile through the existing Tensor-level dataflow.\"\"\"\n    tg = pl.tile.get_block_idx() * T_TILE\n    x_sq_sum = pl.full([1, T_TILE], dtype=pl.FP32, value=0.0)\n    for rms_db in pl.pipeline(D // D_TILE, stage=2):\n        rms_d0 = rms_db * D_TILE\n        rms_x_input = x[tg : tg + T_TILE, rms_d0 : rms_d0 + D_TILE]\n        rms_x_chunk = pl.cast(rms_x_input, target_type=pl.FP32)\n        rms_x_sq = pl.mul(rms_x_chunk, rms_x_chunk)\n        rms_x_row_sum = pl.reshape(pl.row_sum(rms_x_sq), [1, T_TILE])\n        x_sq_sum = pl.add(x_sq_sum, rms_x_row_sum)\n    x_inv_rms = pl.rsqrt(pl.add(pl.mul(x_sq_sum, 1.0 / D), EPS), high_precision=True)\n    x_inv_rms_t = pl.reshape(x_inv_rms, [T_TILE, 1])\n    for apply_db in pl.pipeline(D // D_TILE, stage=2):\n        apply_d0 = apply_db * D_TILE\n        apply_x_input = x[tg : tg + T_TILE, apply_d0 : apply_d0 + D_TILE]\n        apply_x_chunk = pl.cast(apply_x_input, target_type=pl.FP32)\n        norm_w_input = norm_w[apply_d0 : apply_d0 + D_TILE]\n        norm_w_chunk = pl.cast(pl.reshape(norm_w_input, [1, D_TILE]), pl.FP32)\n        x_scaled = pl.row_expand_mul(apply_x_chunk, x_inv_rms_t)\n        x_normed_chunk = pl.col_expand_mul(x_scaled, norm_w_chunk)\n        x_normed[tg : tg + T_TILE, apply_d0 : apply_d0 + D_TILE] = pl.cast(\n            x_normed_chunk,\n            target_type=pl.BF16,\n            mode=\"rint\",\n        )\n\n\n@pl.jit.inline\ndef _rms_norm_tail_tile(\n    x: pl.Tensor[[T_DYN, D], pl.BF16],\n    norm_w: pl.Tensor[[D], pl.BF16],\n    x_normed: pl.Tensor[[T_DYN, D], pl.BF16],\n):\n    \"\"\"Run the ragged last token tile through explicit `valid_shape` load/store.\n\n    Step for step the same RMSNorm as `_rms_norm_full_tile`. The two live in\n    separate scopes rather than in one `if`/`else` body because this path binds\n    the shared names (`x_sq_sum`, `x_inv_rms`, …) to Vec-space Tiles while the\n    aligned path binds them to Tensors, and a name cannot be rebound to a\n    different type inside one kernel.\n    \"\"\"\n    tg = pl.tile.get_block_idx() * T_TILE\n    valid_rows = pl.min(T_TILE, pl.tensor.dim(x, 0) - tg)\n    row_reduce_tmp = pl.create_tile([T_TILE, D_TILE], dtype=pl.FP32, target_memory=pl.MemorySpace.Vec)\n    x_sq_sum = pl.tile.full([1, T_TILE], dtype=pl.FP32, value=0.0)\n    for rms_db in pl.pipeline(D // D_TILE, stage=2):\n        rms_d0 = rms_db * D_TILE\n        rms_x_input = pl.load(\n            x,\n            [tg, rms_d0],\n            [T_TILE, D_TILE],\n            valid_shape=[valid_rows, D_TILE],\n            target_memory=pl.MemorySpace.Vec,\n        )\n        rms_x_chunk = pl.cast(rms_x_input, target_type=pl.FP32)\n        rms_x_sq = pl.mul(rms_x_chunk, rms_x_chunk)\n        rms_x_row_sum = pl.reshape(pl.row_sum(rms_x_sq, row_reduce_tmp), [1, T_TILE])\n        x_sq_sum = pl.add(x_sq_sum, rms_x_row_sum)\n    x_inv_rms = pl.recip(pl.sqrt(pl.add(pl.mul(x_sq_sum, 1.0 / D), EPS)))\n    x_inv_rms_t = pl.reshape(x_inv_rms, [T_TILE, 1])\n    for apply_db in pl.pipeline(D // D_TILE, stage=2):\n        apply_d0 = apply_db * D_TILE\n        apply_x_input = pl.load(\n            x,\n            [tg, apply_d0],\n            [T_TILE, D_TILE],\n            valid_shape=[valid_rows, D_TILE],\n            target_memory=pl.MemorySpace.Vec,\n        )\n        apply_x_chunk = pl.cast(apply_x_input, target_type=pl.FP32)\n        norm_w_input = pl.load(norm_w, [apply_d0], [D_TILE], target_memory=pl.MemorySpace.Vec)\n        norm_w_chunk = pl.cast(pl.reshape(norm_w_input, [1, D_TILE]), pl.FP32)\n        x_scaled = pl.row_expand_mul(apply_x_chunk, x_inv_rms_t)\n        x_normed_chunk = pl.col_expand_mul(x_scaled, norm_w_chunk)\n        x_normed_bf16 = pl.cast(x_normed_chunk, target_type=pl.BF16, mode=\"rint\")\n        x_normed_valid = pl.set_validshape(x_normed_bf16, valid_rows, D_TILE)\n        pl.store(x_normed_valid, [tg, apply_d0], x_normed)\n\n\n@pl.jit.inline\ndef rms_norm(\n    x: pl.Tensor[[T_DYN, D], pl.BF16],\n    norm_w: pl.Tensor[[D], pl.BF16],\n    x_normed: pl.Tensor[[T_DYN, D], pl.BF16],\n):\n    t_dim = pl.tensor.dim(x, 0)\n    # Capture form (not `for ... in pl.spmd`): callers need the producer TaskId to\n    # hang a `pl.system.task_dummy` barrier off it and defer non-critical consumers.\n    token_tiles = (t_dim + T_TILE - 1) // T_TILE\n    with pl.spmd(token_tiles, name_hint=\"rms_norm\", allow_early_resolve=True) as rms_tid:\n        tg_idx = pl.tile.get_block_idx()\n        tg = tg_idx * T_TILE\n        valid_rows = pl.min(T_TILE, t_dim - tg)\n        if valid_rows == T_TILE:\n            _rms_norm_full_tile(x, norm_w, x_normed)\n        else:\n            _rms_norm_tail_tile(x, norm_w, x_normed)\n\n    return rms_tid\n\n\n@pl.jit\ndef rms_norm_test(\n    x: pl.Tensor[[T_DYN, D], pl.BF16],\n    norm_w: pl.Tensor[[D], pl.BF16],\n    x_normed: pl.Out[pl.Tensor[[T_DYN, D], pl.BF16]],\n):\n    x.bind_dynamic(0, T_DYN)\n    x_normed.bind_dynamic(0, T_DYN)\n\n    rms_norm(x, norm_w, x_normed)\n    return x_normed\n\n\ndef golden_rms_norm(x, norm_w):\n    import torch\n\n    x = x.float()\n    norm_w = norm_w.float()\n    inv = torch.rsqrt(x.square().mean(-1, keepdim=True) + EPS)\n    return (x * inv * norm_w).to(torch.bfloat16)\n\n\ndef golden_rms_norm_test(tensors):\n    tensors[\"x_normed\"][:] = golden_rms_norm(tensors[\"x\"], tensors[\"norm_w\"])\n\n\ndef build_tensor_specs(B, S):\n    import torch\n    from golden import TensorSpec\n\n    T = B * S\n\n    def init_x():\n        return torch.randn(T, D) - 0.5\n\n    def init_norm_w():\n        return torch.randn(D) * 0.1 + 1.0\n\n    return [\n        TensorSpec(\"x\", [T, D], torch.bfloat16, init_value=init_x),\n        TensorSpec(\"norm_w\", [D], torch.bfloat16, init_value=init_norm_w),\n        TensorSpec(\"x_normed\", [T, D], torch.bfloat16),\n    ]\n\n\nif __name__ == \"__main__\":\n    import argparse\n    from golden import ratio_allclose, run\n\n    MODES = {\n        \"decode\":  (DECODE_BATCH // TP, DECODE_SEQ),\n        \"prefill\": (PREFILL_BATCH, PREFILL_SEQ),\n    }\n\n    parser = argparse.ArgumentParser(description=\"Standalone DeepSeek V4 attention RMSNorm validation.\")\n    parser.add_argument(\"-p\", \"--platform\", type=str, default=\"a2a3\", choices=[\"a2a3\", \"a2a3sim\", \"a5\", \"a5sim\"])\n    parser.add_argument(\"-d\", \"--device\", type=int, default=0)\n    parser.add_argument(\"--mode\", choices=[\"decode\", \"prefill\", \"all\"], default=\"all\",\n                        help=\"Use decode or prefill batch sizes, or 'all' to test both.\")\n    parser.add_argument(\"--enable-chip-swimlane\", type=int, nargs=\"?\", const=1, default=0, choices=(0, 1, 2, 4))\n    parser.add_argument(\"--runtime-dir\", type=str, default=None)\n    parser.add_argument(\"--golden-data\", type=str, default=None)\n    parser.add_argument(\"--compile-only\", action=\"store_true\", default=False)\n    parser.add_argument(\"--dump-passes\", action=\"store_true\", default=False)\n    args = parser.parse_args()\n\n    modes_to_run = list(MODES.keys()) if args.mode == \"all\" else [args.mode]\n\n    for mode_name in modes_to_run:\n        B, S = MODES[mode_name]\n        print(f\"--- rms_norm_test {mode_name}: B={B}, S={S} ---\")\n        result = run(\n            fn=rms_norm_test,\n            specs=build_tensor_specs(B, S),\n            golden_fn=golden_rms_norm_test,\n            runtime_dir=args.runtime_dir,\n            golden_data=args.golden_data,\n            compile_cfg=dict(dump_passes=args.dump_passes),\n            runtime_cfg=dict(\n                platform=args.platform,\n                device_id=args.device,\n                enable_chip_swimlane=args.enable_chip_swimlane,\n            ),\n            rtol=5e-3,\n            atol=5e-3,\n            compare_fn={\n                \"x_normed\": ratio_allclose(atol=1e-4, rtol=1.0 / 128),\n            },\n            compile_only=args.compile_only,\n        )\n        if not result.passed:\n            if result.error:\n                print(result.error)\n            raise SystemExit(1)\n", "qkv_proj_rope.py": "# Copyright (c) PyPTO Contributors.\n# This program is free software, you can redistribute it and/or modify it under the terms and conditions of\n# CANN Open Software License Agreement Version 2.0 (the \"License\").\n# Please refer to the License for details. You may not use this file except in compliance with the License.\n# THIS SOFTWARE IS PROVIDED ON AN \"AS IS\" BASIS, WITHOUT WARRANTIES OF ANY KIND, EITHER EXPRESS OR IMPLIED,\n# INCLUDING BUT NOT LIMITED TO NON-INFRINGEMENT, MERCHANTABILITY, OR FITNESS FOR A PARTICULAR PURPOSE.\n# See LICENSE in the root of the software repository for the full text of the License.\n# -----------------------------------------------------------------------------------------------------------\n\"\"\"DeepSeek-V4 Q/KV LoRA + RoPE (dynamic shape): projects token-major\nattention-normalized inputs for both decode and prefill attention paths.\"\"\"\n\nimport pypto.language as pl\n\nfrom config import (\n    FLASH as M,\n    DECODE_BATCH,\n    DECODE_SEQ,\n    TP,\n    PREFILL_BATCH,\n    PREFILL_SEQ,\n    INT8_SCALE_MAX,\n    INT8_AMAX_EPS,\n)\n\n\n# Dynamic shape variables. The q branch, the kv branch and the rope tables each\n# carry their own token axis.\nT_DYN = pl.dynamic(\"QKV_Q_T_DYN\")  # T = B * S\nKV_T_DYN = pl.dynamic(\"QKV_KV_T_DYN\")\nROPE_T_DYN = pl.dynamic(\"QKV_ROPE_T_DYN\")\n\n# Bounded physical-row tile for Q/KV projection scratch.\nPREFILL_DENSE_TILE = 512\n\n\n# model config\nD = M.hidden_size\nH = M.num_attention_heads\nHEAD_DIM = M.head_dim\nROPE_DIM = M.qk_rope_head_dim\nROPE_DIM_SCALE = float(ROPE_DIM)\nROPE_HALF = ROPE_DIM // 2\nNOPE_DIM = M.nope_head_dim\nQ_LORA = M.q_lora_rank\nEPS = M.rms_norm_eps\nMAX_SEQ_LEN = M.max_position_embeddings\n\n# tiling\nQ_PROJ_TILE = 128  # qproj K-tile (Q_LORA reduction)\nQPROJ_MM_N_TILE = 512  # qproj output-column tile\nQ_LORA_TILE = 256  # qr rms-norm / quant N granularity\nKV_TILE = 64  # kv rms-norm / rope / NOPE N granularity\nQUANT_TILE = 256\nT_TILE = 8\nMATMUL_T_TILE = 16\nQR_M_TILE = MATMUL_T_TILE  # qr_proj token (M) tile; cube rows must be a 16-row boxed tile\nQR_N_TILE = 128  # qr_proj Q_LORA (N) per matmul\nQR_K_TILE = 256  # qr_proj D (K) reduction tile   | divides QR_SPLIT_K_TILE\nQR_OK = 2  # qr_proj split-K factor         | D//QR_OK cores share each N-group\nQR_SPLIT_K_TILE = D // QR_OK  # qr_proj K per split (=2048)\nKV_M_TILE = MATMUL_T_TILE  # kv_proj token (M) tile; decode pads from 8 real rows to 16\nKV_N_TILE = 128  # kv_proj HEAD_DIM (N) per matmul\nKV_K_TILE = 256  # kv_proj D (K) reduction tile   | divides KV_SPLIT_K_TILE\nKV_OK = 2  # kv_proj split-K factor         | D//KV_OK cores share each N-group\nKV_OM = 4  # kv_proj split-M factor        | M-tiles fan out KV_OM-fold\nKV_SPLIT_K_TILE = D // KV_OK  # kv_proj K per split (=2048)\nQPROJ_M_TILE = 64  # dense qproj token tile; fills the 128 KiB L0C accumulator\nQPROJ_TAIL_M_TILE = MATMUL_T_TILE  # partial-M path validated by decode/small physical T\nKV_RMS_T_TILE = 16  # kv rms-norm + rope fused token (T) tile\nQ_ROPE_T_TILE = 8\nQ_ROPE_H_TILE = 4  # heads per fused qproj dequant/rms/rope task\nassert QPROJ_MM_N_TILE * QPROJ_M_TILE * 4 <= 128 * 1024  # L0C Acc cap\nassert QPROJ_M_TILE % QPROJ_TAIL_M_TILE == 0\n\n\n@pl.jit.inline\ndef materialize_rope_rows_dynamic(\n    freqs_cos: pl.Tensor[[MAX_SEQ_LEN, ROPE_DIM], pl.BF16],\n    freqs_sin: pl.Tensor[[MAX_SEQ_LEN, ROPE_DIM], pl.BF16],\n    position_ids: pl.Tensor[[T_DYN], pl.INT32],\n    rope_cos_t: pl.Tensor[[T_DYN, ROPE_DIM], pl.BF16],\n    rope_sin_t: pl.Tensor[[T_DYN, ROPE_DIM], pl.BF16],\n):\n    \"\"\"Materialize every physical position row.\"\"\"\n    t_dim = pl.tensor.dim(position_ids, 0)\n    token_tiles = (t_dim + KV_RMS_T_TILE - 1) // KV_RMS_T_TILE\n    for rope_t0 in pl.spmd(token_tiles, name_hint=\"qkv_rope_rows_dynamic\"):\n        t0 = rope_t0 * KV_RMS_T_TILE\n        for rope_dt in pl.range(KV_RMS_T_TILE):\n            rope_t = t0 + rope_dt\n            if rope_t < t_dim:\n                rope_pos = pl.cast(pl.read(position_ids, [rope_t]), pl.INDEX)\n                rope_cos_t[rope_t : rope_t + 1, 0:ROPE_DIM] = freqs_cos[rope_pos : rope_pos + 1, 0:ROPE_DIM]\n                rope_sin_t[rope_t : rope_t + 1, 0:ROPE_DIM] = freqs_sin[rope_pos : rope_pos + 1, 0:ROPE_DIM]\n\n\n@pl.jit.inline\ndef materialize_rope_rows(\n    freqs_cos: pl.Tensor[[MAX_SEQ_LEN, ROPE_DIM], pl.BF16],\n    freqs_sin: pl.Tensor[[MAX_SEQ_LEN, ROPE_DIM], pl.BF16],\n    position_ids: pl.Tensor[[T_DYN], pl.INT32],\n    num_tokens: pl.Scalar[pl.INT32],\n    rope_cos_t: pl.Tensor[[T_DYN, ROPE_DIM], pl.BF16],\n    rope_sin_t: pl.Tensor[[T_DYN, ROPE_DIM], pl.BF16],\n):\n    \"\"\"Materialize the active prefix of a capacity-shaped position tensor.\"\"\"\n    t_dim = pl.tensor.dim(position_ids, 0)\n    token_tiles = (t_dim + KV_RMS_T_TILE - 1) // KV_RMS_T_TILE\n    for rope_t0 in pl.spmd(token_tiles, name_hint=\"qkv_rope_rows\"):\n        t0 = rope_t0 * KV_RMS_T_TILE\n        for rope_dt in pl.range(KV_RMS_T_TILE):\n            rope_t = t0 + rope_dt\n            if rope_t < t_dim and rope_t < num_tokens:\n                rope_pos = pl.cast(pl.read(position_ids, [rope_t]), pl.INDEX)\n                rope_cos_t[rope_t : rope_t + 1, 0:ROPE_DIM] = freqs_cos[rope_pos : rope_pos + 1, 0:ROPE_DIM]\n                rope_sin_t[rope_t : rope_t + 1, 0:ROPE_DIM] = freqs_sin[rope_pos : rope_pos + 1, 0:ROPE_DIM]\n\n\n@pl.jit.inline\ndef rope_prepare(\n    rope_cos: pl.Tensor[[ROPE_T_DYN, ROPE_DIM], pl.BF16],\n    rope_sin: pl.Tensor[[ROPE_T_DYN, ROPE_DIM], pl.BF16],\n    rope_cos_il: pl.Tensor[[ROPE_T_DYN, ROPE_DIM], pl.FP32],\n    rope_sin_signed: pl.Tensor[[ROPE_T_DYN, ROPE_DIM], pl.FP32],\n    rope_swap_idx: pl.Tensor[[ROPE_T_DYN, ROPE_DIM], pl.INT32],\n):\n    \"\"\"Build the head-invariant interleaved cos / sign-folded sin / swap-index rope rows.\"\"\"\n    t_dim = pl.tensor.dim(rope_cos, 0)\n    rope_cos_view = pl.reshape(rope_cos, [t_dim, ROPE_DIM])\n    rope_sin_view = pl.reshape(rope_sin, [t_dim, ROPE_DIM])\n    # The tail guard below writes the outputs from inside a conditional region.\n    # Binding them to the scalar extent keeps the region result off the dynamic\n    # symbol, which has no definition in an inlining caller that passes a\n    # statically shaped token axis.\n    rope_cos_il_view = pl.reshape(rope_cos_il, [t_dim, ROPE_DIM])\n    rope_sin_signed_view = pl.reshape(rope_sin_signed, [t_dim, ROPE_DIM])\n    rope_swap_idx_view = pl.reshape(rope_swap_idx, [t_dim, ROPE_DIM])\n\n    token_tiles = (t_dim + Q_ROPE_T_TILE - 1) // Q_ROPE_T_TILE\n    for qrp_idx in pl.spmd(token_tiles, name_hint=\"q_rope_prepare\", allow_early_resolve=True):\n        qrp_t0 = qrp_idx * Q_ROPE_T_TILE\n        qrp_valid_rows = pl.min(Q_ROPE_T_TILE, t_dim - qrp_t0)\n        qrp_ones = pl.full([Q_ROPE_T_TILE, ROPE_DIM], dtype=pl.FP32, value=1.0)\n        qrp_idx_i32 = pl.arange(0, [1, ROPE_DIM], dtype=pl.INT32)\n        qrp_idx_fp32 = pl.cast(qrp_idx_i32, target_type=pl.FP32)\n        qrp_col = pl.col_expand_mul(qrp_ones, qrp_idx_fp32)\n        qrp_half = pl.mul(qrp_col, 0.5)\n        qrp_dup_i32 = pl.cast(qrp_half, target_type=pl.INT32, mode=\"trunc\")\n        qrp_dup_f = pl.cast(qrp_dup_i32, target_type=pl.FP32)\n        qrp_dup_idx = pl.cast(qrp_dup_f, target_type=pl.INT32)\n        qrp_lane = pl.sub(qrp_col, pl.mul(qrp_dup_f, 2.0))\n        qrp_next_col = pl.add(qrp_col, 1.0)\n        qrp_lane_offset = pl.mul(qrp_lane, 2.0)\n        qrp_swap_f = pl.sub(qrp_next_col, qrp_lane_offset)\n        qrp_swap_idx = pl.cast(qrp_swap_f, target_type=pl.INT32)\n        qrp_sign = pl.sub(pl.mul(qrp_lane, 2.0), 1.0)\n        if qrp_valid_rows == Q_ROPE_T_TILE:\n            qrp_cos_rows_full = rope_cos_view[qrp_t0 : qrp_t0 + Q_ROPE_T_TILE, :]\n            qrp_sin_rows_full = rope_sin_view[qrp_t0 : qrp_t0 + Q_ROPE_T_TILE, :]\n            qrp_cos_full = pl.cast(qrp_cos_rows_full, target_type=pl.FP32)\n            qrp_sin_full = pl.cast(qrp_sin_rows_full, target_type=pl.FP32)\n            qrp_cos_il_full = pl.gather(qrp_cos_full, dim=-1, index=qrp_dup_idx)\n            qrp_sin_il_full = pl.gather(qrp_sin_full, dim=-1, index=qrp_dup_idx)\n            qrp_sin_signed_full = pl.mul(qrp_sin_il_full, qrp_sign)\n            rope_cos_il_view[qrp_t0 : qrp_t0 + Q_ROPE_T_TILE, :] = qrp_cos_il_full\n            rope_sin_signed_view[qrp_t0 : qrp_t0 + Q_ROPE_T_TILE, :] = qrp_sin_signed_full\n            rope_swap_idx_view[qrp_t0 : qrp_t0 + Q_ROPE_T_TILE, :] = qrp_swap_idx\n        else:\n            qrp_cos_rows_tail = pl.load(\n                rope_cos_view,\n                [qrp_t0, 0],\n                [Q_ROPE_T_TILE, ROPE_DIM],\n                valid_shape=[qrp_valid_rows, ROPE_DIM],\n                target_memory=pl.MemorySpace.Vec,\n            )\n            qrp_sin_rows_tail = pl.load(\n                rope_sin_view,\n                [qrp_t0, 0],\n                [Q_ROPE_T_TILE, ROPE_DIM],\n                valid_shape=[qrp_valid_rows, ROPE_DIM],\n                target_memory=pl.MemorySpace.Vec,\n            )\n            qrp_tail_col = pl.col_expand_mul(\n                pl.tile.full([Q_ROPE_T_TILE, ROPE_DIM], dtype=pl.FP32, value=1.0),\n                pl.cast(pl.tile.arange(0, [1, ROPE_DIM], dtype=pl.INT32), target_type=pl.FP32),\n            )\n            qrp_tail_dup_f = pl.cast(\n                pl.cast(pl.mul(qrp_tail_col, 0.5), target_type=pl.INT32, mode=\"trunc\"),\n                target_type=pl.FP32,\n            )\n            qrp_tail_lane = pl.sub(qrp_tail_col, pl.mul(qrp_tail_dup_f, 2.0))\n            qrp_tail_swap_f = pl.sub(pl.add(qrp_tail_col, 1.0), pl.mul(qrp_tail_lane, 2.0))\n            # Row-major flattening offsets stay in fp32: col-expand is defined for\n            # half / float only.\n            qrp_row_seed = pl.mul(\n                pl.cast(pl.tile.arange(0, [1, Q_ROPE_T_TILE], dtype=pl.INT32), target_type=pl.FP32),\n                ROPE_DIM_SCALE,\n            )\n            qrp_row_grid = pl.col_expand_mul(\n                pl.tile.full([ROPE_DIM, Q_ROPE_T_TILE], dtype=pl.FP32, value=1.0),\n                qrp_row_seed,\n            )\n            qrp_row_offset = pl.transpose(qrp_row_grid, axis1=0, axis2=1)\n            qrp_dup_idx_tail = pl.cast(pl.add(qrp_tail_dup_f, qrp_row_offset), target_type=pl.INT32)\n            qrp_gather_tmp = pl.create_tile(\n                [Q_ROPE_T_TILE, ROPE_DIM],\n                dtype=pl.INT32,\n                target_memory=pl.MemorySpace.Vec,\n            )\n            qrp_cos_il_tail = pl.tile.gather(\n                pl.cast(qrp_cos_rows_tail, target_type=pl.FP32),\n                qrp_dup_idx_tail,\n                qrp_gather_tmp,\n            )\n            qrp_sin_il_tail = pl.tile.gather(\n                pl.cast(qrp_sin_rows_tail, target_type=pl.FP32),\n                qrp_dup_idx_tail,\n                qrp_gather_tmp,\n            )\n            qrp_tail_sign = pl.sub(pl.mul(qrp_tail_lane, 2.0), 1.0)\n            qrp_sin_signed_tail = pl.mul(qrp_sin_il_tail, qrp_tail_sign)\n            pl.store(\n                pl.set_validshape(qrp_cos_il_tail, qrp_valid_rows, ROPE_DIM),\n                [qrp_t0, 0],\n                rope_cos_il_view,\n            )\n            pl.store(\n                pl.set_validshape(qrp_sin_signed_tail, qrp_valid_rows, ROPE_DIM),\n                [qrp_t0, 0],\n                rope_sin_signed_view,\n            )\n            pl.store(\n                pl.set_validshape(\n                    pl.cast(qrp_tail_swap_f, target_type=pl.INT32),\n                    qrp_valid_rows,\n                    ROPE_DIM,\n                ),\n                [qrp_t0, 0],\n                rope_swap_idx_view,\n            )\n\n\n@pl.jit.inline(auto_scope=False)\ndef q_proj_rope(\n    x: pl.Tensor[[T_DYN, D], pl.BF16],\n    wq_a: pl.Tensor[[D, Q_LORA], pl.BF16],\n    wq_b: pl.Tensor[[Q_LORA, H * HEAD_DIM], pl.INT8],\n    wq_b_scale: pl.Tensor[[H * HEAD_DIM], pl.FP32],\n    gamma_cq: pl.Tensor[[Q_LORA], pl.BF16],\n    rope_cos_il: pl.Tensor[[T_DYN, ROPE_DIM], pl.FP32],\n    rope_sin_signed: pl.Tensor[[T_DYN, ROPE_DIM], pl.FP32],\n    rope_swap_idx: pl.Tensor[[T_DYN, ROPE_DIM], pl.INT32],\n    q: pl.Tensor[[T_DYN, H, HEAD_DIM], pl.BF16],\n    qr: pl.Tensor[[T_DYN, Q_LORA], pl.INT8],\n    qr_scale: pl.Tensor[[T_DYN, 1], pl.FP32],\n):\n    \"\"\"Q LoRA, RMSNorm, quantization, and RoPE over bounded dense tiles.\"\"\"\n    t_dim = pl.tensor.dim(x, 0)\n    for tile_base in pl.range(0, t_dim, PREFILL_DENSE_TILE):\n        tile_rows = pl.min(PREFILL_DENSE_TILE, t_dim - tile_base)\n        with pl.scope():\n            x_view = pl.reshape(x, [t_dim, D])\n            qr_t_matmul = ((tile_rows + QR_M_TILE - 1) // QR_M_TILE) * QR_M_TILE\n            qproj_t_matmul = ((tile_rows + QPROJ_TAIL_M_TILE - 1) // QPROJ_TAIL_M_TILE) * QPROJ_TAIL_M_TILE\n            qproj_full_rows = (tile_rows // QPROJ_M_TILE) * QPROJ_M_TILE\n\n            # Split-K qr_proj (M=t_dim, K=D=4096, N=Q_LORA=1024): QR_N_TILE N-groups expanded\n            # QR_OK-fold into cube blocks that atomic-add their K partials into a zero-seeded\n            # output. Seeded on-core, not through create_tensor init_value=0.\n            qr_fp32 = pl.create_tensor([qr_t_matmul, Q_LORA], dtype=pl.FP32)\n            with pl.at(level=pl.Level.CORE_GROUP, name_hint=\"qr_proj_seed\"):\n                for ts0 in pl.range(0, qr_t_matmul, QR_M_TILE):\n                    for nseed0 in pl.range(0, Q_LORA, QR_N_TILE):\n                        qr_seed = pl.full([QR_M_TILE, QR_N_TILE], dtype=pl.FP32, value=0.0)\n                        qr_fp32[ts0 : ts0 + QR_M_TILE, nseed0 : nseed0 + QR_N_TILE] = qr_seed\n\n            for qbg_idx in pl.spmd(\n                (Q_LORA // QR_N_TILE) * QR_OK, name_hint=\"qr_proj_matmul\", allow_early_resolve=True\n            ):\n                q_a_col0 = (qbg_idx // QR_OK) * QR_N_TILE\n                qr_k_base = (qbg_idx % QR_OK) * QR_SPLIT_K_TILE\n                for t0 in pl.range(0, qr_t_matmul, QR_M_TILE):\n                    q_acc = pl.create_tensor([QR_M_TILE, QR_N_TILE], dtype=pl.FP32)\n                    for db in pl.pipeline(QR_SPLIT_K_TILE // QR_K_TILE, stage=2):\n                        qr_d0 = qr_k_base + db * QR_K_TILE\n                        qr_rows = pl.min(QR_M_TILE, tile_rows - t0)\n                        x_t0 = tile_base + t0\n                        q_x_chunk_bf16 = pl.slice(\n                            x_view,\n                            [QR_M_TILE, QR_K_TILE],\n                            [x_t0, qr_d0],\n                            valid_shape=[qr_rows, QR_K_TILE],\n                        )\n                        w_chunk = wq_a[qr_d0 : qr_d0 + QR_K_TILE, q_a_col0 : q_a_col0 + QR_N_TILE]\n                        if db == 0:\n                            q_acc = pl.matmul(q_x_chunk_bf16, w_chunk, out_dtype=pl.FP32)\n                        else:\n                            q_acc = pl.matmul_acc(q_acc, q_x_chunk_bf16, w_chunk)\n                    qr_fp32 = pl.assemble(qr_fp32, q_acc, [t0, q_a_col0], atomic=pl.AtomicType.Add)\n\n            qr_view = pl.reshape(qr, [t_dim, Q_LORA])\n            qr_scale_view = pl.reshape(qr_scale, [t_dim, 1])\n            qr_i8_matmul = pl.create_tensor([qproj_t_matmul, Q_LORA], dtype=pl.INT8)\n            # The quant scale rides the qr_i8 -> qproj_matmul -> dequant chain.\n            qr_scale_pad_store = pl.create_tensor([qproj_t_matmul, 1], dtype=pl.FP32, manual_dep=True)\n\n            # Two passes per block: pass 1 computes amax; pass 2 recomputes norm and quantizes.\n            qr_token_tiles = (tile_rows + T_TILE - 1) // T_TILE\n            for tg_idx in pl.spmd(qr_token_tiles, name_hint=\"qr_rms_norm_quant\", allow_early_resolve=True):\n                tg = tg_idx * T_TILE\n                valid_rows = pl.min(T_TILE, tile_rows - tg)\n                out_tg = tile_base + tg\n                qr_sq_sum = pl.full([1, T_TILE], dtype=pl.FP32, value=0.0)\n                qr_amax_g = pl.full([1, T_TILE], dtype=pl.FP32, value=0.0)\n                for qr_rms_col0 in pl.pipeline(0, Q_LORA, Q_LORA_TILE, stage=2):\n                    qr_rms_chunk = qr_fp32[tg : tg + T_TILE, qr_rms_col0 : qr_rms_col0 + Q_LORA_TILE]\n                    qr_rms_sq = pl.mul(qr_rms_chunk, qr_rms_chunk)\n                    qr_rms_row_sum = pl.reshape(pl.row_sum(qr_rms_sq), [1, T_TILE])\n                    qr_sq_sum = pl.add(qr_sq_sum, qr_rms_row_sum)\n                    gamma_rms_cast = pl.cast(gamma_cq[qr_rms_col0 : qr_rms_col0 + Q_LORA_TILE], target_type=pl.FP32)\n                    gamma_rms_chunk = pl.reshape(gamma_rms_cast, [1, Q_LORA_TILE])\n                    qr_g = pl.col_expand_mul(qr_rms_chunk, gamma_rms_chunk)\n                    qr_g_abs = pl.abs(qr_g)\n                    qr_g_row_max = pl.reshape(pl.row_max(qr_g_abs), [1, T_TILE])\n                    qr_amax_g = pl.maximum(qr_amax_g, qr_g_row_max)\n                qr_inv_rms = pl.rsqrt(pl.add(pl.mul(qr_sq_sum, 1.0 / Q_LORA), EPS), high_precision=True)\n                qr_inv_rms_t = pl.reshape(qr_inv_rms, [T_TILE, 1])\n                qr_amax_floor = pl.full([1, T_TILE], dtype=pl.FP32, value=INT8_AMAX_EPS)\n                qr_amax_normed = pl.mul(qr_inv_rms, qr_amax_g)\n                qr_tile_amax = pl.maximum(qr_amax_floor, qr_amax_normed)\n\n                qr_scale_quant_row = pl.div(pl.full([1, T_TILE], dtype=pl.FP32, value=INT8_SCALE_MAX), qr_tile_amax)\n                qr_scale_quant_t = pl.reshape(qr_scale_quant_row, [T_TILE, 1])\n                qr_tile_scale_dq = pl.reshape(pl.recip(qr_scale_quant_row), [T_TILE, 1])\n                qr_scale_pad_store = pl.assemble(qr_scale_pad_store, qr_tile_scale_dq, [tg, 0])\n                if valid_rows == T_TILE:\n                    qr_scale_view[out_tg : out_tg + T_TILE, :] = qr_tile_scale_dq\n                else:\n                    qr_scale_tail = pl.load(\n                        qr_scale_pad_store,\n                        [tg, 0],\n                        [T_TILE, 1],\n                        valid_shape=[valid_rows, 1],\n                        target_memory=pl.MemorySpace.Vec,\n                    )\n                    pl.store(qr_scale_tail, [out_tg, 0], qr_scale_view)\n\n                for qa in pl.pipeline(0, Q_LORA, QUANT_TILE, stage=2):\n                    qr_chunk = qr_fp32[tg : tg + T_TILE, qa : qa + QUANT_TILE]\n                    gamma_q_cast = pl.cast(gamma_cq[qa : qa + QUANT_TILE], target_type=pl.FP32)\n                    gamma_q_chunk = pl.reshape(gamma_q_cast, [1, QUANT_TILE])\n                    qr_q_normed = pl.col_expand_mul(pl.row_expand_mul(qr_chunk, qr_inv_rms_t), gamma_q_chunk)\n                    qr_q_scaled = pl.row_expand_mul(qr_q_normed, qr_scale_quant_t)\n                    qr_q_i32 = pl.cast(qr_q_scaled, target_type=pl.INT32, mode=\"rint\")\n                    qr_q_half = pl.cast(qr_q_i32, target_type=pl.FP16, mode=\"round\")\n                    qr_q_i8 = pl.cast(qr_q_half, target_type=pl.INT8, mode=\"trunc\")\n                    qr_i8_matmul[tg : tg + T_TILE, qa : qa + QUANT_TILE] = qr_q_i8\n                    if valid_rows == T_TILE:\n                        qr_view[out_tg : out_tg + T_TILE, qa : qa + QUANT_TILE] = qr_q_i8\n                    else:\n                        qr_q_tail = pl.load(\n                            qr_i8_matmul,\n                            [tg, qa],\n                            [T_TILE, QUANT_TILE],\n                            valid_shape=[valid_rows, QUANT_TILE],\n                            target_memory=pl.MemorySpace.Vec,\n                        )\n                        pl.store(qr_q_tail, [out_tg, qa], qr_view)\n\n            # Pure-matmul qproj scope (cube, INT32 -> GM), unmixed with downstream vector work.\n            q_proj_i32 = pl.create_tensor([qproj_t_matmul, H * HEAD_DIM], dtype=pl.INT32)\n            # Full 64-row cube tiles use the dense path.  The A2/A3 partial-M path is\n            # not numerically reliable at this tile size, so the final incomplete\n            # 64-row block is lowered through the established 16-row cube shape.\n            for qproj_n_idx in pl.spmd(\n                (H * HEAD_DIM) // QPROJ_MM_N_TILE,\n                name_hint=\"qproj_matmul\",\n            ):\n                w_col0 = qproj_n_idx * QPROJ_MM_N_TILE\n                for t0 in pl.range(0, qproj_full_rows, QPROJ_M_TILE):\n                    col_acc = pl.create_tensor([QPROJ_M_TILE, QPROJ_MM_N_TILE], dtype=pl.INT32)\n                    for qr_proj_col0 in pl.pipeline(0, Q_LORA, Q_PROJ_TILE, stage=2):\n                        qr_i8_chunk = qr_i8_matmul[\n                            t0 : t0 + QPROJ_M_TILE,\n                            qr_proj_col0 : qr_proj_col0 + Q_PROJ_TILE,\n                        ]\n                        wq_chunk = wq_b[qr_proj_col0 : qr_proj_col0 + Q_PROJ_TILE, w_col0 : w_col0 + QPROJ_MM_N_TILE]\n                        if qr_proj_col0 == 0:\n                            col_acc = pl.matmul(qr_i8_chunk, wq_chunk, out_dtype=pl.INT32)\n                        else:\n                            col_acc = pl.matmul_acc(col_acc, qr_i8_chunk, wq_chunk)\n                    q_proj_i32[t0 : t0 + QPROJ_M_TILE, w_col0 : w_col0 + QPROJ_MM_N_TILE] = col_acc\n\n                tail_w_col0 = w_col0\n                for tail_t0 in pl.range(qproj_full_rows, qproj_t_matmul, QPROJ_TAIL_M_TILE):\n                    qproj_tail_rows = pl.min(QPROJ_TAIL_M_TILE, tile_rows - tail_t0)\n                    tail_acc = pl.create_tensor([QPROJ_TAIL_M_TILE, QPROJ_MM_N_TILE], dtype=pl.INT32)\n                    for tail_qr_col0 in pl.pipeline(0, Q_LORA, Q_PROJ_TILE, stage=2):\n                        qr_i8_tail = pl.slice(\n                            qr_i8_matmul,\n                            [QPROJ_TAIL_M_TILE, Q_PROJ_TILE],\n                            [tail_t0, tail_qr_col0],\n                            valid_shape=[qproj_tail_rows, Q_PROJ_TILE],\n                        )\n                        wq_tail = wq_b[\n                            tail_qr_col0 : tail_qr_col0 + Q_PROJ_TILE,\n                            tail_w_col0 : tail_w_col0 + QPROJ_MM_N_TILE,\n                        ]\n                        if tail_qr_col0 == 0:\n                            tail_acc = pl.matmul(qr_i8_tail, wq_tail, out_dtype=pl.INT32)\n                        else:\n                            tail_acc = pl.matmul_acc(tail_acc, qr_i8_tail, wq_tail)\n                    q_proj_i32[\n                        tail_t0 : tail_t0 + QPROJ_TAIL_M_TILE,\n                        tail_w_col0 : tail_w_col0 + QPROJ_MM_N_TILE,\n                    ] = tail_acc\n\n            # Fused qproj dequant, per-head RMSNorm, NOPE writeback, and interleaved RoPE.\n            # RoPE: out[j] = inv_rms * (x[j] * cos[j] + x[j^1] * sign[j] * sin[j]).\n            q_flat = pl.reshape(q, [t_dim, H * HEAD_DIM])\n            for hg_idx in pl.spmd(\n                H // Q_ROPE_H_TILE, name_hint=\"qproj_dequant_rms_nope_rope\", allow_early_resolve=True\n            ):\n                hg = hg_idx * Q_ROPE_H_TILE\n                for tg in pl.range(0, tile_rows, Q_ROPE_T_TILE):\n                    out_tg = tile_base + tg\n                    if tg + Q_ROPE_T_TILE <= tile_rows:\n                        qr_scale_dq_t = qr_scale_pad_store[tg : tg + Q_ROPE_T_TILE, :]\n                        q_cos_il = rope_cos_il[out_tg : out_tg + Q_ROPE_T_TILE, :]\n                        q_sin_signed = rope_sin_signed[out_tg : out_tg + Q_ROPE_T_TILE, :]\n                        q_swap_idx = rope_swap_idx[out_tg : out_tg + Q_ROPE_T_TILE, :]\n                        for h_inner in pl.pipeline(Q_ROPE_H_TILE, stage=2):\n                            h = hg + h_inner\n                            h0 = h * HEAD_DIM\n                            q_head_acc = q_proj_i32[tg : tg + Q_ROPE_T_TILE, h0 : h0 + HEAD_DIM]\n                            q_head_scale = pl.reshape(wq_b_scale[h0 : h0 + HEAD_DIM], [1, HEAD_DIM])\n                            q_head_acc_fp32 = pl.cast(q_head_acc, target_type=pl.FP32, mode=\"none\")\n                            q_head_row_scaled = pl.row_expand_mul(q_head_acc_fp32, qr_scale_dq_t)\n                            q_head_dq = pl.col_expand_mul(q_head_row_scaled, q_head_scale)\n                            q_head_sq = pl.mul(q_head_dq, q_head_dq)\n                            q_head_sq_row = pl.row_sum(q_head_sq)\n                            q_head_sq_sum = pl.reshape(q_head_sq_row, [1, Q_ROPE_T_TILE])\n                            q_head_sq_mean = pl.mul(q_head_sq_sum, 1.0 / HEAD_DIM)\n                            q_head_var = pl.add(q_head_sq_mean, EPS)\n                            q_head_inv_rms = pl.rsqrt(q_head_var, high_precision=True)\n                            q_head_inv_rms_t = pl.reshape(q_head_inv_rms, [Q_ROPE_T_TILE, 1])\n\n                            q_nope_normed = pl.row_expand_mul(q_head_dq[:, 0:NOPE_DIM], q_head_inv_rms_t)\n                            q_nope_bf16 = pl.cast(q_nope_normed, target_type=pl.BF16, mode=\"rint\")\n                            q_flat[out_tg : out_tg + Q_ROPE_T_TILE, h0 : h0 + NOPE_DIM] = q_nope_bf16\n\n                            q_rope_chunk_raw = q_head_dq[:, NOPE_DIM:HEAD_DIM]\n                            q_rope_chunk = pl.row_expand_mul(q_rope_chunk_raw, q_head_inv_rms_t)\n                            q_rope_swapped = pl.gather(q_rope_chunk, dim=-1, index=q_swap_idx)\n                            q_rope_base = pl.mul(q_rope_chunk, q_cos_il)\n                            q_rope_delta = pl.mul(q_rope_swapped, q_sin_signed)\n                            q_rope_rot = pl.add(q_rope_base, q_rope_delta)\n                            q_rope_bf16 = pl.cast(q_rope_rot, target_type=pl.BF16, mode=\"rint\")\n                            q_flat[out_tg : out_tg + Q_ROPE_T_TILE, h0 + NOPE_DIM : h0 + HEAD_DIM] = q_rope_bf16\n                    else:\n                        valid_tail_rows = tile_rows - tg\n                        # q_proj and its dequant scale are padded to the cube boundary.\n                        # Keep the math on a static eight-row tile and crop public stores.\n                        qr_scale_dq_tail = pl.load(\n                            qr_scale_pad_store,\n                            [tg, 0],\n                            [Q_ROPE_T_TILE, 1],\n                            target_memory=pl.MemorySpace.Vec,\n                        )\n                        q_cos_il_tail = pl.load(\n                            rope_cos_il,\n                            [out_tg, 0],\n                            [Q_ROPE_T_TILE, ROPE_DIM],\n                            valid_shape=[valid_tail_rows, ROPE_DIM],\n                            target_memory=pl.MemorySpace.Vec,\n                        )\n                        q_sin_signed_tail = pl.load(\n                            rope_sin_signed,\n                            [out_tg, 0],\n                            [Q_ROPE_T_TILE, ROPE_DIM],\n                            valid_shape=[valid_tail_rows, ROPE_DIM],\n                            target_memory=pl.MemorySpace.Vec,\n                        )\n                        q_col = pl.col_expand_mul(\n                            pl.tile.full([Q_ROPE_T_TILE, ROPE_DIM], dtype=pl.FP32, value=1.0),\n                            pl.cast(pl.tile.arange(0, [1, ROPE_DIM], dtype=pl.INT32), target_type=pl.FP32),\n                        )\n                        q_dup_f = pl.cast(pl.cast(pl.mul(q_col, 0.5), target_type=pl.INT32, mode=\"trunc\"), pl.FP32)\n                        q_lane = pl.sub(q_col, pl.mul(q_dup_f, 2.0))\n                        q_swap_f = pl.sub(pl.add(q_col, 1.0), pl.mul(q_lane, 2.0))\n                        # Row-major flattening offsets stay in fp32: col-expand is defined\n                        # for half / float only.\n                        q_row_seed = pl.mul(\n                            pl.cast(pl.tile.arange(0, [1, Q_ROPE_T_TILE], dtype=pl.INT32), target_type=pl.FP32),\n                            ROPE_DIM_SCALE,\n                        )\n                        q_row_grid = pl.col_expand_mul(\n                            pl.tile.full([ROPE_DIM, Q_ROPE_T_TILE], dtype=pl.FP32, value=1.0),\n                            q_row_seed,\n                        )\n                        q_row_offset = pl.transpose(q_row_grid, axis1=0, axis2=1)\n                        q_swap_idx_tail = pl.cast(pl.add(q_swap_f, q_row_offset), target_type=pl.INT32)\n                        q_head_reduce_tmp = pl.create_tile(\n                            [Q_ROPE_T_TILE, HEAD_DIM],\n                            dtype=pl.FP32,\n                            target_memory=pl.MemorySpace.Vec,\n                        )\n                        q_gather_tmp = pl.create_tile(\n                            [Q_ROPE_T_TILE, ROPE_DIM],\n                            dtype=pl.INT32,\n                            target_memory=pl.MemorySpace.Vec,\n                        )\n                        for h_inner_tail in pl.range(Q_ROPE_H_TILE):\n                            h_tail = hg + h_inner_tail\n                            h0_tail = h_tail * HEAD_DIM\n                            q_head_acc_tail = pl.load(\n                                q_proj_i32,\n                                [tg, h0_tail],\n                                [Q_ROPE_T_TILE, HEAD_DIM],\n                                target_memory=pl.MemorySpace.Vec,\n                            )\n                            q_head_scale_input_tail = pl.load(\n                                wq_b_scale,\n                                [h0_tail],\n                                [HEAD_DIM],\n                                target_memory=pl.MemorySpace.Vec,\n                            )\n                            q_head_scale_tail = pl.reshape(q_head_scale_input_tail, [1, HEAD_DIM])\n                            q_head_acc_fp32_tail = pl.cast(q_head_acc_tail, target_type=pl.FP32, mode=\"none\")\n                            q_head_row_scaled_tail = pl.row_expand_mul(q_head_acc_fp32_tail, qr_scale_dq_tail)\n                            q_head_dq_tail = pl.col_expand_mul(q_head_row_scaled_tail, q_head_scale_tail)\n\n                            q_head_sq_tail = pl.mul(q_head_dq_tail, q_head_dq_tail)\n                            q_head_sq_sum_tail = pl.row_sum(q_head_sq_tail, q_head_reduce_tmp)\n                            q_head_inv_rms_tail = pl.recip(\n                                pl.sqrt(pl.add(pl.mul(q_head_sq_sum_tail, 1.0 / HEAD_DIM), EPS)),\n                            )\n\n                            q_nope_normed_tail = pl.row_expand_mul(q_head_dq_tail[:, 0:NOPE_DIM], q_head_inv_rms_tail)\n                            q_nope_bf16_tail = pl.cast(q_nope_normed_tail, target_type=pl.BF16, mode=\"rint\")\n                            q_nope_valid = pl.set_validshape(q_nope_bf16_tail, valid_tail_rows, NOPE_DIM)\n                            pl.store(q_nope_valid, [out_tg, h0_tail], q_flat)\n\n                            q_rope_chunk_raw_tail = q_head_dq_tail[:, NOPE_DIM:HEAD_DIM]\n                            q_rope_chunk_tail = pl.row_expand_mul(q_rope_chunk_raw_tail, q_head_inv_rms_tail)\n                            q_rope_swapped_tail = pl.tile.gather(q_rope_chunk_tail, q_swap_idx_tail, q_gather_tmp)\n                            q_rope_base_tail = pl.mul(q_rope_chunk_tail, q_cos_il_tail)\n                            q_rope_delta_tail = pl.mul(q_rope_swapped_tail, q_sin_signed_tail)\n                            q_rope_rot_tail = pl.add(q_rope_base_tail, q_rope_delta_tail)\n                            q_rope_bf16_tail = pl.cast(q_rope_rot_tail, target_type=pl.BF16, mode=\"rint\")\n                            q_rope_valid = pl.set_validshape(q_rope_bf16_tail, valid_tail_rows, ROPE_DIM)\n                            pl.store(q_rope_valid, [out_tg, h0_tail + NOPE_DIM], q_flat)\n\n\n@pl.jit.inline(auto_scope=False)\ndef kv_proj_rope(\n    x: pl.Tensor[[KV_T_DYN, D], pl.BF16],\n    wkv: pl.Tensor[[D, HEAD_DIM], pl.BF16],\n    gamma_ckv: pl.Tensor[[HEAD_DIM], pl.BF16],\n    rope_cos_il: pl.Tensor[[KV_T_DYN, ROPE_DIM], pl.FP32],\n    rope_sin_signed: pl.Tensor[[KV_T_DYN, ROPE_DIM], pl.FP32],\n    rope_swap_idx: pl.Tensor[[KV_T_DYN, ROPE_DIM], pl.INT32],\n    kv: pl.Tensor[[KV_T_DYN, HEAD_DIM], pl.BF16],\n    late_dep: pl.Scalar[pl.TASK_ID],\n):\n    \"\"\"KV LoRA, RMSNorm, and RoPE over bounded dense tiles.\"\"\"\n    t_dim = pl.tensor.dim(x, 0)\n    for tile_base in pl.range(0, t_dim, PREFILL_DENSE_TILE):\n        tile_rows = pl.min(PREFILL_DENSE_TILE, t_dim - tile_base)\n        with pl.scope():\n            x_view = pl.reshape(x, [t_dim, D])\n            t_matmul = ((tile_rows + MATMUL_T_TILE - 1) // MATMUL_T_TILE) * MATMUL_T_TILE\n\n            # Split-K kv_proj: KV_N_TILE N-groups expanded KV_OK-fold into cube blocks that\n            # atomic-add their K partials into a zero-seeded output.\n            kv_fp32 = pl.create_tensor([t_matmul, HEAD_DIM], dtype=pl.FP32)\n            with pl.at(level=pl.Level.CORE_GROUP, name_hint=\"kv_proj_seed\"):\n                for kts0 in pl.range(0, t_matmul, KV_M_TILE):\n                    for kvseed0 in pl.range(0, HEAD_DIM, KV_N_TILE):\n                        kv_seed = pl.full([KV_M_TILE, KV_N_TILE], dtype=pl.FP32, value=0.0)\n                        kv_fp32[kts0 : kts0 + KV_M_TILE, kvseed0 : kvseed0 + KV_N_TILE] = kv_seed\n\n            # `late_dep` fences kv_proj one hop behind rms_norm so qr_proj_matmul takes the cores first.\n            with pl.spmd(\n                (HEAD_DIM // KV_N_TILE) * KV_OK * KV_OM, name_hint=\"kv_proj_matmul\", deps=[late_dep],\n            ) as _kv_tid:\n                kbg = pl.tile.get_block_idx()\n                kv_col0 = (kbg // (KV_OK * KV_OM)) * KV_N_TILE\n                kv_k_base = ((kbg // KV_OM) % KV_OK) * KV_SPLIT_K_TILE\n                kv_m_group = kbg % KV_OM\n                for t0 in pl.range(kv_m_group * KV_M_TILE, t_matmul, KV_OM * KV_M_TILE):\n                    kv_acc = pl.create_tensor([KV_M_TILE, KV_N_TILE], dtype=pl.FP32)\n                    for db in pl.pipeline(KV_SPLIT_K_TILE // KV_K_TILE, stage=2):\n                        d0 = kv_k_base + db * KV_K_TILE\n                        kv_rows = pl.min(KV_M_TILE, tile_rows - t0)\n                        x_t0 = tile_base + t0\n                        kv_x_chunk_bf16 = pl.slice(\n                            x_view,\n                            [KV_M_TILE, KV_K_TILE],\n                            [x_t0, d0],\n                            valid_shape=[kv_rows, KV_K_TILE],\n                        )\n                        wkv_chunk = wkv[d0 : d0 + KV_K_TILE, kv_col0 : kv_col0 + KV_N_TILE]\n                        if db == 0:\n                            kv_acc = pl.matmul(kv_x_chunk_bf16, wkv_chunk, out_dtype=pl.FP32)\n                        else:\n                            kv_acc = pl.matmul_acc(kv_acc, kv_x_chunk_bf16, wkv_chunk)\n                    kv_fp32 = pl.assemble(kv_fp32, kv_acc, [t0, kv_col0], atomic=pl.AtomicType.Add)\n\n            kv_view = pl.reshape(kv, [t_dim, HEAD_DIM])\n\n            # Fused KV RMSNorm + interleaved (CANN A3) RoPE, one spmd task per\n            # [KV_RMS_T_TILE, HEAD_DIM] row block. NOPE columns [0:NOPE_DIM) and rope columns\n            # [NOPE_DIM:HEAD_DIM) are disjoint, so each task writes a conflict-free row block.\n            kv_token_tiles = (tile_rows + KV_RMS_T_TILE - 1) // KV_RMS_T_TILE\n            for tg_idx in pl.spmd(kv_token_tiles, name_hint=\"kv_rms_norm_rope\"):\n                tg = tg_idx * KV_RMS_T_TILE\n                valid_rows = pl.min(KV_RMS_T_TILE, tile_rows - tg)\n                out_tg = tile_base + tg\n                if valid_rows == KV_RMS_T_TILE:\n                    kv_sq_sum = pl.full([1, KV_RMS_T_TILE], dtype=pl.FP32, value=0.0)\n                    for kv_sq_col0 in pl.pipeline(0, HEAD_DIM, KV_TILE, stage=2):\n                        kv_chunk = kv_fp32[tg : tg + KV_RMS_T_TILE, kv_sq_col0 : kv_sq_col0 + KV_TILE]\n                        kv_sq = pl.mul(kv_chunk, kv_chunk)\n                        kv_row_sum = pl.reshape(pl.row_sum(kv_sq), [1, KV_RMS_T_TILE])\n                        kv_sq_sum = pl.add(kv_sq_sum, kv_row_sum)\n                    kv_inv_rms = pl.rsqrt(pl.add(pl.mul(kv_sq_sum, 1.0 / HEAD_DIM), EPS), high_precision=True)\n                    kv_inv_rms_t = pl.reshape(kv_inv_rms, [KV_RMS_T_TILE, 1])\n\n                    for n0 in pl.pipeline(0, NOPE_DIM, KV_TILE, stage=2):\n                        kv_chunk = kv_fp32[tg : tg + KV_RMS_T_TILE, n0 : n0 + KV_TILE]\n                        gamma_kv_cast = pl.cast(gamma_ckv[n0 : n0 + KV_TILE], target_type=pl.FP32)\n                        gamma_kv_chunk = pl.reshape(gamma_kv_cast, [1, KV_TILE])\n                        kv_normed = pl.col_expand_mul(pl.row_expand_mul(kv_chunk, kv_inv_rms_t), gamma_kv_chunk)\n                        kv_normed_bf16 = pl.cast(kv_normed, target_type=pl.BF16, mode=\"rint\")\n                        kv_view[out_tg : out_tg + KV_RMS_T_TILE, n0 : n0 + KV_TILE] = kv_normed_bf16\n\n                    gamma_rope_cast = pl.cast(gamma_ckv[NOPE_DIM : NOPE_DIM + ROPE_DIM], target_type=pl.FP32)\n                    gamma_rope = pl.reshape(gamma_rope_cast, [1, ROPE_DIM])\n                    kv_rope_chunk = kv_fp32[tg : tg + KV_RMS_T_TILE, NOPE_DIM : NOPE_DIM + ROPE_DIM]\n                    kv_rope_norm_chunk = pl.col_expand_mul(pl.row_expand_mul(kv_rope_chunk, kv_inv_rms_t), gamma_rope)\n                    kv_cos_il_full = rope_cos_il[out_tg : out_tg + KV_RMS_T_TILE, :]\n                    kv_sin_signed_full = rope_sin_signed[out_tg : out_tg + KV_RMS_T_TILE, :]\n                    kv_swap_idx_full = rope_swap_idx[out_tg : out_tg + KV_RMS_T_TILE, :]\n                    kv_swapped_full = pl.gather(kv_rope_norm_chunk, dim=-1, index=kv_swap_idx_full)\n                    kv_rope_rot_full = pl.add(\n                        pl.mul(kv_rope_norm_chunk, kv_cos_il_full),\n                        pl.mul(kv_swapped_full, kv_sin_signed_full),\n                    )\n                    kv_rope_i16_full = pl.cast(kv_rope_rot_full, target_type=pl.BF16, mode=\"rint\")\n                    kv_view[out_tg : out_tg + KV_RMS_T_TILE, NOPE_DIM:HEAD_DIM] = kv_rope_i16_full\n                else:\n                    kv_reduce_tmp = pl.create_tile(\n                        [KV_RMS_T_TILE, KV_TILE], dtype=pl.FP32, target_memory=pl.MemorySpace.Vec\n                    )\n                    kv_sq_sum_tail = pl.tile.full([1, KV_RMS_T_TILE], dtype=pl.FP32, value=0.0)\n                    for kv_sq_col0_tail in pl.pipeline(0, HEAD_DIM, KV_TILE, stage=2):\n                        kv_chunk_tail = pl.load(\n                            kv_fp32,\n                            [tg, kv_sq_col0_tail],\n                            [KV_RMS_T_TILE, KV_TILE],\n                            valid_shape=[valid_rows, KV_TILE],\n                            target_memory=pl.MemorySpace.Vec,\n                        )\n                        kv_sq_tail = pl.mul(kv_chunk_tail, kv_chunk_tail)\n                        kv_row_sum_tail = pl.reshape(pl.row_sum(kv_sq_tail, kv_reduce_tmp), [1, KV_RMS_T_TILE])\n                        kv_sq_sum_tail = pl.add(kv_sq_sum_tail, kv_row_sum_tail)\n                    kv_inv_rms_tail = pl.recip(pl.sqrt(pl.add(pl.mul(kv_sq_sum_tail, 1.0 / HEAD_DIM), EPS)))\n                    kv_inv_rms_t_tail = pl.reshape(kv_inv_rms_tail, [KV_RMS_T_TILE, 1])\n\n                    for n0_tail in pl.pipeline(0, NOPE_DIM, KV_TILE, stage=2):\n                        kv_chunk_tail = pl.load(\n                            kv_fp32,\n                            [tg, n0_tail],\n                            [KV_RMS_T_TILE, KV_TILE],\n                            valid_shape=[valid_rows, KV_TILE],\n                            target_memory=pl.MemorySpace.Vec,\n                        )\n                        gamma_kv_input_tail = pl.load(\n                            gamma_ckv,\n                            [n0_tail],\n                            [KV_TILE],\n                            target_memory=pl.MemorySpace.Vec,\n                        )\n                        gamma_kv_cast_tail = pl.cast(gamma_kv_input_tail, target_type=pl.FP32)\n                        gamma_kv_chunk_tail = pl.reshape(gamma_kv_cast_tail, [1, KV_TILE])\n                        kv_normed_tail = pl.col_expand_mul(\n                            pl.row_expand_mul(kv_chunk_tail, kv_inv_rms_t_tail),\n                            gamma_kv_chunk_tail,\n                        )\n                        kv_normed_bf16_tail = pl.cast(kv_normed_tail, target_type=pl.BF16, mode=\"rint\")\n                        kv_normed_valid = pl.set_validshape(kv_normed_bf16_tail, valid_rows, KV_TILE)\n                        pl.store(kv_normed_valid, [out_tg, n0_tail], kv_view)\n\n                    gamma_rope_input_tail = pl.load(\n                        gamma_ckv,\n                        [NOPE_DIM],\n                        [ROPE_DIM],\n                        target_memory=pl.MemorySpace.Vec,\n                    )\n                    gamma_rope_cast_tail = pl.cast(gamma_rope_input_tail, target_type=pl.FP32)\n                    gamma_rope_tail = pl.reshape(gamma_rope_cast_tail, [1, ROPE_DIM])\n                    kv_rope_chunk_tail = pl.load(\n                        kv_fp32,\n                        [tg, NOPE_DIM],\n                        [KV_RMS_T_TILE, ROPE_DIM],\n                        valid_shape=[valid_rows, ROPE_DIM],\n                        target_memory=pl.MemorySpace.Vec,\n                    )\n                    kv_rope_norm_tail = pl.col_expand_mul(\n                        pl.row_expand_mul(kv_rope_chunk_tail, kv_inv_rms_t_tail),\n                        gamma_rope_tail,\n                    )\n                    kv_cos_il_tail = pl.load(\n                        rope_cos_il,\n                        [out_tg, 0],\n                        [KV_RMS_T_TILE, ROPE_DIM],\n                        valid_shape=[valid_rows, ROPE_DIM],\n                        target_memory=pl.MemorySpace.Vec,\n                    )\n                    kv_sin_signed_tail = pl.load(\n                        rope_sin_signed,\n                        [out_tg, 0],\n                        [KV_RMS_T_TILE, ROPE_DIM],\n                        valid_shape=[valid_rows, ROPE_DIM],\n                        target_memory=pl.MemorySpace.Vec,\n                    )\n                    kv_col = pl.col_expand_mul(\n                        pl.tile.full([KV_RMS_T_TILE, ROPE_DIM], dtype=pl.FP32, value=1.0),\n                        pl.cast(pl.tile.arange(0, [1, ROPE_DIM], dtype=pl.INT32), target_type=pl.FP32),\n                    )\n                    kv_dup_f = pl.cast(pl.cast(pl.mul(kv_col, 0.5), target_type=pl.INT32, mode=\"trunc\"), pl.FP32)\n                    kv_lane = pl.sub(kv_col, pl.mul(kv_dup_f, 2.0))\n                    kv_swap_f = pl.sub(pl.add(kv_col, 1.0), pl.mul(kv_lane, 2.0))\n                    # Row-major flattening offsets stay in fp32: col-expand is defined\n                    # for half / float only.\n                    kv_row_seed = pl.mul(\n                        pl.cast(pl.tile.arange(0, [1, KV_RMS_T_TILE], dtype=pl.INT32), target_type=pl.FP32),\n                        ROPE_DIM_SCALE,\n                    )\n                    kv_row_grid = pl.col_expand_mul(\n                        pl.tile.full([ROPE_DIM, KV_RMS_T_TILE], dtype=pl.FP32, value=1.0),\n                        kv_row_seed,\n                    )\n                    kv_row_offset = pl.transpose(kv_row_grid, axis1=0, axis2=1)\n                    kv_swap_idx_tail = pl.cast(pl.add(kv_swap_f, kv_row_offset), target_type=pl.INT32)\n                    kv_gather_tmp = pl.create_tile(\n                        [KV_RMS_T_TILE, ROPE_DIM],\n                        dtype=pl.INT32,\n                        target_memory=pl.MemorySpace.Vec,\n                    )\n                    kv_swapped_tail = pl.tile.gather(kv_rope_norm_tail, kv_swap_idx_tail, kv_gather_tmp)\n                    kv_rope_rot_tail = pl.add(\n                        pl.mul(kv_rope_norm_tail, kv_cos_il_tail),\n                        pl.mul(kv_swapped_tail, kv_sin_signed_tail),\n                    )\n                    kv_rope_i16_tail = pl.cast(kv_rope_rot_tail, target_type=pl.BF16, mode=\"rint\")\n                    kv_rope_valid = pl.set_validshape(kv_rope_i16_tail, valid_rows, ROPE_DIM)\n                    pl.store(kv_rope_valid, [out_tg, NOPE_DIM], kv_view)\n\n\n@pl.jit.inline(auto_scope=False)\ndef qkv_proj_rope(\n    x: pl.Tensor[[T_DYN, D], pl.BF16],\n    wq_a: pl.Tensor[[D, Q_LORA], pl.BF16],\n    wq_b: pl.Tensor[[Q_LORA, H * HEAD_DIM], pl.INT8],\n    wq_b_scale: pl.Tensor[[H * HEAD_DIM], pl.FP32],\n    wkv: pl.Tensor[[D, HEAD_DIM], pl.BF16],\n    rope_cos: pl.Tensor[[T_DYN, ROPE_DIM], pl.BF16],\n    rope_sin: pl.Tensor[[T_DYN, ROPE_DIM], pl.BF16],\n    gamma_cq: pl.Tensor[[Q_LORA], pl.BF16],\n    gamma_ckv: pl.Tensor[[HEAD_DIM], pl.BF16],\n    q: pl.Tensor[[T_DYN, H, HEAD_DIM], pl.BF16],\n    kv: pl.Tensor[[T_DYN, HEAD_DIM], pl.BF16],\n    qr: pl.Tensor[[T_DYN, Q_LORA], pl.INT8],\n    qr_scale: pl.Tensor[[T_DYN, 1], pl.FP32],\n    late_dep: pl.Scalar[pl.TASK_ID],\n):\n    \"\"\"Fused q + kv projection: both branches share one token axis and one rope table.\"\"\"\n    t_dim = pl.tensor.dim(x, 0)\n    q_rope_cos_il = pl.create_tensor([t_dim, ROPE_DIM], dtype=pl.FP32)\n    q_rope_sin_signed = pl.create_tensor([t_dim, ROPE_DIM], dtype=pl.FP32)\n    q_rope_swap_idx = pl.create_tensor([t_dim, ROPE_DIM], dtype=pl.INT32)\n    rope_prepare(rope_cos, rope_sin, q_rope_cos_il, q_rope_sin_signed, q_rope_swap_idx)\n    q_proj_rope(\n        x,\n        wq_a,\n        wq_b,\n        wq_b_scale,\n        gamma_cq,\n        q_rope_cos_il,\n        q_rope_sin_signed,\n        q_rope_swap_idx,\n        q,\n        qr,\n        qr_scale,\n    )\n    kv_proj_rope(\n        x,\n        wkv,\n        gamma_ckv,\n        q_rope_cos_il,\n        q_rope_sin_signed,\n        q_rope_swap_idx,\n        kv,\n        late_dep,\n    )\n    return q\n\n\n@pl.jit\ndef qkv_proj_rope_test(\n    x: pl.Tensor[[T_DYN, D], pl.BF16],\n    wq_a: pl.Tensor[[D, Q_LORA], pl.BF16],\n    wq_b: pl.Tensor[[Q_LORA, H * HEAD_DIM], pl.INT8],\n    wq_b_scale: pl.Tensor[[H * HEAD_DIM], pl.FP32],\n    wkv: pl.Tensor[[D, HEAD_DIM], pl.BF16],\n    rope_cos: pl.Tensor[[T_DYN, ROPE_DIM], pl.BF16],\n    rope_sin: pl.Tensor[[T_DYN, ROPE_DIM], pl.BF16],\n    gamma_cq: pl.Tensor[[Q_LORA], pl.BF16],\n    gamma_ckv: pl.Tensor[[HEAD_DIM], pl.BF16],\n    q: pl.Out[pl.Tensor[[T_DYN, H, HEAD_DIM], pl.BF16]],\n    kv: pl.Out[pl.Tensor[[T_DYN, HEAD_DIM], pl.BF16]],\n    qr: pl.Out[pl.Tensor[[T_DYN, Q_LORA], pl.INT8]],\n    qr_scale: pl.Out[pl.Tensor[[T_DYN, 1], pl.FP32]],\n):\n    x.bind_dynamic(0, T_DYN)\n    rope_cos.bind_dynamic(0, T_DYN)\n    rope_sin.bind_dynamic(0, T_DYN)\n    q.bind_dynamic(0, T_DYN)\n    kv.bind_dynamic(0, T_DYN)\n    qr.bind_dynamic(0, T_DYN)\n    qr_scale.bind_dynamic(0, T_DYN)\n\n    # Standalone: no rms_norm producer to fence.\n    late_dep = pl.system.task_dummy(deps=[])\n    qkv_proj_rope(\n        x,\n        wq_a,\n        wq_b,\n        wq_b_scale,\n        wkv,\n        rope_cos,\n        rope_sin,\n        gamma_cq,\n        gamma_ckv,\n        q,\n        kv,\n        qr,\n        qr_scale,\n        late_dep,\n    )\n    return q\n\n\n# Split-branch coverage geometry: q on a CP-local token slice, kv on the full run.\nSPLIT_T_FULL = PREFILL_BATCH * PREFILL_SEQ\nSPLIT_T_LOCAL = SPLIT_T_FULL // 4\n\n\n@pl.jit\ndef q_kv_split_test(\n    x_local: pl.Tensor[[SPLIT_T_LOCAL, D], pl.BF16],\n    x_full: pl.Tensor[[SPLIT_T_FULL, D], pl.BF16],\n    wq_a: pl.Tensor[[D, Q_LORA], pl.BF16],\n    wq_b: pl.Tensor[[Q_LORA, H * HEAD_DIM], pl.INT8],\n    wq_b_scale: pl.Tensor[[H * HEAD_DIM], pl.FP32],\n    wkv: pl.Tensor[[D, HEAD_DIM], pl.BF16],\n    rope_cos_local: pl.Tensor[[SPLIT_T_LOCAL, ROPE_DIM], pl.BF16],\n    rope_sin_local: pl.Tensor[[SPLIT_T_LOCAL, ROPE_DIM], pl.BF16],\n    rope_cos_full: pl.Tensor[[SPLIT_T_FULL, ROPE_DIM], pl.BF16],\n    rope_sin_full: pl.Tensor[[SPLIT_T_FULL, ROPE_DIM], pl.BF16],\n    gamma_cq: pl.Tensor[[Q_LORA], pl.BF16],\n    gamma_ckv: pl.Tensor[[HEAD_DIM], pl.BF16],\n    q: pl.Out[pl.Tensor[[SPLIT_T_LOCAL, H, HEAD_DIM], pl.BF16]],\n    qr: pl.Out[pl.Tensor[[SPLIT_T_LOCAL, Q_LORA], pl.INT8]],\n    qr_scale: pl.Out[pl.Tensor[[SPLIT_T_LOCAL, 1], pl.FP32]],\n    kv: pl.Out[pl.Tensor[[SPLIT_T_FULL, HEAD_DIM], pl.BF16]],\n):\n    \"\"\"Drive the q and kv branches at different token counts, as CP does.\"\"\"\n    q_cos_il = pl.create_tensor([SPLIT_T_LOCAL, ROPE_DIM], dtype=pl.FP32)\n    q_sin_signed = pl.create_tensor([SPLIT_T_LOCAL, ROPE_DIM], dtype=pl.FP32)\n    q_swap_idx = pl.create_tensor([SPLIT_T_LOCAL, ROPE_DIM], dtype=pl.INT32)\n    rope_prepare(rope_cos_local, rope_sin_local, q_cos_il, q_sin_signed, q_swap_idx)\n    q_proj_rope(\n        x_local,\n        wq_a,\n        wq_b,\n        wq_b_scale,\n        gamma_cq,\n        q_cos_il,\n        q_sin_signed,\n        q_swap_idx,\n        q,\n        qr,\n        qr_scale,\n    )\n\n    kv_cos_il = pl.create_tensor([SPLIT_T_FULL, ROPE_DIM], dtype=pl.FP32)\n    kv_sin_signed = pl.create_tensor([SPLIT_T_FULL, ROPE_DIM], dtype=pl.FP32)\n    kv_swap_idx = pl.create_tensor([SPLIT_T_FULL, ROPE_DIM], dtype=pl.INT32)\n    rope_prepare(rope_cos_full, rope_sin_full, kv_cos_il, kv_sin_signed, kv_swap_idx)\n    # Standalone: no rms_norm producer to fence.\n    late_dep = pl.system.task_dummy(deps=[])\n    kv_proj_rope(\n        x_full,\n        wkv,\n        gamma_ckv,\n        kv_cos_il,\n        kv_sin_signed,\n        kv_swap_idx,\n        kv,\n        late_dep,\n    )\n    return q\n\n\ndef golden_q_kv_split(tensors):\n    \"\"\"Reference: the fused golden on the full run, sliced to each branch's rows.\"\"\"\n    import torch\n\n    full = dict(tensors)\n    full[\"x\"] = tensors[\"x_full\"]\n    full[\"rope_cos\"] = tensors[\"rope_cos_full\"]\n    full[\"rope_sin\"] = tensors[\"rope_sin_full\"]\n    full[\"q\"] = torch.zeros(SPLIT_T_FULL, H, HEAD_DIM, dtype=torch.bfloat16)\n    full[\"kv\"] = torch.zeros(SPLIT_T_FULL, HEAD_DIM, dtype=torch.bfloat16)\n    full[\"qr\"] = torch.zeros(SPLIT_T_FULL, Q_LORA, dtype=torch.int8)\n    full[\"qr_scale\"] = torch.zeros(SPLIT_T_FULL, 1, dtype=torch.float32)\n    golden_qkv_proj_rope(full)\n\n    tensors[\"q\"][:] = full[\"q\"][:SPLIT_T_LOCAL]\n    tensors[\"qr\"][:] = full[\"qr\"][:SPLIT_T_LOCAL]\n    tensors[\"qr_scale\"][:] = full[\"qr_scale\"][:SPLIT_T_LOCAL]\n    tensors[\"kv\"][:] = full[\"kv\"]\n\n\ndef build_split_tensor_specs():\n    import torch\n    from golden import TensorSpec\n\n    base = {spec.name: spec for spec in build_tensor_specs(1, SPLIT_T_FULL)}\n    x_full = base[\"x\"].init_value()\n    rope_cos_full = base[\"rope_cos\"].init_value()\n    rope_sin_full = base[\"rope_sin\"].init_value()\n    x_loc = x_full[:SPLIT_T_LOCAL].clone()\n    rope_cos_loc = rope_cos_full[:SPLIT_T_LOCAL].clone()\n    rope_sin_loc = rope_sin_full[:SPLIT_T_LOCAL].clone()\n\n    return [\n        TensorSpec(\"x_local\", [SPLIT_T_LOCAL, D], torch.bfloat16, init_value=lambda: x_loc),\n        TensorSpec(\"x_full\", [SPLIT_T_FULL, D], torch.bfloat16, init_value=lambda: x_full),\n        base[\"wq_a\"],\n        base[\"wq_b\"],\n        base[\"wq_b_scale\"],\n        base[\"wkv\"],\n        TensorSpec(\n            \"rope_cos_local\", [SPLIT_T_LOCAL, ROPE_DIM], torch.bfloat16, init_value=lambda: rope_cos_loc\n        ),\n        TensorSpec(\n            \"rope_sin_local\", [SPLIT_T_LOCAL, ROPE_DIM], torch.bfloat16, init_value=lambda: rope_sin_loc\n        ),\n        TensorSpec(\n            \"rope_cos_full\", [SPLIT_T_FULL, ROPE_DIM], torch.bfloat16, init_value=lambda: rope_cos_full\n        ),\n        TensorSpec(\n            \"rope_sin_full\", [SPLIT_T_FULL, ROPE_DIM], torch.bfloat16, init_value=lambda: rope_sin_full\n        ),\n        base[\"gamma_cq\"],\n        base[\"gamma_ckv\"],\n        TensorSpec(\"q\", [SPLIT_T_LOCAL, H, HEAD_DIM], torch.bfloat16),\n        TensorSpec(\"qr\", [SPLIT_T_LOCAL, Q_LORA], torch.int8),\n        TensorSpec(\"qr_scale\", [SPLIT_T_LOCAL, 1], torch.float32),\n        TensorSpec(\"kv\", [SPLIT_T_FULL, HEAD_DIM], torch.bfloat16),\n    ]\n\n\ndef golden_qkv_proj_rope(tensors):\n    \"\"\"Torch reference: Q/KV LoRA + RoPE for an already attention-normalized input.\"\"\"\n    import torch\n    from utils import int8_quant_per_row\n\n    x = tensors[\"x\"].float()\n    wq_a = tensors[\"wq_a\"].float()\n    wq_b = tensors[\"wq_b\"]\n    wq_b_scale = tensors[\"wq_b_scale\"].float().view(-1)\n    wkv = tensors[\"wkv\"].float()\n    rope_cos = tensors[\"rope_cos\"].float()\n    rope_sin = tensors[\"rope_sin\"].float()\n    gamma_cq = tensors[\"gamma_cq\"].float()\n    gamma_ckv = tensors[\"gamma_ckv\"].float()\n\n    def rms_norm(x, gamma, eps=EPS):\n        inv = torch.rsqrt(x.square().mean(-1, keepdim=True) + eps)\n        return x * inv * gamma\n\n    def matmul_bf16_input_fp32(a, b):\n        a_fp32 = a.to(torch.bfloat16).float()\n        b_fp32 = b.to(torch.bfloat16).float()\n        return torch.matmul(a_fp32, b_fp32).float()\n\n    def apply_rope(x_rope, cos, sin):\n        # x_rope: [T, ..., ROPE_DIM] with interleaved even/odd rotary pairs.\n        x_pair = x_rope.unflatten(-1, (-1, 2))\n        x_even, x_odd = x_pair[..., 0], x_pair[..., 1]\n        cos_v = cos[..., :ROPE_HALF]\n        sin_v = sin[..., :ROPE_HALF]\n        while cos_v.ndim < x_even.ndim:\n            cos_v = cos_v.unsqueeze(-2)\n            sin_v = sin_v.unsqueeze(-2)\n        y_even = (x_even * cos_v - x_odd * sin_v).to(torch.bfloat16)\n        y_odd = (x_even * sin_v + x_odd * cos_v).to(torch.bfloat16)\n        return torch.stack([y_even, y_odd], dim=-1).flatten(-2)\n\n    t_dim = x.shape[0]\n    token_x = x.view(t_dim, D)\n\n    # Q path\n    qr_out = rms_norm(matmul_bf16_input_fp32(token_x, wq_a), gamma_cq)  # [T, Q_LORA]\n    # W8A8C16: wq_b W8 per-output-channel int8; qr_out A8 per-token int8.\n    # flash: also quantizes wq_a/wkv to fp8 (default Linear dtype).\n    qr_i8, qr_scale = int8_quant_per_row(qr_out.float())\n    q_i32 = torch.matmul(qr_i8.to(torch.int32), wq_b.to(torch.int32))\n    q_full = (q_i32.float() * qr_scale * wq_b_scale.view(1, -1)).view(t_dim, H, HEAD_DIM)\n    inv = torch.rsqrt(q_full.square().mean(-1, keepdim=True) + EPS)\n    q_full = q_full * inv  # per-head RMSNorm (no gamma)\n    q_nope = q_full[..., :NOPE_DIM]\n    q_rope = apply_rope(q_full[..., NOPE_DIM:], rope_cos, rope_sin)\n    q_out = torch.cat([q_nope, q_rope], dim=-1)\n\n    # KV path\n    kv_full = rms_norm(matmul_bf16_input_fp32(token_x, wkv), gamma_ckv)  # [T, HEAD_DIM]\n    kv_nope = kv_full[..., :NOPE_DIM]\n    kv_rope_in = kv_full[..., NOPE_DIM:].unsqueeze(1)  # add a pseudo head dim\n    kv_rope = apply_rope(kv_rope_in, rope_cos, rope_sin).squeeze(1)\n    kv_out = torch.cat([kv_nope, kv_rope], dim=-1)\n\n    tensors[\"q\"][:] = q_out.to(torch.bfloat16)\n    tensors[\"kv\"][:] = kv_out.to(torch.bfloat16)\n    tensors[\"qr\"][:] = qr_i8\n    tensors[\"qr_scale\"][:] = qr_scale\n\n\ndef build_tensor_specs(B, S):\n    import torch\n    from golden import TensorSpec\n\n    T = B * S\n\n    def quant_w_per_output_channel(w):\n        amax = w.float().abs().amax(dim=0).clamp_min(INT8_AMAX_EPS)\n        scale_quant = INT8_SCALE_MAX / amax\n        scaled = w.float() * scale_quant.view(1, H * HEAD_DIM)\n        w_i32 = torch.round(scaled).to(torch.int32)\n        w_i32 = torch.clamp(w_i32, -int(INT8_SCALE_MAX), int(INT8_SCALE_MAX))\n        w_i8 = w_i32.to(torch.float16).to(torch.int8)\n        return w_i8, (1.0 / scale_quant).float()\n\n    def init_x():\n        return torch.empty([T, D], dtype=torch.bfloat16).uniform_(-1, 1)\n\n    def init_wq_a():\n        return torch.empty([D, Q_LORA], dtype=torch.bfloat16).uniform_(-0.1, 0.1)\n\n    def init_wq_b():\n        return torch.empty([Q_LORA, H * HEAD_DIM], dtype=torch.bfloat16).uniform_(-0.1, 0.1)\n\n    def init_wkv():\n        return torch.empty([D, HEAD_DIM], dtype=torch.bfloat16).uniform_(-0.1, 0.1)\n\n    def init_cos():\n        return torch.empty([T, ROPE_DIM], dtype=torch.bfloat16).uniform_(-1, 1)\n\n    def init_sin():\n        return torch.empty([T, ROPE_DIM], dtype=torch.bfloat16).uniform_(-1, 1)\n\n    def init_gamma_cq():\n        return torch.empty([Q_LORA], dtype=torch.bfloat16).uniform_(-1, 1)\n\n    def init_gamma_ckv():\n        return torch.empty([HEAD_DIM], dtype=torch.bfloat16).uniform_(-1, 1)\n\n    wq_b_bf16 = init_wq_b().to(torch.bfloat16)\n    wq_b_i8, wq_b_scale = quant_w_per_output_channel(wq_b_bf16)\n    wq_b_scale = wq_b_scale.view(H * HEAD_DIM)\n\n    return [\n        TensorSpec(\"x\", [T, D], torch.bfloat16, init_value=init_x),\n        TensorSpec(\"wq_a\", [D, Q_LORA], torch.bfloat16, init_value=init_wq_a),\n        TensorSpec(\"wq_b\", [Q_LORA, H * HEAD_DIM], torch.int8, init_value=lambda: wq_b_i8),\n        TensorSpec(\"wq_b_scale\", [H * HEAD_DIM], torch.float32, init_value=lambda: wq_b_scale),\n        TensorSpec(\"wkv\", [D, HEAD_DIM], torch.bfloat16, init_value=init_wkv),\n        TensorSpec(\"rope_cos\", [T, ROPE_DIM], torch.bfloat16, init_value=init_cos),\n        TensorSpec(\"rope_sin\", [T, ROPE_DIM], torch.bfloat16, init_value=init_sin),\n        TensorSpec(\"gamma_cq\", [Q_LORA], torch.bfloat16, init_value=init_gamma_cq),\n        TensorSpec(\"gamma_ckv\", [HEAD_DIM], torch.bfloat16, init_value=init_gamma_ckv),\n        TensorSpec(\"q\", [T, H, HEAD_DIM], torch.bfloat16),\n        TensorSpec(\"kv\", [T, HEAD_DIM], torch.bfloat16),\n        TensorSpec(\"qr\", [T, Q_LORA], torch.int8),\n        TensorSpec(\"qr_scale\", [T, 1], torch.float32),\n    ]\n\n\nif __name__ == \"__main__\":\n    import argparse\n    from golden import ratio_allclose, run\n\n    MODES = {\n        \"decode\": (DECODE_BATCH // TP, DECODE_SEQ),\n        \"prefill\": (PREFILL_BATCH, PREFILL_SEQ),\n    }\n\n    parser = argparse.ArgumentParser()\n    parser.add_argument(\n        \"-p\", \"--platform\", type=str, default=\"a2a3\", choices=[\"a2a3\", \"a2a3sim\", \"a5\", \"a5sim\"]\n    )\n    parser.add_argument(\"-d\", \"--device\", type=int, default=0)\n    parser.add_argument(\n        \"--mode\",\n        choices=[\"decode\", \"prefill\", \"split\", \"all\"],\n        default=\"all\",\n        help=\"decode / prefill batch sizes, 'split' for mismatched q and kv rows, or 'all'.\",\n    )\n    parser.add_argument(\n        \"--enable-chip-swimlane\",\n        type=int,\n        choices=[0, 1, 2, 4],\n        default=0,\n        help=\"chip swimlane level: 0=off, 1=per-kernel AICore timing \"\n        \"(prints the per-function Task Statistics table), 2=+AICPU timing.\",\n    )\n    parser.add_argument(\"--runtime-dir\", type=str, default=None)\n    parser.add_argument(\"--golden-data\", type=str, default=None)\n    parser.add_argument(\"--compile-only\", action=\"store_true\", default=False)\n    parser.add_argument(\"--dump-passes\", action=\"store_true\", default=False)\n    args = parser.parse_args()\n\n    modes_to_run = list(MODES.keys()) + [\"split\"] if args.mode == \"all\" else [args.mode]\n\n    for mode_name in modes_to_run:\n        if mode_name == \"split\":\n            fn, specs, golden = q_kv_split_test, build_split_tensor_specs(), golden_q_kv_split\n            print(f\"--- qkv_proj_rope split: q rows={SPLIT_T_LOCAL}, kv rows={SPLIT_T_FULL} ---\")\n        else:\n            B, S = MODES[mode_name]\n            fn, specs, golden = qkv_proj_rope_test, build_tensor_specs(B, S), golden_qkv_proj_rope\n            print(f\"--- qkv_proj_rope {mode_name}: B={B}, S={S} ---\")\n        result = run(\n            fn=fn,\n            specs=specs,\n            golden_fn=golden,\n            # W8A8C16 q_proj adds INT8 quant/dequant round-off before per-head RMSNorm.\n            rtol=5e-3,\n            atol=5e-3,\n            # Precision reference: pypto mla_prolog —\n            # cann-recipes-infer/ops/pypto_python/example/test_mla_prolog_pypto.py\n            compare_fn={\n                \"q\": ratio_allclose(atol=1e-4, rtol=1.0 / 128),\n                \"kv\": ratio_allclose(atol=1e-4, rtol=1.0 / 128),\n                \"qr\": ratio_allclose(atol=1, rtol=0, max_error_ratio=0),\n                \"qr_scale\": ratio_allclose(atol=2.5e-5, rtol=5e-3),\n            },\n            runtime_dir=args.runtime_dir,\n            golden_data=args.golden_data,\n            compile_cfg=dict(dump_passes=args.dump_passes),\n            runtime_cfg=dict(\n                platform=args.platform,\n                device_id=args.device,\n                enable_chip_swimlane=args.enable_chip_swimlane,\n            ),\n            compile_only=args.compile_only,\n        )\n        if not result.passed:\n            if result.error:\n                print(result.error)\n            raise SystemExit(1)\n", "decode_compressor_ratio4.py": "# Copyright (c) PyPTO Contributors.\n# This program is free software, you can redistribute it and/or modify it under the terms and conditions of\n# CANN Open Software License Agreement Version 2.0 (the \"License\").\n# Please refer to the License for details. You may not use this file except in compliance with the License.\n# THIS SOFTWARE IS PROVIDED ON AN \"AS IS\" BASIS, WITHOUT WARRANTIES OF ANY KIND, EITHER EXPRESS OR IMPLIED,\n# INCLUDING BUT NOT LIMITED TO NON-INFRINGEMENT, MERCHANTABILITY, OR FITNESS FOR A PARTICULAR PURPOSE.\n# See LICENSE in the root of the software repository for the full text of the License.\n# -----------------------------------------------------------------------------------------------------------\n\"\"\"DeepSeek-V4 KV Compressor (decode incremental, ratio=4 overlap).\n\nUses overlapping state layout with 8 slots.\nFront slots 0-3 at columns [0:HEAD_DIM], back slots 4-7 at columns [HEAD_DIM:OUT_DIM].\nOnline-softmax pooling followed by the recurrent-state commit.\"\"\"\n\n\nimport pypto.language as pl\n\nfrom config import (\n    FLASH as M,\n    DECODE_BATCH,\n    TP,\n    DECODE_SEQ,\n    BLOCK_SIZE,\n    C4A_COMPRESSOR_BLOCK_SIZE,\n    KV_CMP_BLOCK_NUM,\n    FP32_NEG_INF,\n)\n\n\n# Dynamic shape variables. Under CP the compressor runs over the whole TP group's\n# token stream while its caller stays on the local query rows, so its token and\n# request axes are its own symbols rather than the caller's.\nB_DYN = pl.dynamic(\"DECODE_CSA_C4_B_DYN\")\nS_DYN = pl.dynamic(\"DECODE_CSA_C4_S_DYN\")\nT_DYN = pl.dynamic(\"DECODE_CSA_C4_T_DYN\")  # T = B * S\n\n# model config\nB = DECODE_BATCH // TP\nS = DECODE_SEQ\nEPS = M.rms_norm_eps\nD = M.hidden_size\nHEAD_DIM = M.head_dim\nHEAD_DIM_INV = 1.0 / HEAD_DIM\nROPE_HEAD_DIM = M.qk_rope_head_dim\nNOPE_HEAD_DIM = M.nope_head_dim\nMAX_SEQ_LEN = M.max_position_embeddings\n\n# kernel-local (ratio-4 overlapping compressor)\nCOMPRESS_RATIO = 4\nOVERLAP = COMPRESS_RATIO == 4\nCOFF = 1 + int(OVERLAP)\nOUT_DIM = COFF * HEAD_DIM\nSTATE_LEN = COFF * COMPRESS_RATIO\nCOMPRESS_STATE_BLOCK_SIZE = C4A_COMPRESSOR_BLOCK_SIZE\nCOMPRESS_STATE_MAX_BLOCKS = (STATE_LEN + COMPRESS_STATE_BLOCK_SIZE - 1) // COMPRESS_STATE_BLOCK_SIZE\nCOMPRESS_STATE_BLOCK_NUM_DYN = pl.dynamic(\"CSA_STATE_BLOCK_NUM_DYN\")\nCOMPRESS_STATE_DIM = 2 * OUT_DIM\nCMP_MAX_BLOCKS = (MAX_SEQ_LEN // COMPRESS_RATIO + BLOCK_SIZE - 1) // BLOCK_SIZE\nCMP_BLOCK_NUM = KV_CMP_BLOCK_NUM\nCMP_BLOCK_NUM_DYN = pl.dynamic(\"CMP_BLOCK_NUM_DYN\")\n\n# tiling\nK_TILE = 512\nOUT_TILE = 64\nMM_B_TILE = 16\n# Scratch spans the CP group's whole token stream, which the compressor runs\n# over, not the rank-local B * S.\nGROUP_BS = DECODE_BATCH * DECODE_SEQ\nBS_PAD = ((GROUP_BS + MM_B_TILE - 1) // MM_B_TILE) * MM_B_TILE\nHEAD_TILE = 64\nRMS_PAD_TILE = 16  # 16-row block of B (min M for FP32 vec ops)\n\n\n@pl.jit.inline\ndef compressor_ratio4(\n    x: pl.Tensor[[T_DYN, D], pl.BF16],\n    kv: pl.Tensor[[T_DYN, HEAD_DIM], pl.FP32],\n    compress_state: pl.Tensor[[COMPRESS_STATE_BLOCK_NUM_DYN, COMPRESS_STATE_BLOCK_SIZE, COMPRESS_STATE_DIM], pl.FP32],\n    compress_state_block_table: pl.Tensor[[B_DYN, COMPRESS_STATE_MAX_BLOCKS], pl.INT32],\n    wkv: pl.Tensor[[OUT_DIM, D], pl.BF16],\n    wgate: pl.Tensor[[OUT_DIM, D], pl.BF16],\n    ape: pl.Tensor[[COMPRESS_RATIO, OUT_DIM], pl.FP32],\n    norm_w: pl.Tensor[[HEAD_DIM], pl.BF16],\n    # Token-local, interleave-duplicated cos and sign-folded sin. Only ratio-4\n    # boundary rows are consumed.\n    cos: pl.Tensor[[T_DYN, ROPE_HEAD_DIM], pl.FP32],\n    sin: pl.Tensor[[T_DYN, ROPE_HEAD_DIM], pl.FP32],\n    cmp_kv_cache: pl.Tensor[[CMP_BLOCK_NUM_DYN, BLOCK_SIZE, 1, HEAD_DIM], pl.BF16],\n    position_ids: pl.Tensor[[T_DYN], pl.INT32],\n    cmp_slot_mapping: pl.Tensor[[T_DYN], pl.INT64],\n    state_slot_mapping: pl.Tensor[[T_DYN], pl.INT64],\n    late_dep: pl.Scalar[pl.TASK_ID],\n) -> tuple[pl.Tensor, pl.Scalar[pl.TASK_ID]]:\n    b_dim = pl.tensor.dim(compress_state_block_table, 0)\n    bs = pl.tensor.dim(x, 0)\n    s_dim = bs // b_dim\n    t_matmul = ((bs + MM_B_TILE - 1) // MM_B_TILE) * MM_B_TILE  # ceil to whole 16-row cube tiles\n    rms_blocks = (bs + RMS_PAD_TILE - 1) // RMS_PAD_TILE\n    x_flat = x\n    cmp4_kv_proj_pad = pl.create_tensor([BS_PAD, OUT_DIM], dtype=pl.FP32)\n    cmp4_score_proj_pad = pl.create_tensor([BS_PAD, OUT_DIM], dtype=pl.FP32)\n    compress_state_block_num = pl.tensor.dim(compress_state, 0)\n    cmp_block_num = pl.tensor.dim(cmp_kv_cache, 0)\n    compress_state_flat = pl.reshape(compress_state, [compress_state_block_num * COMPRESS_STATE_BLOCK_SIZE, COMPRESS_STATE_DIM])\n    kv_flat = kv\n    cmp_kv_cache_flat = pl.reshape(cmp_kv_cache, [cmp_block_num * BLOCK_SIZE, HEAD_DIM])\n\n    # Deferred behind the caller's rms_norm dummy barrier: qkv's qr_proj_matmul is the\n    # critical path and must win the cores when rms_norm retires.\n    with pl.spmd(\n        t_matmul * OUT_DIM // (MM_B_TILE * OUT_TILE), name_hint=\"kv_score_proj\", deps=[late_dep]\n    ) as _kv_score_tid:\n        idx = pl.tile.get_block_idx()\n        global_row0 = (idx // (OUT_DIM // OUT_TILE)) * MM_B_TILE\n        o0 = (idx % (OUT_DIM // OUT_TILE)) * OUT_TILE\n        kv_acc = pl.create_tensor([MM_B_TILE, OUT_TILE], dtype=pl.FP32)\n        score_acc = pl.create_tensor([MM_B_TILE, OUT_TILE], dtype=pl.FP32)\n        for kb in pl.pipeline(0, D // K_TILE, stage=2):\n            k0 = kb * K_TILE\n            x_rows = pl.min(MM_B_TILE, bs - global_row0)\n            x_tile = pl.slice(x_flat, [MM_B_TILE, K_TILE], [global_row0, k0], valid_shape=[x_rows, K_TILE])\n            # Weights stored transposed [OUT_DIM, D] and consumed via b_trans=True so the\n            # GM->L1 load is a DN2ZN (each [OUT_TILE, K_TILE] row is K-contiguous = long\n            # bursts) instead of ND2NZ on [K_TILE, OUT_TILE] (K strided = many short\n            # bursts). Cuts the transaction-bound MTE2 cost ~14% busy / ~7% compressor wall.\n            wkv_tile = wkv[o0 : o0 + OUT_TILE, k0 : k0 + K_TILE]\n            wgate_tile = wgate[o0 : o0 + OUT_TILE, k0 : k0 + K_TILE]\n            if k0 == 0:\n                kv_acc = pl.matmul(x_tile, wkv_tile, out_dtype=pl.FP32, b_trans=True)\n                score_acc = pl.matmul(x_tile, wgate_tile, out_dtype=pl.FP32, b_trans=True)\n            else:\n                kv_acc = pl.matmul_acc(kv_acc, x_tile, wkv_tile, b_trans=True)\n                score_acc = pl.matmul_acc(score_acc, x_tile, wgate_tile, b_trans=True)\n\n        cmp4_kv_proj_pad[global_row0 : global_row0 + MM_B_TILE, o0 : o0 + OUT_TILE] = kv_acc\n        cmp4_score_proj_pad[global_row0 : global_row0 + MM_B_TILE, o0 : o0 + OUT_TILE] = score_acc\n\n    # Pool every ratio-4 boundary against the old persistent ring plus the\n    # current-step projection overlay. State is committed only after all pools\n    # have finished, so later tokens cannot overwrite rows needed by an earlier\n    # boundary in the same S=8 step.\n    pooled_kv = pl.create_tensor([BS_PAD, HEAD_DIM], dtype=pl.FP32)\n    # One block per request: each c_idx owns its own state ring and writes only\n    # its own pooled_kv rows, so the whole nest is parallel over requests.\n    with pl.spmd(b_dim, name_hint=\"scatter_softmax_pool\", deps=[_kv_score_tid]) as pool_tid:\n        c_idx = pl.tile.get_block_idx()\n        first_pos_b = pl.read(position_ids, [c_idx * s_dim])\n        for s_idx in pl.range(s_dim):\n            token = c_idx * s_dim + s_idx\n            token_pos = pl.read(position_ids, [token])\n            pooled_kv[token : token + 1, :] = pl.full([1, HEAD_DIM], dtype=pl.FP32, value=0.0)\n            if (token_pos + 1) % COMPRESS_RATIO == 0:\n                window_start = token_pos - STATE_LEN + 1\n                for h0 in pl.range(0, HEAD_DIM, HEAD_TILE):\n                    last_ape_row = pl.cast(token_pos % COMPRESS_RATIO, target_type=pl.INDEX)\n                    mi = pl.add(\n                        cmp4_score_proj_pad[\n                            token : token + 1,\n                            HEAD_DIM + h0 : HEAD_DIM + h0 + HEAD_TILE,\n                        ],\n                        ape[\n                            last_ape_row : last_ape_row + 1,\n                            HEAD_DIM + h0 : HEAD_DIM + h0 + HEAD_TILE,\n                        ],\n                    )\n                    li = pl.exp(pl.sub(mi, mi))\n                    oi = cmp4_kv_proj_pad[\n                        token : token + 1,\n                        HEAD_DIM + h0 : HEAD_DIM + h0 + HEAD_TILE,\n                    ]\n                    for state_idx in pl.range(STATE_LEN - 1):\n                        logical_pos = window_start + state_idx\n                        value = pl.full([1, HEAD_TILE], dtype=pl.FP32, value=0.0)\n                        score = pl.full([1, HEAD_TILE], dtype=pl.FP32, value=FP32_NEG_INF)\n                        state_half = 0\n                        if state_idx >= COMPRESS_RATIO:\n                            state_half = HEAD_DIM\n                        if logical_pos >= 0 and logical_pos < first_pos_b:\n                            ring_row = logical_pos % STATE_LEN\n                            state_page_off = ring_row // COMPRESS_STATE_BLOCK_SIZE\n                            state_blk_id_i32 = pl.read(\n                                compress_state_block_table, [c_idx, state_page_off])\n                            if state_blk_id_i32 >= 0:\n                                state_blk_id = pl.cast(state_blk_id_i32, pl.INDEX)\n                                state_row = state_blk_id * COMPRESS_STATE_BLOCK_SIZE + ring_row % COMPRESS_STATE_BLOCK_SIZE\n                                value = compress_state_flat[\n                                    state_row : state_row + 1,\n                                    state_half + h0 : state_half + h0 + HEAD_TILE,\n                                ]\n                                score = compress_state_flat[\n                                    state_row : state_row + 1,\n                                    OUT_DIM + state_half + h0 : OUT_DIM + state_half + h0 + HEAD_TILE,\n                                ]\n                        if logical_pos >= first_pos_b:\n                            if logical_pos <= token_pos:\n                                overlay_token = c_idx * s_dim + logical_pos - first_pos_b\n                                ape_row = pl.cast(logical_pos % COMPRESS_RATIO, target_type=pl.INDEX)\n                                value = cmp4_kv_proj_pad[\n                                    overlay_token : overlay_token + 1,\n                                    state_half + h0 : state_half + h0 + HEAD_TILE,\n                                ]\n                                score = pl.add(\n                                    cmp4_score_proj_pad[\n                                        overlay_token : overlay_token + 1,\n                                        state_half + h0 : state_half + h0 + HEAD_TILE,\n                                    ],\n                                    ape[ape_row : ape_row + 1, state_half + h0 : state_half + h0 + HEAD_TILE],\n                                )\n                        mi_next = pl.maximum(mi, score)\n                        alpha = pl.exp(pl.sub(mi, mi_next))\n                        beta = pl.exp(pl.sub(score, mi_next))\n                        li = pl.add(pl.mul(alpha, li), beta)\n                        oi = pl.add(pl.mul(oi, alpha), pl.mul(value, beta))\n                        mi = mi_next\n                    pooled_kv[token : token + 1, h0 : h0 + HEAD_TILE] = pl.div(oi, li)\n\n    # The recurrent state ring is a commit, not a source for the current step.\n    # One block per request, like the pool above. Each token commits to its own\n    # ring row: S <= STATE_LEN, so a request's tokens hold distinct positions mod\n    # STATE_LEN, and requests hold distinct state pages.\n    with pl.spmd(b_dim, name_hint=\"compress_state_commit\", deps=[pool_tid]):\n        c_idx = pl.tile.get_block_idx()\n        for s_idx in pl.range(s_dim):\n            token = c_idx * s_dim + s_idx\n            state_row_i64 = pl.read(state_slot_mapping, [token])\n            if state_row_i64 >= 0:\n                state_row = pl.cast(state_row_i64, pl.INDEX)\n                token_pos = pl.read(position_ids, [token])\n                ape_row = pl.cast(token_pos % COMPRESS_RATIO, target_type=pl.INDEX)\n                compress_state_flat[state_row : state_row + 1, 0 : OUT_DIM] = cmp4_kv_proj_pad[\n                    token : token + 1, 0 : OUT_DIM]\n                compress_state_flat[state_row : state_row + 1, OUT_DIM : COMPRESS_STATE_DIM] = pl.add(\n                    cmp4_score_proj_pad[token : token + 1, 0 : OUT_DIM], ape[ape_row : ape_row + 1, 0 : OUT_DIM])\n\n    normed_kv = pl.create_tensor([BS_PAD, HEAD_DIM], dtype=pl.FP32)\n    norm_w_2d = pl.reshape(norm_w, [1, HEAD_DIM])\n    with pl.spmd(\n        rms_blocks, name_hint=\"rmsnorm_rope_cache_write\", deps=[pool_tid]\n    ) as cache_write_tid:\n        rms_blk = pl.tile.get_block_idx()\n        b0 = rms_blk * RMS_PAD_TILE\n        rms_blk_rows = pl.min(RMS_PAD_TILE, bs - b0)\n        cos_b = pl.slice(cos, [RMS_PAD_TILE, ROPE_HEAD_DIM], [b0, 0], valid_shape=[rms_blk_rows, ROPE_HEAD_DIM])\n        sin_b = pl.slice(sin, [RMS_PAD_TILE, ROPE_HEAD_DIM], [b0, 0], valid_shape=[rms_blk_rows, ROPE_HEAD_DIM])\n        partial_sq = pl.full([1, RMS_PAD_TILE], dtype=pl.FP32, value=0.0)\n        for k0 in pl.range(0, HEAD_DIM, HEAD_TILE):\n            kv_rms_chunk = pooled_kv[b0 : b0 + RMS_PAD_TILE, k0 : k0 + HEAD_TILE]\n            kv_rms_sq = pl.mul(kv_rms_chunk, kv_rms_chunk)\n            kv_rms_rowsum = pl.reshape(pl.row_sum(kv_rms_sq), [1, RMS_PAD_TILE])\n            partial_sq = pl.add(partial_sq, kv_rms_rowsum)\n\n        variance = pl.reshape(pl.add(pl.mul(partial_sq, HEAD_DIM_INV), EPS), [RMS_PAD_TILE, 1])\n        inv_rms = pl.recip(pl.sqrt(variance))\n        for k0 in pl.range(0, NOPE_HEAD_DIM, HEAD_TILE):\n            kv_norm_chunk = pooled_kv[b0 : b0 + RMS_PAD_TILE, k0 : k0 + HEAD_TILE]\n            gamma = pl.cast(norm_w_2d[:, k0 : k0 + HEAD_TILE], pl.FP32)\n            normed_chunk = pl.col_expand_mul(pl.row_expand_mul(kv_norm_chunk, inv_rms), gamma)\n            normed_kv[b0 : b0 + RMS_PAD_TILE, k0 : k0 + HEAD_TILE] = normed_chunk\n\n        kv_rope_norm = pooled_kv[b0 : b0 + RMS_PAD_TILE, NOPE_HEAD_DIM : HEAD_DIM]\n        gamma_rope = pl.cast(norm_w_2d[:, NOPE_HEAD_DIM : HEAD_DIM], pl.FP32)\n        # A3 interleaved swap-gather (same form as kv_rope_fused in qkv_proj_rope),\n        # replacing the de-interleave gather + rotate + re-interleave scatter. gamma+inv_rms\n        # are folded into rope_normed BEFORE the swap, so the swapped lane n[j^1] correctly\n        # carries gamma[j^1]; inv_rms is per-row so it commutes. Only swap_idx (j^1) is built\n        # in-kernel -- it permutes data, so no table can hold it; the interleaved cos and\n        # sign-folded sin come in ready to use. normed_kv is FP32 -> write directly.\n        #   out[j] = n[j]*cos_il[j] + n[j^1]*sin_il_signed[j]\n        rope_normed = pl.col_expand_mul(pl.row_expand_mul(kv_rope_norm, inv_rms), gamma_rope)\n        rope_ones = pl.full([RMS_PAD_TILE, ROPE_HEAD_DIM], dtype=pl.FP32, value=1.0)\n        rope_col = pl.col_expand_mul(rope_ones, pl.cast(pl.arange(0, [1, ROPE_HEAD_DIM], dtype=pl.INT32), target_type=pl.FP32))\n        rope_dup_f = pl.cast(pl.cast(pl.mul(rope_col, 0.5), target_type=pl.INT32, mode=\"trunc\"), target_type=pl.FP32)\n        rope_lane = pl.sub(rope_col, pl.mul(rope_dup_f, 2.0))                                          # j%2\n        rope_swap_idx = pl.cast(pl.sub(pl.add(rope_col, 1.0), pl.mul(rope_lane, 2.0)), target_type=pl.INT32)  # j^1\n        swapped = pl.gather(rope_normed, dim=-1, index=rope_swap_idx)\n        rope_rot = pl.add(pl.mul(rope_normed, cos_b), pl.mul(swapped, sin_b))\n        normed_kv[b0 : b0 + RMS_PAD_TILE, NOPE_HEAD_DIM : HEAD_DIM] = rope_rot\n\n        for inner in pl.range(rms_blk_rows):\n            token = b0 + inner\n            cache_row_i64 = pl.read(cmp_slot_mapping, [token])\n            if cache_row_i64 >= 0:\n                cache_row = pl.cast(cache_row_i64, pl.INDEX)\n                kv_row_fp32 = normed_kv[token : token + 1, 0 : HEAD_DIM]\n                kv_flat[token : token + 1, :] = kv_row_fp32\n                cmp_kv_cache_flat[cache_row : cache_row + 1, :] = pl.cast(\n                    kv_row_fp32, target_type=pl.BF16, mode=\"rint\")\n\n    return kv, cache_write_tid\n\n\n@pl.jit\ndef compressor_test(\n    x: pl.Tensor[[T_DYN, D], pl.BF16],\n    kv: pl.Out[pl.Tensor[[T_DYN, HEAD_DIM], pl.FP32]],\n    compress_state: pl.InOut[pl.Tensor[[COMPRESS_STATE_BLOCK_NUM_DYN, COMPRESS_STATE_BLOCK_SIZE, COMPRESS_STATE_DIM], pl.FP32]],\n    compress_state_block_table: pl.Tensor[[B_DYN, COMPRESS_STATE_MAX_BLOCKS], pl.INT32],\n    wkv: pl.Tensor[[OUT_DIM, D], pl.BF16],\n    wgate: pl.Tensor[[OUT_DIM, D], pl.BF16],\n    ape: pl.Tensor[[COMPRESS_RATIO, OUT_DIM], pl.FP32],\n    norm_w: pl.Tensor[[HEAD_DIM], pl.BF16],\n    cos: pl.Tensor[[T_DYN, ROPE_HEAD_DIM], pl.FP32],\n    sin: pl.Tensor[[T_DYN, ROPE_HEAD_DIM], pl.FP32],\n    cmp_kv_cache: pl.InOut[pl.Tensor[[CMP_BLOCK_NUM_DYN, BLOCK_SIZE, 1, HEAD_DIM], pl.BF16]],\n    position_ids: pl.Tensor[[T_DYN], pl.INT32],\n    cmp_slot_mapping: pl.Tensor[[T_DYN], pl.INT64],\n    state_slot_mapping: pl.Tensor[[T_DYN], pl.INT64],\n):\n    x.bind_dynamic(0, T_DYN)\n    kv.bind_dynamic(0, T_DYN)\n    compress_state_block_table.bind_dynamic(0, B_DYN)\n    cos.bind_dynamic(0, T_DYN)\n    sin.bind_dynamic(0, T_DYN)\n    position_ids.bind_dynamic(0, T_DYN)\n    cmp_slot_mapping.bind_dynamic(0, T_DYN)\n    state_slot_mapping.bind_dynamic(0, T_DYN)\n\n    # Standalone: no rms_norm producer, so the barrier fences nothing (ready on submit).\n    late_dep = pl.system.task_dummy(deps=[])\n    kv, _cache_write_tid = compressor_ratio4(\n        x,\n        kv,\n        compress_state,\n        compress_state_block_table,\n        wkv,\n        wgate,\n        ape,\n        norm_w,\n        cos,\n        sin,\n        cmp_kv_cache,\n        position_ids,\n        cmp_slot_mapping,\n        state_slot_mapping,\n        late_dep,\n    )\n    return kv, compress_state, cmp_kv_cache\n\n\ndef golden_compressor(tensors):\n    \"\"\"Torch reference for Compressor.forward (decode branch, ratio=4 overlap).\"\"\"\n    import torch\n\n    # Rows this golden never writes stay NaN: ignored by the kv comparator.\n    tensors[\"kv\"].fill_(float(\"nan\"))\n\n    x = tensors[\"x\"].float()\n    compress_state = tensors[\"compress_state\"]\n    compress_state_block_table = tensors[\"compress_state_block_table\"]\n    wkv = tensors[\"wkv\"].float()\n    wgate = tensors[\"wgate\"].float()\n    ape = tensors[\"ape\"]\n    norm_w = tensors[\"norm_w\"]\n    cos = tensors[\"cos\"]\n    sin = tensors[\"sin\"]\n    cmp_kv_cache = tensors[\"cmp_kv_cache\"]\n    position_ids = tensors[\"position_ids\"].to(torch.int64)\n    cmp_slot_mapping = tensors[\"cmp_slot_mapping\"].to(torch.int64)\n    state_slot_mapping = tensors[\"state_slot_mapping\"].to(torch.int64)\n    tokens = x.shape[0]\n    bsz = tokens // S\n    position_ids = position_ids.view(bsz, S)\n    cmp_slot_mapping = cmp_slot_mapping.view(bsz, S)\n    state_slot_mapping = state_slot_mapping.view(bsz, S)\n    ratio, rd = COMPRESS_RATIO, ROPE_HEAD_DIM\n\n    kv_proj = x @ wkv.t()\n    score_proj = x @ wgate.t()\n    old_state = compress_state.clone()\n    pooled = torch.zeros(tokens, HEAD_DIM, dtype=torch.float32, device=x.device)\n\n    for b in range(bsz):\n        first_pos = int(position_ids[b, 0].item())\n        for s in range(S):\n            token = b * S + s\n            token_pos = int(position_ids[b, s].item())\n            if (token_pos + 1) % ratio != 0:\n                continue\n            kv_rows = []\n            score_rows = []\n            for state_idx in range(STATE_LEN):\n                logical_pos = token_pos - STATE_LEN + 1 + state_idx\n                half = 0 if state_idx < ratio else HEAD_DIM\n                value = torch.zeros(HEAD_DIM, dtype=torch.float32, device=x.device)\n                score = torch.full((HEAD_DIM,), float(\"-inf\"), dtype=torch.float32, device=x.device)\n                if 0 <= logical_pos < first_pos:\n                    ring_row = logical_pos % STATE_LEN\n                    page_off, intra = divmod(ring_row, COMPRESS_STATE_BLOCK_SIZE)\n                    block = int(compress_state_block_table[b, page_off].item())\n                    if block >= 0:\n                        value = old_state[block, intra, half : half + HEAD_DIM]\n                        score = old_state[block, intra, OUT_DIM + half : OUT_DIM + half + HEAD_DIM]\n                if first_pos <= logical_pos <= token_pos:\n                    overlay = b * S + logical_pos - first_pos\n                    value = kv_proj[overlay, half : half + HEAD_DIM]\n                    score = score_proj[overlay, half : half + HEAD_DIM] + ape[\n                        logical_pos % ratio, half : half + HEAD_DIM]\n                kv_rows.append(value)\n                score_rows.append(score)\n            kvs = torch.stack(kv_rows)\n            scores = torch.stack(score_rows)\n            pooled[token] = (kvs * scores.softmax(dim=0)).sum(dim=0)\n\n    for b in range(bsz):\n        for s in range(S):\n            token = b * S + s\n            state_row = int(state_slot_mapping[b, s].item())\n            if state_row < 0:\n                continue\n            block, intra = divmod(state_row, COMPRESS_STATE_BLOCK_SIZE)\n            token_pos = int(position_ids[b, s].item())\n            compress_state[block, intra, :OUT_DIM] = kv_proj[token]\n            compress_state[block, intra, OUT_DIM:] = score_proj[token] + ape[token_pos % ratio]\n\n    tensors[\"compress_state\"][:] = compress_state\n\n    def rmsnorm(x, w):\n        x = x.float()\n        var = x.square().mean(-1, keepdim=True)\n        x = x * torch.rsqrt(var + EPS)\n        return w * x\n\n    for b in range(bsz):\n        for s in range(S):\n            token = b * S + s\n            cmp_row = int(cmp_slot_mapping[b, s].item())\n            if cmp_row < 0:\n                continue\n            kv_b = rmsnorm(pooled[token : token + 1], norm_w)\n            rope_normed = kv_b[..., -rd:]\n            rope_swapped = rope_normed.reshape(1, -1, 2).flip(-1).flatten(-2)\n            rope_rot = rope_normed * cos[token] + rope_swapped * sin[token]\n            kv_b = torch.cat([kv_b[..., :-rd], rope_rot], dim=-1)\n            tensors[\"kv\"][token : token + 1] = kv_b\n            blk_id = cmp_row // BLOCK_SIZE\n            cmp_kv_cache[blk_id, cmp_row % BLOCK_SIZE, 0] = kv_b[0]\n\n    tensors[\"cmp_kv_cache\"][:] = cmp_kv_cache\n\n\ndef build_tensor_specs(start_pos=None, batch=B):\n    import torch  # type: ignore[import]\n    from utils import (\n        block_table,\n        compressed_slot_mapping,\n        csa_decode_start_set,\n        position_ids_from_starts,\n        resolve_start_positions,\n        token_local_rope,\n    )\n    from golden import TensorSpec\n\n    def default_starts():\n        # Keep the default standalone fixture on a complete recurrent window;\n        # explicit --start-pos values still cover cold-start probes.\n        values = csa_decode_start_set(\n            batch=batch, seq=S, compress_ratio=COMPRESS_RATIO,\n            state_block_size=COMPRESS_STATE_BLOCK_SIZE)\n        return torch.where(values < STATE_LEN, values + STATE_LEN, values)\n\n    starts = resolve_start_positions(\n        start_pos,\n        batch=batch,\n        seq=S,\n        max_seq_len=MAX_SEQ_LEN,\n        default_fn=default_starts,\n    )\n    positions = position_ids_from_starts(starts, seq=S)\n    state_block_num = batch * COMPRESS_STATE_MAX_BLOCKS\n    state_block_table = torch.arange(\n        state_block_num - 1, -1, -1, dtype=torch.int32\n    ).reshape(batch, COMPRESS_STATE_MAX_BLOCKS)\n    ring_rows = positions.to(torch.int64) % STATE_LEN\n    state_pages = torch.gather(\n        state_block_table.to(torch.int64), 1, ring_rows // COMPRESS_STATE_BLOCK_SIZE)\n    state_slots = state_pages * COMPRESS_STATE_BLOCK_SIZE + ring_rows % COMPRESS_STATE_BLOCK_SIZE\n    cmp_block_table = block_table(\n        batch=batch,\n        table_blocks=CMP_MAX_BLOCKS,\n        physical_blocks=CMP_BLOCK_NUM,\n    )\n    cmp_slots = compressed_slot_mapping(\n        positions,\n        cmp_block_table,\n        compress_ratio=COMPRESS_RATIO,\n        block_size=BLOCK_SIZE,\n    )\n    rope_positions = torch.where(\n        (positions.to(torch.int64) + 1) % COMPRESS_RATIO == 0,\n        positions.to(torch.int64) - (COMPRESS_RATIO - 1),\n        torch.zeros_like(positions, dtype=torch.int64),\n    )\n    rope_cos, rope_sin = token_local_rope(\n        M,\n        COMPRESS_RATIO,\n        rope_positions,\n        max_seq_len=MAX_SEQ_LEN,\n        dtype=torch.float32,\n    )\n    rope_cos = rope_cos[:, : ROPE_HEAD_DIM // 2].repeat_interleave(2, dim=-1)\n    rope_sin = rope_sin[:, : ROPE_HEAD_DIM // 2].repeat_interleave(2, dim=-1)\n    rope_sign = torch.ones(ROPE_HEAD_DIM, dtype=torch.float32)\n    rope_sign[0::2] = -1.0\n    rope_sin = rope_sin * rope_sign\n\n    def init_x():\n        return torch.rand(batch * S, D)\n    def init_compress_state():\n        return torch.randn(\n            state_block_num, COMPRESS_STATE_BLOCK_SIZE, COMPRESS_STATE_DIM\n        ) * 0.05\n    def init_compress_state_block_table():\n        return state_block_table.clone()\n    # BF16 weight std and RMSNorm gamma mean/std, averaged over DeepSeek-V4-Flash-0731\n    # layers 8/32 (the ratio-4 CSA main compressor).\n    def init_wkv():\n        return torch.randn(OUT_DIM, D) * 0.0240\n    def init_wgate():\n        return torch.randn(OUT_DIM, D) * 0.0381\n    def init_ape():\n        return torch.randn(COMPRESS_RATIO, OUT_DIM) * 0.1226\n    def init_norm_w():\n        return 0.9569 + 0.1916 * torch.randn(HEAD_DIM)\n    def init_cos():\n        return rope_cos.clone()\n    def init_sin():\n        return rope_sin.clone()\n    def init_cmp_kv_cache():\n        return torch.zeros(CMP_BLOCK_NUM, BLOCK_SIZE, 1, HEAD_DIM)\n    def init_position_ids():\n        return positions.clone()\n    def init_state_slot_mapping():\n        return state_slots.clone()\n    def init_cmp_slot_mapping():\n        return cmp_slots.clone()\n\n    return [\n        TensorSpec(\"x\", [batch * S, D], torch.bfloat16, init_value=init_x),\n        TensorSpec(\"kv\", [batch * S, HEAD_DIM], torch.float32),\n        TensorSpec(\"compress_state\", [state_block_num, COMPRESS_STATE_BLOCK_SIZE, COMPRESS_STATE_DIM], torch.float32, init_value=init_compress_state),\n        TensorSpec(\"compress_state_block_table\", [batch, COMPRESS_STATE_MAX_BLOCKS], torch.int32, init_value=init_compress_state_block_table),\n        TensorSpec(\"wkv\", [OUT_DIM, D], torch.bfloat16, init_value=init_wkv),\n        TensorSpec(\"wgate\", [OUT_DIM, D], torch.bfloat16, init_value=init_wgate),\n        TensorSpec(\"ape\", [COMPRESS_RATIO, OUT_DIM], torch.float32, init_value=init_ape),\n        TensorSpec(\"norm_w\", [HEAD_DIM], torch.bfloat16, init_value=init_norm_w),\n        TensorSpec(\"cos\", [batch * S, ROPE_HEAD_DIM], torch.float32, init_value=init_cos),\n        TensorSpec(\"sin\", [batch * S, ROPE_HEAD_DIM], torch.float32, init_value=init_sin),\n        TensorSpec(\"cmp_kv_cache\", [CMP_BLOCK_NUM, BLOCK_SIZE, 1, HEAD_DIM], torch.bfloat16, init_value=init_cmp_kv_cache),\n        TensorSpec(\"position_ids\", [batch * S], torch.int32, init_value=lambda: init_position_ids().reshape(-1)),\n        TensorSpec(\"cmp_slot_mapping\", [batch * S], torch.int64, init_value=lambda: init_cmp_slot_mapping().reshape(-1)),\n        TensorSpec(\"state_slot_mapping\", [batch * S], torch.int64, init_value=lambda: init_state_slot_mapping().reshape(-1)),\n    ]\n\n\nif __name__ == \"__main__\":\n    import argparse\n    from golden import ratio_allclose, run\n\n    parser = argparse.ArgumentParser()\n    parser.add_argument(\"-p\", \"--platform\", type=str, default=\"a2a3\",\n                        choices=[\"a2a3\", \"a2a3sim\", \"a5\", \"a5sim\"])\n    parser.add_argument(\"-d\", \"--device\", type=int, default=0)\n    parser.add_argument(\"-b\", \"--batch\", type=int, default=B,\n                        help=f\"runtime request count up to {B} (the compile-time upper bound). \"\n                             \"The batch axes are pl.dynamic, so one compiled program \"\n                             \"serves every value.\")\n    parser.add_argument(\"--start-pos\", type=str, default=None,\n                        help=\"Fixture-only start position: one value for a uniform batch or \"\n                             \"a comma-separated value per request.\")\n    parser.add_argument(\"--enable-chip-swimlane\", action=\"store_true\", default=False)\n    parser.add_argument(\"--runtime-dir\", type=str, default=None)\n    parser.add_argument(\"--golden-data\", type=str, default=None)\n    parser.add_argument(\"--dump-passes\", action=\"store_true\", default=False)\n    args = parser.parse_args()\n    if args.batch < 1 or args.batch > B:\n        parser.error(f\"--batch must be in [1, {B}], got {args.batch}\")\n    start_pos = None\n    if args.start_pos is not None:\n        try:\n            start_values = [int(value) for value in args.start_pos.split(\",\")]\n        except ValueError:\n            parser.error(f\"--start-pos must contain integers, got {args.start_pos!r}\")\n        start_pos = start_values[0] if len(start_values) == 1 else start_values\n\n    result = run(\n        fn=compressor_test,\n        specs=build_tensor_specs(start_pos, batch=args.batch),\n        golden_fn=golden_compressor,\n        runtime_dir=args.runtime_dir,\n        golden_data=args.golden_data,\n        compile_cfg=dict(dump_passes=args.dump_passes),\n        runtime_cfg=dict(\n            platform=args.platform,\n            device_id=args.device,\n            enable_chip_swimlane=args.enable_chip_swimlane,\n        ),\n        rtol=1e-3,\n        atol=1e-3,\n        compare_fn={\n            \"kv\":          ratio_allclose(atol=1e-4, rtol=1.0 / 128, max_error_ratio=0.0, ignore_nan=True),\n            \"compress_state\":    ratio_allclose(atol=1e-3, rtol=1e-3, max_error_ratio=0.0),\n            \"cmp_kv_cache\": ratio_allclose(atol=1e-4, rtol=1.0 / 128, max_error_ratio=0.0),\n        },\n    )\n    if not result.passed:\n        if result.error:\n            print(result.error)\n        raise SystemExit(1)\n", "decode_indexer_compressor.py": "# Copyright (c) PyPTO Contributors.\n# This program is free software, you can redistribute it and/or modify it under the terms and conditions of\n# CANN Open Software License Agreement Version 2.0 (the \"License\").\n# Please refer to the License for details. You may not use this file except in compliance with the License.\n# THIS SOFTWARE IS PROVIDED ON AN \"AS IS\" BASIS, WITHOUT WARRANTIES OF ANY KIND, EITHER EXPRESS OR IMPLIED,\n# INCLUDING BUT NOT LIMITED TO NON-INFRINGEMENT, MERCHANTABILITY, OR FITNESS FOR A PARTICULAR PURPOSE.\n# See LICENSE in the root of the software repository for the full text of the License.\n# -----------------------------------------------------------------------------------------------------------\n\"\"\"DeepSeek-V4 Indexer KV Compressor (decode incremental, ratio=4 overlap).\"\"\"\n\n\nimport pypto.language as pl\n\nfrom config import (\n    FLASH as M,\n    DECODE_BATCH,\n    TP,\n    DECODE_SEQ,\n    BLOCK_SIZE,\n    C4A_COMPRESSOR_BLOCK_SIZE,\n    IDX_CACHE_BLOCK_NUM,\n    FP32_NEG_INF,\n    INT8_SCALE_MAX,\n    INT8_AMAX_EPS,\n)\n\n\n# Dynamic shape variables.\n# Under CP the indexer cache is built from the whole TP group's token stream while\n# the indexer's query half stays on the local rows, so this half carries its own\n# token and request axes.\nB_DYN = pl.dynamic(\"DECODE_IDX_C4_B_DYN\")\nS_DYN = pl.dynamic(\"DECODE_IDX_C4_S_DYN\")\nT_DYN = pl.dynamic(\"DECODE_IDX_C4_T_DYN\")  # T = B * S\n\n# model config\nB = DECODE_BATCH // TP\nS = DECODE_SEQ\nEPS = M.rms_norm_eps\nD = M.hidden_size\nHEAD_DIM = M.index_head_dim\nHEAD_DIM_INV = 1.0 / HEAD_DIM\nROPE_HEAD_DIM = M.qk_rope_head_dim\nNOPE_HEAD_DIM = M.index_nope_head_dim\nMAX_SEQ_LEN = M.max_position_embeddings\n\n# kernel-local (ratio-4 overlapping compressor)\nCOMPRESS_RATIO = 4\nOVERLAP = COMPRESS_RATIO == 4\nCOFF = 1 + int(OVERLAP)\nOUT_DIM = COFF * HEAD_DIM\nSTATE_LEN = COFF * COMPRESS_RATIO\nCOMPRESS_STATE_BLOCK_SIZE = C4A_COMPRESSOR_BLOCK_SIZE\nCOMPRESS_STATE_MAX_BLOCKS = (STATE_LEN + COMPRESS_STATE_BLOCK_SIZE - 1) // COMPRESS_STATE_BLOCK_SIZE\nCOMPRESS_STATE_DIM = 2 * OUT_DIM\nIDX_MAX_BLOCKS = (MAX_SEQ_LEN // COMPRESS_RATIO + BLOCK_SIZE - 1) // BLOCK_SIZE\nIDX_CACHE_BLOCK_NUM_DYN = pl.dynamic(\"IDX_CACHE_BLOCK_NUM_DYN\")\nCOMPRESS_STATE_BLOCK_NUM_DYN = pl.dynamic(\"INNER_STATE_BLOCK_NUM_DYN\")\n\n# tiling\nK_TILE = 512\nOUT_TILE = 64\nPROJ_OUT_TILE = 32  # kv_score_proj N-tile\nassert PROJ_OUT_TILE % 16 == 0, \"cube tile cols must be a multiple of 16\"\nMM_B_TILE = 16\n# Scratch spans the CP group's whole token stream, not the rank-local B * S.\nGROUP_BS = DECODE_BATCH * DECODE_SEQ\nBS_PAD = ((GROUP_BS + MM_B_TILE - 1) // MM_B_TILE) * MM_B_TILE\nHEAD_TILE = 64\nRMS_PAD_TILE = 16  # 16-row block of B (hadamard matmul M multiple of 16)\n\n\n@pl.jit.inline\ndef indexer_compressor(\n    x: pl.Tensor[[T_DYN, D], pl.BF16],\n    kv: pl.Tensor[[T_DYN, HEAD_DIM], pl.FP32],\n    compress_state: pl.Tensor[[COMPRESS_STATE_BLOCK_NUM_DYN, COMPRESS_STATE_BLOCK_SIZE, COMPRESS_STATE_DIM], pl.FP32],\n    compress_state_block_table: pl.Tensor[[B_DYN, COMPRESS_STATE_MAX_BLOCKS], pl.INT32],\n    wkv: pl.Tensor[[OUT_DIM, D], pl.BF16],\n    wgate: pl.Tensor[[OUT_DIM, D], pl.BF16],\n    ape: pl.Tensor[[COMPRESS_RATIO, OUT_DIM], pl.FP32],\n    norm_w: pl.Tensor[[HEAD_DIM], pl.BF16],\n    # Token-local, interleave-duplicated cos and sign-folded sin. Only ratio-4\n    # boundary rows are consumed.\n    cos: pl.Tensor[[T_DYN, ROPE_HEAD_DIM], pl.FP32],\n    sin: pl.Tensor[[T_DYN, ROPE_HEAD_DIM], pl.FP32],\n    hadamard: pl.Tensor[[HEAD_DIM, HEAD_DIM], pl.BF16],\n    idx_kv_cache: pl.Tensor[[IDX_CACHE_BLOCK_NUM_DYN, BLOCK_SIZE, 1, HEAD_DIM], pl.INT8],\n    idx_kv_scale: pl.Tensor[[IDX_CACHE_BLOCK_NUM_DYN, BLOCK_SIZE, 1, 1], pl.FP32],\n    position_ids: pl.Tensor[[T_DYN], pl.INT32],\n    idx_slot_mapping: pl.Tensor[[T_DYN], pl.INT64],\n    inner_state_slot_mapping: pl.Tensor[[T_DYN], pl.INT64],\n    late_dep: pl.Scalar[pl.TASK_ID],\n):\n    b_dim = pl.tensor.dim(compress_state_block_table, 0)\n    bs = pl.tensor.dim(x, 0)\n    s_dim = bs // b_dim\n    t_matmul = ((bs + MM_B_TILE - 1) // MM_B_TILE) * MM_B_TILE  # ceil to whole 16-row cube tiles\n    rms_blocks = (bs + RMS_PAD_TILE - 1) // RMS_PAD_TILE\n    x_flat = x\n    kv_proj_pad = pl.create_tensor([BS_PAD, OUT_DIM], dtype=pl.FP32)\n    score_proj_pad = pl.create_tensor([BS_PAD, OUT_DIM], dtype=pl.FP32)\n    compress_state_block_num = pl.tensor.dim(compress_state, 0)\n    idx_block_num = pl.tensor.dim(idx_kv_cache, 0)\n    compress_state_flat = pl.reshape(compress_state, [compress_state_block_num * COMPRESS_STATE_BLOCK_SIZE, COMPRESS_STATE_DIM])\n    kv_flat = kv\n    idx_kv_cache_flat = pl.reshape(idx_kv_cache, [idx_block_num * BLOCK_SIZE, HEAD_DIM])\n    idx_kv_scale_flat = pl.reshape(idx_kv_scale, [idx_block_num * BLOCK_SIZE, 1])\n\n    # Deferred behind the caller's rms_norm dummy barrier: qkv's qr_proj_matmul is the\n    # critical path and must win the cores when rms_norm retires.\n    with pl.spmd(\n        t_matmul * OUT_DIM // (MM_B_TILE * PROJ_OUT_TILE), name_hint=\"kv_score_proj\", deps=[late_dep]\n    ) as _kv_score_tid:\n        idx = pl.tile.get_block_idx()\n        global_row0 = (idx // (OUT_DIM // PROJ_OUT_TILE)) * MM_B_TILE\n        o0 = (idx % (OUT_DIM // PROJ_OUT_TILE)) * PROJ_OUT_TILE\n        kv_acc = pl.create_tensor([MM_B_TILE, PROJ_OUT_TILE], dtype=pl.FP32)\n        score_acc = pl.create_tensor([MM_B_TILE, PROJ_OUT_TILE], dtype=pl.FP32)\n        for kb in pl.pipeline(0, D // K_TILE, stage=2):\n            k0 = kb * K_TILE\n            x_rows = pl.min(MM_B_TILE, bs - global_row0)\n            x_tile = pl.slice(x_flat, [MM_B_TILE, K_TILE], [global_row0, k0], valid_shape=[x_rows, K_TILE])\n            # Weights stored transposed [OUT_DIM, D] and consumed via b_trans=True so the\n            # GM->L1 load is a DN2ZN (each [PROJ_OUT_TILE, K_TILE] row is K-contiguous = long\n            # bursts) instead of ND2NZ on [K_TILE, PROJ_OUT_TILE] (K strided = many short\n            # bursts). Mirrors the main compressor (decode_compressor_ratio4); the strided\n            # ND2NZ form here was ~2x slower on this matmul (43us -> ~20us per task).\n            wkv_tile = wkv[o0 : o0 + PROJ_OUT_TILE, k0 : k0 + K_TILE]\n            wgate_tile = wgate[o0 : o0 + PROJ_OUT_TILE, k0 : k0 + K_TILE]\n            if k0 == 0:\n                kv_acc = pl.matmul(x_tile, wkv_tile, out_dtype=pl.FP32, b_trans=True)\n                score_acc = pl.matmul(x_tile, wgate_tile, out_dtype=pl.FP32, b_trans=True)\n            else:\n                kv_acc = pl.matmul_acc(kv_acc, x_tile, wkv_tile, b_trans=True)\n                score_acc = pl.matmul_acc(score_acc, x_tile, wgate_tile, b_trans=True)\n\n        kv_proj_pad[global_row0 : global_row0 + MM_B_TILE, o0 : o0 + PROJ_OUT_TILE] = kv_acc\n        score_proj_pad[global_row0 : global_row0 + MM_B_TILE, o0 : o0 + PROJ_OUT_TILE] = score_acc\n\n    # Pool every ratio-4 boundary against the old persistent ring plus the\n    # current-step projection overlay. State is committed only after all pools\n    # have finished, so later tokens cannot overwrite rows needed by an earlier\n    # boundary in the same S=8 step.\n    pooled_kv = pl.create_tensor([BS_PAD, HEAD_DIM], dtype=pl.FP32)\n    # One block per request: each c_idx owns its own state ring and writes only\n    # its own pooled_kv rows, so the whole nest is parallel over requests.\n    with pl.spmd(b_dim, name_hint=\"scatter_softmax_pool\", deps=[_kv_score_tid]) as pool_tid:\n        c_idx = pl.tile.get_block_idx()\n        first_pos_b = pl.read(position_ids, [c_idx * s_dim])\n        for s_idx in pl.range(s_dim):\n            token = c_idx * s_dim + s_idx\n            token_pos = pl.read(position_ids, [token])\n            pooled_kv[token : token + 1, :] = pl.full([1, HEAD_DIM], dtype=pl.FP32, value=0.0)\n            if (token_pos + 1) % COMPRESS_RATIO == 0:\n                window_start = token_pos - STATE_LEN + 1\n                for h0 in pl.range(0, HEAD_DIM, HEAD_TILE):\n                    last_ape_row = pl.cast(token_pos % COMPRESS_RATIO, target_type=pl.INDEX)\n                    mi = pl.add(\n                        score_proj_pad[\n                            token : token + 1,\n                            HEAD_DIM + h0 : HEAD_DIM + h0 + HEAD_TILE,\n                        ],\n                        ape[\n                            last_ape_row : last_ape_row + 1,\n                            HEAD_DIM + h0 : HEAD_DIM + h0 + HEAD_TILE,\n                        ],\n                    )\n                    li = pl.exp(pl.sub(mi, mi))\n                    oi = kv_proj_pad[\n                        token : token + 1,\n                        HEAD_DIM + h0 : HEAD_DIM + h0 + HEAD_TILE,\n                    ]\n                    for state_idx in pl.range(STATE_LEN - 1):\n                        logical_pos = window_start + state_idx\n                        value = pl.full([1, HEAD_TILE], dtype=pl.FP32, value=0.0)\n                        score = pl.full([1, HEAD_TILE], dtype=pl.FP32, value=FP32_NEG_INF)\n                        state_half = 0\n                        if state_idx >= COMPRESS_RATIO:\n                            state_half = HEAD_DIM\n                        if logical_pos >= 0 and logical_pos < first_pos_b:\n                            ring_row = logical_pos % STATE_LEN\n                            state_page_off = ring_row // COMPRESS_STATE_BLOCK_SIZE\n                            state_blk_id_i32 = pl.read(\n                                compress_state_block_table, [c_idx, state_page_off])\n                            if state_blk_id_i32 >= 0:\n                                state_blk_id = pl.cast(state_blk_id_i32, pl.INDEX)\n                                state_row = state_blk_id * COMPRESS_STATE_BLOCK_SIZE + ring_row % COMPRESS_STATE_BLOCK_SIZE\n                                value = compress_state_flat[\n                                    state_row : state_row + 1,\n                                    state_half + h0 : state_half + h0 + HEAD_TILE,\n                                ]\n                                score = compress_state_flat[\n                                    state_row : state_row + 1,\n                                    OUT_DIM + state_half + h0 : OUT_DIM + state_half + h0 + HEAD_TILE,\n                                ]\n                        if logical_pos >= first_pos_b:\n                            if logical_pos <= token_pos:\n                                overlay_token = c_idx * s_dim + logical_pos - first_pos_b\n                                ape_row = pl.cast(logical_pos % COMPRESS_RATIO, target_type=pl.INDEX)\n                                value = kv_proj_pad[\n                                    overlay_token : overlay_token + 1,\n                                    state_half + h0 : state_half + h0 + HEAD_TILE,\n                                ]\n                                score = pl.add(\n                                    score_proj_pad[\n                                        overlay_token : overlay_token + 1,\n                                        state_half + h0 : state_half + h0 + HEAD_TILE,\n                                    ],\n                                    ape[\n                                        ape_row : ape_row + 1,\n                                        state_half + h0 : state_half + h0 + HEAD_TILE,\n                                    ],\n                                )\n                        mi_next = pl.maximum(mi, score)\n                        alpha = pl.exp(pl.sub(mi, mi_next))\n                        beta = pl.exp(pl.sub(score, mi_next))\n                        li = pl.add(pl.mul(alpha, li), beta)\n                        oi = pl.add(pl.mul(oi, alpha), pl.mul(value, beta))\n                        mi = mi_next\n                    pooled_kv[token : token + 1, h0 : h0 + HEAD_TILE] = pl.div(oi, li)\n\n    # The recurrent state ring is a commit, not a source for the current step.\n    # One block per request, like the pool above. Each token commits to its own\n    # ring row: S <= STATE_LEN, so a request's tokens hold distinct positions mod\n    # STATE_LEN, and requests hold distinct state pages.\n    with pl.spmd(b_dim, name_hint=\"compress_state_commit\", deps=[pool_tid]):\n        c_idx = pl.tile.get_block_idx()\n        for s_idx in pl.range(s_dim):\n            token = c_idx * s_dim + s_idx\n            state_row_i64 = pl.read(inner_state_slot_mapping, [token])\n            if state_row_i64 >= 0:\n                state_row = pl.cast(state_row_i64, pl.INDEX)\n                token_pos = pl.read(position_ids, [token])\n                ape_row = pl.cast(token_pos % COMPRESS_RATIO, target_type=pl.INDEX)\n                compress_state_flat[state_row : state_row + 1, 0 : OUT_DIM] = kv_proj_pad[\n                    token : token + 1, 0 : OUT_DIM]\n                compress_state_flat[state_row : state_row + 1, OUT_DIM : COMPRESS_STATE_DIM] = pl.add(\n                    score_proj_pad[token : token + 1, 0 : OUT_DIM],\n                    ape[ape_row : ape_row + 1, 0 : OUT_DIM],\n                )\n\n    normed_kv = pl.create_tensor([BS_PAD, HEAD_DIM], dtype=pl.BF16)\n    norm_w_2d = pl.reshape(norm_w, [1, HEAD_DIM])\n    with pl.spmd(rms_blocks, name_hint=\"rmsnorm_rope\", deps=[pool_tid]) as rms_tid:\n        rms_blk = pl.tile.get_block_idx()\n        # one 16-row token block; rows rms_blk_rows..15 are pad on the tail block.\n        # cos/sin arrive interleave-duplicated and sign-folded, so these land at the\n        # full ROPE_HEAD_DIM width and feed the rotation with no in-scope dup-gather.\n        b0 = rms_blk * RMS_PAD_TILE\n        rms_blk_rows = pl.min(RMS_PAD_TILE, bs - b0)\n        cos_b = pl.slice(cos, [RMS_PAD_TILE, ROPE_HEAD_DIM], [b0, 0], valid_shape=[rms_blk_rows, ROPE_HEAD_DIM])\n        sin_b = pl.slice(sin, [RMS_PAD_TILE, ROPE_HEAD_DIM], [b0, 0], valid_shape=[rms_blk_rows, ROPE_HEAD_DIM])\n        partial_sq = pl.full([1, RMS_PAD_TILE], dtype=pl.FP32, value=0.0)\n        for k0 in pl.pipeline(0, HEAD_DIM, HEAD_TILE, stage=2):\n            kv_rms_chunk = pooled_kv[b0 : b0 + RMS_PAD_TILE, k0 : k0 + HEAD_TILE]\n            kv_rms_sq = pl.mul(kv_rms_chunk, kv_rms_chunk)\n            kv_rms_rowsum = pl.reshape(pl.row_sum(kv_rms_sq), [1, RMS_PAD_TILE])\n            partial_sq = pl.add(partial_sq, kv_rms_rowsum)\n\n        variance = pl.reshape(pl.add(pl.mul(partial_sq, HEAD_DIM_INV), EPS), [RMS_PAD_TILE, 1])\n        inv_rms = pl.recip(pl.sqrt(variance))\n        for k0 in pl.pipeline(0, NOPE_HEAD_DIM, HEAD_TILE, stage=2):\n            kv_norm_chunk = pooled_kv[b0 : b0 + RMS_PAD_TILE, k0 : k0 + HEAD_TILE]\n            gamma = pl.cast(norm_w_2d[:, k0 : k0 + HEAD_TILE], pl.FP32)\n            normed_chunk = pl.col_expand_mul(pl.row_expand_mul(kv_norm_chunk, inv_rms), gamma)\n            normed_kv[b0 : b0 + RMS_PAD_TILE, k0 : k0 + HEAD_TILE] = pl.cast(\n                normed_chunk,\n                target_type=pl.BF16,\n                mode=\"rint\",\n            )\n\n        kv_rope_norm = pooled_kv[b0 : b0 + RMS_PAD_TILE, NOPE_HEAD_DIM : HEAD_DIM]\n        gamma_rope = pl.cast(norm_w_2d[:, NOPE_HEAD_DIM : HEAD_DIM], pl.FP32)\n        # A3 interleaved swap-gather (same form as kv_rms_norm_rope in qkv_proj_rope),\n        # replacing the de-interleave gather + rotate + re-interleave scatter. gamma+inv_rms\n        # are folded into rope_normed BEFORE the swap, so the swapped lane n[j^1] correctly\n        # carries gamma[j^1]; inv_rms is per-row so it commutes. Only swap_idx (j^1) is built\n        # in-kernel -- it permutes data, so no table can hold it; the interleaved cos and\n        # sign-folded sin come in ready to use. normed_kv is BF16 -> cast on write.\n        #   out[j] = n[j]*cos_il[j] + n[j^1]*sin_il_signed[j]\n        rope_normed = pl.col_expand_mul(pl.row_expand_mul(kv_rope_norm, inv_rms), gamma_rope)\n        rope_ones = pl.full([RMS_PAD_TILE, ROPE_HEAD_DIM], dtype=pl.FP32, value=1.0)\n        rope_col = pl.col_expand_mul(rope_ones, pl.cast(pl.arange(0, [1, ROPE_HEAD_DIM], dtype=pl.INT32), target_type=pl.FP32))\n        rope_dup_f = pl.cast(pl.cast(pl.mul(rope_col, 0.5), target_type=pl.INT32, mode=\"trunc\"), target_type=pl.FP32)\n        rope_lane = pl.sub(rope_col, pl.mul(rope_dup_f, 2.0))                                          # j%2\n        rope_swap_idx = pl.cast(pl.sub(pl.add(rope_col, 1.0), pl.mul(rope_lane, 2.0)), target_type=pl.INT32)  # j^1\n        swapped = pl.gather(rope_normed, dim=-1, index=rope_swap_idx)\n        rope_rot = pl.add(pl.mul(rope_normed, cos_b), pl.mul(swapped, sin_b))\n        normed_kv[b0 : b0 + RMS_PAD_TILE, NOPE_HEAD_DIM : HEAD_DIM] = pl.cast(\n            rope_rot,\n            target_type=pl.BF16,\n            mode=\"rint\",\n        )\n\n    kv_final = pl.create_tensor([BS_PAD, HEAD_DIM], dtype=pl.FP32)\n    with pl.spmd(rms_blocks, name_hint=\"kv_hadamard\", deps=[rms_tid]) as hadamard_tid:\n        had_blk = pl.tile.get_block_idx()\n        had_b0 = had_blk * RMS_PAD_TILE\n        kv_proj_tile = normed_kv[had_b0 : had_b0 + RMS_PAD_TILE, 0 : HEAD_DIM]\n        for o0 in pl.range(0, HEAD_DIM, OUT_TILE):\n            hadamard_tile = hadamard[0 : HEAD_DIM, o0 : o0 + OUT_TILE]\n            kv_hadamard_acc = pl.matmul(kv_proj_tile, hadamard_tile, out_dtype=pl.FP32)\n            kv_final[had_b0 : had_b0 + RMS_PAD_TILE, o0 : o0 + OUT_TILE] = kv_hadamard_acc\n\n    with pl.spmd(rms_blocks, name_hint=\"kv_and_cache_write\", deps=[hadamard_tid]) as _write_tid:\n        wr_blk = pl.tile.get_block_idx()\n        # C8 quant-on-write: per-row INT8 quant of the block (M=RMS_PAD_TILE keeps tiles 32B-aligned;\n        # quantize the bf16-rounded value to match golden)\n        wr_b0 = wr_blk * RMS_PAD_TILE\n        wr_blk_rows = pl.min(RMS_PAD_TILE, bs - wr_b0)\n        kv_blk_f32 = pl.cast(\n            pl.cast(kv_final[wr_b0 : wr_b0 + RMS_PAD_TILE, 0 : HEAD_DIM], target_type=pl.BF16, mode=\"rint\"),\n            target_type=pl.FP32)\n        # amax = max(|x|); abs-based (max(row_max, -row_min) is wrong on signed KV)\n        kv_amax = pl.reshape(pl.row_max(pl.abs(kv_blk_f32)), [1, RMS_PAD_TILE])\n        kv_amax = pl.maximum(kv_amax, pl.full([1, RMS_PAD_TILE], dtype=pl.FP32, value=INT8_AMAX_EPS))\n        kv_scale_q_row = pl.div(pl.full([1, RMS_PAD_TILE], dtype=pl.FP32, value=INT8_SCALE_MAX), kv_amax)\n        kv_scale_dq_col = pl.reshape(pl.recip(kv_scale_q_row), [RMS_PAD_TILE, 1])\n        kv_scale_q_col = pl.reshape(kv_scale_q_row, [RMS_PAD_TILE, 1])\n        kv_scaled = pl.row_expand_mul(kv_blk_f32, kv_scale_q_col)\n        kv_i32 = pl.cast(kv_scaled, target_type=pl.INT32, mode=\"rint\")\n        kv_half = pl.cast(kv_i32, target_type=pl.FP16, mode=\"round\")\n        kv_i8_blk = pl.cast(kv_half, target_type=pl.INT8, mode=\"trunc\")\n        for inner in pl.range(wr_blk_rows):\n            token = wr_b0 + inner\n            cache_row_i64 = pl.read(idx_slot_mapping, [token])\n            if cache_row_i64 >= 0:\n                cache_row = pl.cast(cache_row_i64, pl.INDEX)\n                kv_flat[token : token + 1, :] = kv_final[token : token + 1, 0 : HEAD_DIM]\n                idx_kv_cache_flat[cache_row : cache_row + 1, :] = kv_i8_blk[inner : inner + 1, :]\n                # scale is one value per position; a [1,1] tile store is sub-32B, so scalar-write it\n                pl.write(idx_kv_scale_flat, [cache_row, 0], pl.read(kv_scale_dq_col, [inner, 0]))\n\n    return _write_tid\n\n\n@pl.jit\ndef compressor_test(\n    x: pl.Tensor[[T_DYN, D], pl.BF16],\n    kv: pl.Out[pl.Tensor[[T_DYN, HEAD_DIM], pl.FP32]],\n    compress_state: pl.InOut[pl.Tensor[[COMPRESS_STATE_BLOCK_NUM_DYN, COMPRESS_STATE_BLOCK_SIZE, COMPRESS_STATE_DIM], pl.FP32]],\n    compress_state_block_table: pl.Tensor[[B_DYN, COMPRESS_STATE_MAX_BLOCKS], pl.INT32],\n    wkv: pl.Tensor[[OUT_DIM, D], pl.BF16],\n    wgate: pl.Tensor[[OUT_DIM, D], pl.BF16],\n    ape: pl.Tensor[[COMPRESS_RATIO, OUT_DIM], pl.FP32],\n    norm_w: pl.Tensor[[HEAD_DIM], pl.BF16],\n    cos: pl.Tensor[[T_DYN, ROPE_HEAD_DIM], pl.FP32],\n    sin: pl.Tensor[[T_DYN, ROPE_HEAD_DIM], pl.FP32],\n    hadamard: pl.Tensor[[HEAD_DIM, HEAD_DIM], pl.BF16],\n    idx_kv_cache: pl.InOut[pl.Tensor[[IDX_CACHE_BLOCK_NUM_DYN, BLOCK_SIZE, 1, HEAD_DIM], pl.INT8]],\n    idx_kv_scale: pl.InOut[pl.Tensor[[IDX_CACHE_BLOCK_NUM_DYN, BLOCK_SIZE, 1, 1], pl.FP32]],\n    position_ids: pl.Tensor[[T_DYN], pl.INT32],\n    idx_slot_mapping: pl.Tensor[[T_DYN], pl.INT64],\n    inner_state_slot_mapping: pl.Tensor[[T_DYN], pl.INT64],\n):\n    x.bind_dynamic(0, T_DYN)\n    kv.bind_dynamic(0, T_DYN)\n    compress_state_block_table.bind_dynamic(0, B_DYN)\n    cos.bind_dynamic(0, T_DYN)\n    sin.bind_dynamic(0, T_DYN)\n    position_ids.bind_dynamic(0, T_DYN)\n    idx_slot_mapping.bind_dynamic(0, T_DYN)\n    inner_state_slot_mapping.bind_dynamic(0, T_DYN)\n\n    # Standalone: no rms_norm producer, so the barrier fences nothing (ready on submit).\n    late_dep = pl.system.task_dummy(deps=[])\n    indexer_compressor(\n        x,\n        kv,\n        compress_state,\n        compress_state_block_table,\n        wkv,\n        wgate,\n        ape,\n        norm_w,\n        cos,\n        sin,\n        hadamard,\n        idx_kv_cache,\n        idx_kv_scale,\n        position_ids,\n        idx_slot_mapping,\n        inner_state_slot_mapping,\n        late_dep,\n    )\n    return kv, compress_state, idx_kv_cache, idx_kv_scale\n\n\ndef golden_compressor(tensors):\n    \"\"\"Torch reference for Compressor.forward (decode branch, ratio=4 overlap).\"\"\"\n    import torch\n\n    # Rows this golden never writes stay NaN: ignored by the kv comparator.\n    tensors[\"kv\"].fill_(float(\"nan\"))\n\n    x = tensors[\"x\"].float()\n    compress_state = tensors[\"compress_state\"]\n    compress_state_block_table = tensors[\"compress_state_block_table\"]\n    wkv = tensors[\"wkv\"].float()\n    wgate = tensors[\"wgate\"].float()\n    ape = tensors[\"ape\"]\n    norm_w = tensors[\"norm_w\"]\n    cos = tensors[\"cos\"]\n    sin = tensors[\"sin\"]\n    hadamard = tensors[\"hadamard\"].float()\n    idx_kv_cache = tensors[\"idx_kv_cache\"]\n    idx_kv_scale = tensors[\"idx_kv_scale\"]\n    position_ids = tensors[\"position_ids\"].to(torch.int64)\n    idx_slot_mapping = tensors[\"idx_slot_mapping\"].to(torch.int64)\n    inner_state_slot_mapping = tensors[\"inner_state_slot_mapping\"].to(torch.int64)\n    tokens = x.shape[0]\n    bsz = tokens // S\n    position_ids = position_ids.view(bsz, S)\n    idx_slot_mapping = idx_slot_mapping.view(bsz, S)\n    inner_state_slot_mapping = inner_state_slot_mapping.view(bsz, S)\n    ratio, rd = COMPRESS_RATIO, ROPE_HEAD_DIM\n\n    kv_proj = x @ wkv.t()\n    score_proj = x @ wgate.t()\n    old_state = compress_state.clone()\n    pooled = torch.zeros(tokens, HEAD_DIM, dtype=torch.float32, device=x.device)\n\n    for b in range(bsz):\n        first_pos = int(position_ids[b, 0].item())\n        for s in range(S):\n            token = b * S + s\n            token_pos = int(position_ids[b, s].item())\n            if (token_pos + 1) % ratio != 0:\n                continue\n            kv_rows = []\n            score_rows = []\n            for state_idx in range(STATE_LEN):\n                logical_pos = token_pos - STATE_LEN + 1 + state_idx\n                state_half = 0 if state_idx < ratio else HEAD_DIM\n                if logical_pos < 0:\n                    kv_rows.append(torch.zeros(HEAD_DIM, dtype=torch.float32, device=x.device))\n                    score_rows.append(torch.full((HEAD_DIM,), float(\"-inf\"), dtype=torch.float32, device=x.device))\n                elif logical_pos < first_pos:\n                    ring_row = logical_pos % STATE_LEN\n                    page_off, intra = divmod(ring_row, COMPRESS_STATE_BLOCK_SIZE)\n                    block = int(compress_state_block_table[b, page_off].item())\n                    if block >= 0:\n                        kv_rows.append(old_state[block, intra, state_half : state_half + HEAD_DIM])\n                        score_rows.append(\n                            old_state[block, intra, OUT_DIM + state_half : OUT_DIM + state_half + HEAD_DIM])\n                    else:\n                        kv_rows.append(torch.zeros(HEAD_DIM, dtype=torch.float32, device=x.device))\n                        score_rows.append(torch.full(\n                            (HEAD_DIM,), float(\"-inf\"), dtype=torch.float32, device=x.device))\n                else:\n                    overlay_token = b * S + logical_pos - first_pos\n                    kv_rows.append(kv_proj[overlay_token, state_half : state_half + HEAD_DIM])\n                    score_rows.append(\n                        score_proj[overlay_token, state_half : state_half + HEAD_DIM]\n                        + ape[logical_pos % ratio, state_half : state_half + HEAD_DIM])\n            kvs = torch.stack(kv_rows, dim=0)\n            scores = torch.stack(score_rows, dim=0)\n            pooled[token] = (kvs * scores.softmax(dim=0)).sum(dim=0)\n\n    for b in range(bsz):\n        for s in range(S):\n            token = b * S + s\n            state_row = int(inner_state_slot_mapping[b, s].item())\n            if state_row < 0:\n                continue\n            block, intra = divmod(state_row, COMPRESS_STATE_BLOCK_SIZE)\n            token_pos = int(position_ids[b, s].item())\n            compress_state[block, intra, :OUT_DIM] = kv_proj[token]\n            compress_state[block, intra, OUT_DIM:] = score_proj[token] + ape[token_pos % ratio]\n\n    tensors[\"compress_state\"][:] = compress_state\n\n    def rmsnorm(x, w):\n        x = x.float()\n        var = x.square().mean(-1, keepdim=True)\n        x = x * torch.rsqrt(var + EPS)\n        return w * x\n\n    for b in range(bsz):\n        for s in range(S):\n            token = b * S + s\n            token_pos = int(position_ids[b, s].item())\n            if (token_pos + 1) % ratio != 0:\n                continue\n            kv_b = rmsnorm(pooled[token : token + 1], norm_w)\n            rope_normed = kv_b[..., -rd:]\n            rope_swapped = rope_normed.reshape(1, -1, 2).flip(-1).flatten(-2)\n            rope_rot = rope_normed * cos[token] + rope_swapped * sin[token]\n            kv_b = torch.cat([kv_b[..., :-rd], rope_rot], dim=-1)\n            kv_b = kv_b.to(torch.bfloat16).float() @ hadamard\n\n            cache_row = int(idx_slot_mapping[b, s].item())\n            if cache_row < 0:\n                continue\n            tensors[\"kv\"][token : token + 1, :] = kv_b\n            blk_id = cache_row // BLOCK_SIZE\n            intra = cache_row % BLOCK_SIZE\n            # C8 quant-on-write: quantize the bf16-rounded compressed row to int8 + per-position scale\n            row_bf16 = kv_b[0].to(torch.bfloat16).float()\n            amax = row_bf16.abs().amax().clamp_min(INT8_AMAX_EPS)\n            scale_q = INT8_SCALE_MAX / amax\n            idx_kv_cache[blk_id, intra, 0] = torch.round(row_bf16 * scale_q).to(torch.int32).to(torch.float16).to(torch.int8)\n            idx_kv_scale[blk_id, intra, 0, 0] = 1.0 / scale_q\n\n    tensors[\"idx_kv_cache\"][:] = idx_kv_cache\n    tensors[\"idx_kv_scale\"][:] = idx_kv_scale\n\n\ndef build_tensor_specs(start_pos=None, batch=B):\n    import torch  # type: ignore[import]\n    from utils import (\n        block_table,\n        compressed_slot_mapping,\n        csa_decode_start_set,\n        position_ids_from_starts,\n        resolve_start_positions,\n        token_local_rope,\n    )\n    from golden import TensorSpec\n\n    def default_starts():\n        # Keep the default standalone fixture on a complete recurrent window;\n        # explicit --start-pos values still cover cold-start probes.\n        values = csa_decode_start_set(\n            batch=batch, seq=S, compress_ratio=COMPRESS_RATIO,\n            state_block_size=COMPRESS_STATE_BLOCK_SIZE)\n        return torch.where(values < STATE_LEN, values + STATE_LEN, values)\n\n    starts = resolve_start_positions(\n        start_pos,\n        batch=batch,\n        seq=S,\n        max_seq_len=MAX_SEQ_LEN,\n        default_fn=default_starts,\n    )\n    positions = position_ids_from_starts(starts, seq=S)\n    state_block_num = batch * COMPRESS_STATE_MAX_BLOCKS\n    state_block_table = torch.arange(\n        state_block_num - 1, -1, -1, dtype=torch.int32\n    ).reshape(batch, COMPRESS_STATE_MAX_BLOCKS)\n    ring_rows = positions.to(torch.int64) % STATE_LEN\n    state_pages = torch.gather(\n        state_block_table.to(torch.int64), 1, ring_rows // COMPRESS_STATE_BLOCK_SIZE)\n    state_slots = state_pages * COMPRESS_STATE_BLOCK_SIZE + ring_rows % COMPRESS_STATE_BLOCK_SIZE\n    idx_block_table = block_table(\n        batch=batch,\n        table_blocks=IDX_MAX_BLOCKS,\n        physical_blocks=IDX_CACHE_BLOCK_NUM,\n    )\n    idx_slots = compressed_slot_mapping(\n        positions,\n        idx_block_table,\n        compress_ratio=COMPRESS_RATIO,\n        block_size=BLOCK_SIZE,\n    )\n    rope_positions = torch.where(\n        (positions.to(torch.int64) + 1) % COMPRESS_RATIO == 0,\n        positions.to(torch.int64) - (COMPRESS_RATIO - 1),\n        torch.zeros_like(positions, dtype=torch.int64),\n    )\n    rope_cos, rope_sin = token_local_rope(\n        M,\n        COMPRESS_RATIO,\n        rope_positions,\n        max_seq_len=MAX_SEQ_LEN,\n        dtype=torch.float32,\n    )\n    rope_cos = rope_cos[:, : ROPE_HEAD_DIM // 2].repeat_interleave(2, dim=-1)\n    rope_sin = rope_sin[:, : ROPE_HEAD_DIM // 2].repeat_interleave(2, dim=-1)\n    rope_sign = torch.ones(ROPE_HEAD_DIM, dtype=torch.float32)\n    rope_sign[0::2] = -1.0\n    rope_sin = rope_sin * rope_sign\n\n    def init_x():\n        return torch.rand(batch * S, D)\n    def init_compress_state():\n        return torch.randn(\n            state_block_num, COMPRESS_STATE_BLOCK_SIZE, COMPRESS_STATE_DIM\n        ) * 0.05\n    def init_compress_state_block_table():\n        return state_block_table.clone()\n    # BF16 weight std and RMSNorm gamma mean/std, averaged over DeepSeek-V4-Flash-0731\n    # layers 8/32 (the CSA inner / indexer compressor).\n    def init_wkv():\n        return torch.randn(OUT_DIM, D) * 0.0270\n    def init_wgate():\n        return torch.randn(OUT_DIM, D) * 0.0513\n    def init_ape():\n        return torch.randn(COMPRESS_RATIO, OUT_DIM) * 0.1524\n    def init_norm_w():\n        return 0.6903 + 0.2663 * torch.randn(HEAD_DIM)\n    def init_cos():\n        return rope_cos.clone()\n    def init_sin():\n        return rope_sin.clone()\n    def init_hadamard():\n        return torch.rand(HEAD_DIM, HEAD_DIM) * (HEAD_DIM ** -0.5)\n    def init_idx_kv_cache():\n        return torch.zeros(IDX_CACHE_BLOCK_NUM, BLOCK_SIZE, 1, HEAD_DIM, dtype=torch.int8)\n    def init_idx_kv_scale():\n        return torch.zeros(IDX_CACHE_BLOCK_NUM, BLOCK_SIZE, 1, 1)\n    def init_position_ids():\n        return positions.clone()\n    def init_inner_state_slot_mapping():\n        return state_slots.clone()\n    def init_idx_slot_mapping():\n        return idx_slots.clone()\n\n    return [\n        TensorSpec(\"x\", [batch * S, D], torch.bfloat16, init_value=init_x),\n        TensorSpec(\"kv\", [batch * S, HEAD_DIM], torch.float32),\n        TensorSpec(\"compress_state\", [state_block_num, COMPRESS_STATE_BLOCK_SIZE, COMPRESS_STATE_DIM], torch.float32, init_value=init_compress_state),\n        TensorSpec(\"compress_state_block_table\", [batch, COMPRESS_STATE_MAX_BLOCKS], torch.int32, init_value=init_compress_state_block_table),\n        TensorSpec(\"wkv\", [OUT_DIM, D], torch.bfloat16, init_value=init_wkv),\n        TensorSpec(\"wgate\", [OUT_DIM, D], torch.bfloat16, init_value=init_wgate),\n        TensorSpec(\"ape\", [COMPRESS_RATIO, OUT_DIM], torch.float32, init_value=init_ape),\n        TensorSpec(\"norm_w\", [HEAD_DIM], torch.bfloat16, init_value=init_norm_w),\n        TensorSpec(\"cos\", [batch * S, ROPE_HEAD_DIM], torch.float32, init_value=init_cos),\n        TensorSpec(\"sin\", [batch * S, ROPE_HEAD_DIM], torch.float32, init_value=init_sin),\n        TensorSpec(\"hadamard\", [HEAD_DIM, HEAD_DIM], torch.bfloat16, init_value=init_hadamard),\n        TensorSpec(\"idx_kv_cache\", [IDX_CACHE_BLOCK_NUM, BLOCK_SIZE, 1, HEAD_DIM], torch.int8, init_value=init_idx_kv_cache),\n        TensorSpec(\"idx_kv_scale\", [IDX_CACHE_BLOCK_NUM, BLOCK_SIZE, 1, 1], torch.float32, init_value=init_idx_kv_scale),\n        TensorSpec(\"position_ids\", [batch * S], torch.int32, init_value=lambda: init_position_ids().reshape(-1)),\n        TensorSpec(\"idx_slot_mapping\", [batch * S], torch.int64, init_value=lambda: init_idx_slot_mapping().reshape(-1)),\n        TensorSpec(\"inner_state_slot_mapping\", [batch * S], torch.int64, init_value=lambda: init_inner_state_slot_mapping().reshape(-1)),\n    ]\n\n\nif __name__ == \"__main__\":\n    import argparse\n    from golden import ratio_allclose, run\n\n    parser = argparse.ArgumentParser()\n    parser.add_argument(\"-p\", \"--platform\", type=str, default=\"a2a3\",\n                        choices=[\"a2a3\", \"a2a3sim\", \"a5\", \"a5sim\"])\n    parser.add_argument(\"-d\", \"--device\", type=int, default=0)\n    parser.add_argument(\"-b\", \"--batch\", type=int, default=B,\n                        help=f\"runtime request count up to {B} (the compile-time upper bound). \"\n                             \"The batch axes are pl.dynamic, so one compiled program \"\n                             \"serves every value.\")\n    parser.add_argument(\"--start-pos\", type=str, default=None,\n                        help=\"Fixture-only start position: one value for a uniform batch or \"\n                             \"a comma-separated value per request.\")\n    parser.add_argument(\"--enable-chip-swimlane\", action=\"store_true\", default=False)\n    parser.add_argument(\"--runtime-dir\", type=str, default=None)\n    parser.add_argument(\"--golden-data\", type=str, default=None)\n    parser.add_argument(\"--dump-passes\", action=\"store_true\", default=False)\n    args = parser.parse_args()\n    if args.batch < 1 or args.batch > B:\n        parser.error(f\"--batch must be in [1, {B}], got {args.batch}\")\n    start_pos = None\n    if args.start_pos is not None:\n        try:\n            start_values = [int(value) for value in args.start_pos.split(\",\")]\n        except ValueError:\n            parser.error(f\"--start-pos must contain integers, got {args.start_pos!r}\")\n        start_pos = start_values[0] if len(start_values) == 1 else start_values\n\n    result = run(\n        fn=compressor_test,\n        specs=build_tensor_specs(start_pos, batch=args.batch),\n        golden_fn=golden_compressor,\n        runtime_dir=args.runtime_dir,\n        golden_data=args.golden_data,\n        compile_cfg=dict(dump_passes=args.dump_passes),\n        runtime_cfg=dict(\n            platform=args.platform,\n            device_id=args.device,\n            enable_chip_swimlane=args.enable_chip_swimlane,\n        ),\n        rtol=1e-3,\n        atol=1e-3,\n        compare_fn={\n            # kv leaves the 128x128 hadamard rotation, so an element is a 128-term sum of\n            # rows reaching |x| ~ 10 and the row's dynamic range runs past 1e4:1. Its error\n            # floor is set by that input scale, not by the cancelled output, so atol carries\n            # it -- a 1e-4 floor asks small elements for a relative accuracy the bf16 inputs\n            # cannot hold. rtol still bounds the large elements.\n            \"kv\":          ratio_allclose(atol=1e-3, rtol=1.0 / 128, max_error_ratio=0.0, ignore_nan=True),\n            \"compress_state\": ratio_allclose(atol=1e-3, rtol=1e-3, max_error_ratio=0.0),\n            \"idx_kv_cache\": ratio_allclose(atol=1, rtol=0, max_error_ratio=0.01),\n            \"idx_kv_scale\": ratio_allclose(atol=1e-4, rtol=1.0 / 128, max_error_ratio=0.01),\n        },\n    )\n    if not result.passed:\n        if result.error:\n            print(result.error)\n        raise SystemExit(1)\n", "decode_indexer.py": "# Copyright (c) PyPTO Contributors.\n# This program is free software, you can redistribute it and/or modify it under the terms and conditions of\n# CANN Open Software License Agreement Version 2.0 (the \"License\").\n# Please refer to the License for details. You may not use this file except in compliance with the License.\n# THIS SOFTWARE IS PROVIDED ON AN \"AS IS\" BASIS, WITHOUT WARRANTIES OF ANY KIND, EITHER EXPRESS OR IMPLIED,\n# INCLUDING BUT NOT LIMITED TO NON-INFRINGEMENT, MERCHANTABILITY, OR FITNESS FOR A PARTICULAR PURPOSE.\n# See LICENSE in the root of the software repository for the full text of the License.\n# -----------------------------------------------------------------------------------------------------------\n\"\"\"DeepSeek-V4 Indexer (decode). Mirrors model.py Indexer (line 380-433);\ngolden is a port of forward's decode branch (prefill `start_pos == 0` path is omitted).\nThe inner Compressor is invoked via golden_compressor (placeholder).\"\"\"\n\n\nimport pypto.language as pl\n\nfrom config import (\n    FLASH as M,\n    DECODE_BATCH,\n    TP,\n    DECODE_SEQ,\n    BLOCK_SIZE,\n    C4A_COMPRESSOR_BLOCK_SIZE,\n    FP32_NEG_INF,\n    INT8_SCALE_MAX,\n    INT8_AMAX_EPS,\n)\nfrom decode_indexer_compressor import indexer_compressor\n\n# Dynamic shape variables. S stays static: the score/topk scopes divide by it.\nB_DYN = pl.dynamic(\"B_DYN\")\nT_DYN = pl.dynamic(\"T_DYN\")  # T = B * S\n\n# model config\nB = DECODE_BATCH // TP\nS = DECODE_SEQ\nT = B * S\nD = M.hidden_size\nQ_LORA = M.q_lora_rank\nROPE_HEAD_DIM = M.qk_rope_head_dim\nIDX_N_HEADS = M.index_n_heads\nIDX_HEAD_DIM = M.index_head_dim\nIDX_NOPE_HEAD_DIM = M.index_nope_head_dim\nWEIGHTS_SCALE = M.index_weights_scale\nMAX_SEQ_LEN = M.max_position_embeddings\n\n# kernel-local\nCOMPRESS_RATIO = 4   # the indexer only runs on ratio-4 layers\nIDX_TOPK = M.index_topk\nINNER_OVERLAP = COMPRESS_RATIO == 4\nINNER_COFF = 1 + int(INNER_OVERLAP)\nINNER_HEAD_DIM = IDX_HEAD_DIM\nINNER_OUT_DIM = INNER_COFF * INNER_HEAD_DIM\nINNER_STATE_BLOCK_SIZE = C4A_COMPRESSOR_BLOCK_SIZE\nINNER_STATE_LEN = INNER_COFF * COMPRESS_RATIO\nINNER_STATE_MAX_BLOCKS = (\n    INNER_STATE_LEN + INNER_STATE_BLOCK_SIZE - 1\n) // INNER_STATE_BLOCK_SIZE\nINNER_STATE_BLOCK_NUM_DYN = pl.dynamic(\"INNER_STATE_BLOCK_NUM_DYN\")\nINNER_STATE_DIM = 2 * INNER_OUT_DIM\n\nIDX_MAX_ROWS = MAX_SEQ_LEN // COMPRESS_RATIO\nIDX_MAX_BLOCKS = (IDX_MAX_ROWS + BLOCK_SIZE - 1) // BLOCK_SIZE\nIDX_CACHE_BLOCK_NUM_DYN = pl.dynamic(\"IDX_CACHE_BLOCK_NUM_DYN\")\n\n# tiling\nCACHE_TILE = min(64, BLOCK_SIZE)\nassert BLOCK_SIZE % CACHE_TILE == 0, \"CACHE_TILE must not cross a paged idx_kv_cache block\"\nQ_TILE = 256\n# Q_OUT_TILE is the per-task N granularity (sets idx_qr_proj task count); MM_N_TILE\n# is the Mat-safe cube N-tile. Q_OUT_TILE fans Q_OUT_TILE // MM_N_TILE cube ops per\n# task so task count halves without growing the [Q_TILE, MM_N_TILE] L1 wq load.\nQ_OUT_TILE = 1024\nT_PAD = ((T + 16 - 1) // 16) * 16  # static upper bound on the token axis\n# Matmul M at the 16-row cube floor: a tile taller than the dynamic source is not expressible.\nMM_ROW_TILE = 16\n# INT32 Acc is MM_ROW_TILE * MM_N_TILE * 4B and must stay under the 128KiB L0C wall.\nMM_N_TILE = min(512, (128 * 1024) // (MM_ROW_TILE * 4))\nQR_OT_COUNT = IDX_N_HEADS * IDX_HEAD_DIM // Q_OUT_TILE  # qr_proj N-tasks per row block\nassert Q_OUT_TILE % MM_N_TILE == 0\n# Dequant token tile: a whole-T [T, Q_OUT_TILE] FP32 tile does not fit UB.\nDEQUANT_T_TILE = min(T, 8)\nassert T % DEQUANT_T_TILE == 0\nHEAD_DIM_TILE = 32\nD_TILE = 512\n# weights_proj splits K, not N: a [D_TILE, IDX_N_HEADS] row block reads contiguous GM,\n# while an N slice would take 32B out of every 128B row. Each task writes its own\n# partial row block, summed by a separate reduce scope. Partials are laid out\n# [K slice][T_PAD rows] so the reduce adds whole T_PAD-row blocks.\n# WEIGHTS_K_SLICE // D_TILE == 2, so the inner loop is a pl.range: a degenerate\n# 2-iteration pl.pipeline(stage=2) miscompiles over matmul.\nWEIGHTS_OK = 4\nWEIGHTS_K_SLICE = D // WEIGHTS_OK\nassert WEIGHTS_K_SLICE % D_TILE == 0\nQH_QUANT_TILE = 64\n# cube tile for q @ hadamard; L0C caps it at QH_MM_TILE * IDX_HEAD_DIM * 4B <= 64KiB.\nQH_MM_TILE = 64\nQH_HEAD_DIM_TILE = 64\nROPE_ROW_BLOCK = IDX_N_HEADS\n# qr_rope SPMD tile == row block: one ROPE_ROW_TILE-row block per SPMD tile.\nROPE_ROW_TILE = 32\nassert IDX_N_HEADS >= ROPE_ROW_TILE and IDX_N_HEADS % ROPE_ROW_TILE == 0\nTOPK_PAIR_WIDTH = 2 * IDX_TOPK\n\n# Exact Top-K geometry for the 1M selector.\nTOPK_CANDIDATES_PER_LEAF = 8192\nTOPK_MAX_CANDIDATES = IDX_MAX_ROWS\nTOPK_MAX_LEAVES = TOPK_MAX_CANDIDATES // TOPK_CANDIDATES_PER_LEAF\nTOPK_LEAVES_PER_GROUP = 2\nTOPK_GROUPS_PER_QUERY = TOPK_MAX_LEAVES // TOPK_LEAVES_PER_GROUP\n# Each AIV reduces one group at a time. Group roots survive until the query\n# merge; each worker reuses a two-row scratch for its current group.\nTOPK_GROUP_WORKERS = 48\nTOPK_GROUP_ROOT_ROWS = T_PAD * TOPK_GROUPS_PER_QUERY\nTOPK_GROUP_SCRATCH_ROWS = TOPK_GROUP_WORKERS * TOPK_LEAVES_PER_GROUP\nTOPK_ARENA_ROWS = TOPK_GROUP_ROOT_ROWS + TOPK_GROUP_SCRATCH_ROWS\n# One persistent mixed worker per physical 910B AIC. The workers share one\n# global leaf sequence, so ragged queries cannot strand per-query lanes.\nTOPK_SCORE_WORKERS = 24\nassert TOPK_MAX_CANDIDATES % TOPK_CANDIDATES_PER_LEAF == 0\nassert TOPK_MAX_LEAVES == 32\nassert TOPK_MAX_LEAVES % TOPK_LEAVES_PER_GROUP == 0\nassert TOPK_GROUPS_PER_QUERY == 16\n\n\n@pl.jit.inline\ndef merge2_top512_pairs(\n    pair_arena: pl.Tensor,\n    left_slot: pl.Scalar[pl.INDEX],\n    right_slot: pl.Scalar[pl.INDEX],\n    output_slot: pl.Scalar[pl.INDEX],\n) -> None:\n    \"\"\"Merge two arena rows and store their exact Top-512 pair row.\"\"\"\n    left = pl.load(\n        pair_arena, [left_slot, 0], [1, TOPK_PAIR_WIDTH]\n    )\n    right = pl.load(\n        pair_arena, [right_slot, 0], [1, TOPK_PAIR_WIDTH]\n    )\n    merge_tmp = pl.tile.create([1, 2 * TOPK_PAIR_WIDTH], dtype=pl.FP32)\n    merged_all = pl.tile.mrgsort(left, right, tmp=merge_tmp)\n    merged = pl.tile.slice(\n        merged_all, [1, TOPK_PAIR_WIDTH], [0, 0]\n    )\n    pl.store(merged, [output_slot, 0], pair_arena)\n\n\n@pl.jit.inline\ndef merge_topk_level_pairs(\n    pair_arena: pl.Tensor,\n    arena_base: pl.Scalar[pl.INDEX],\n    input_count: pl.Scalar[pl.INDEX],\n    input_base: pl.Scalar[pl.INDEX],\n    output_base: pl.Scalar[pl.INDEX],\n) -> None:\n    \"\"\"Reduce one exact-Top-K forest level, forwarding an odd final node.\"\"\"\n    output_count = (input_count + 1) // 2\n    for output in pl.range(output_count):\n        left_slot = arena_base + input_base + 2 * output\n        right_slot = left_slot + 1\n        output_slot = arena_base + output_base + output\n        if right_slot < arena_base + input_base + input_count:\n            merge2_top512_pairs(\n                pair_arena,\n                left_slot,\n                right_slot,\n                output_slot,\n            )\n        else:\n            forwarded = pl.load(\n                pair_arena, [left_slot, 0], [1, TOPK_PAIR_WIDTH]\n            )\n            pl.store(forwarded, [output_slot, 0], pair_arena)\n\n\n@pl.jit.inline\ndef indexer_topk_leaf(\n    score_arena: pl.Tensor[[T_DYN, TOPK_MAX_CANDIDATES], pl.FP32],\n    pair_arena: pl.Tensor[[TOPK_ARENA_ROWS, TOPK_PAIR_WIDTH], pl.FP32],\n    query: pl.Scalar[pl.INDEX],\n    logical_begin: pl.Scalar[pl.INDEX],\n    valid_count: pl.Scalar[pl.INDEX],\n    output_slot: pl.Scalar[pl.INDEX],\n) -> None:\n    \"\"\"Sort one scored 8K leaf and store its exact Top-512 pair row.\"\"\"\n    logical_begin_i32 = pl.cast(logical_begin, pl.INT32)\n    leaf_indices = pl.add(\n        pl.tile.arange(\n            0,\n            [1, TOPK_CANDIDATES_PER_LEAF],\n            dtype=pl.INT32,\n        ),\n        logical_begin_i32,\n    )\n    leaf_scores_raw = pl.load(\n        score_arena,\n        [query, logical_begin],\n        [1, TOPK_CANDIDATES_PER_LEAF],\n        valid_shape=[1, valid_count],\n    )\n    leaf_scores = pl.tile.fillpad(\n        leaf_scores_raw,\n        pad_value=pl.PadValue.min,\n    )\n    leaf_scores = pl.maximum(\n        leaf_scores,\n        pl.tile.full(\n            [1, TOPK_CANDIDATES_PER_LEAF],\n            dtype=pl.FP32,\n            value=FP32_NEG_INF,\n        ),\n    )\n    pairs = pl.sort32(\n        leaf_scores,\n        pl.reinterpret_view(leaf_indices, pl.UINT32),\n    )\n    pairs = pl.mrgsort(pairs, block_len=64)\n    pairs = pl.mrgsort(pairs, block_len=256)\n    pairs = pl.mrgsort(pairs, block_len=1024)\n    pairs = pl.mrgsort(pairs, block_len=4096)\n    pl.store(\n        pl.tile.slice(pairs, [1, TOPK_PAIR_WIDTH], [0, 0]),\n        [output_slot, 0],\n        pair_arena,\n    )\n\n\n@pl.jit.incore\ndef indexer_topk_group_wave(\n    position_ids: pl.Tensor[[T_DYN], pl.INT32],\n    kv_seq_lens: pl.Tensor[[B_DYN], pl.INT32],\n    score_arena: pl.Tensor[[T_DYN, TOPK_MAX_CANDIDATES], pl.FP32],\n    pair_arena: pl.Tensor[[TOPK_ARENA_ROWS, TOPK_PAIR_WIDTH], pl.FP32],\n):\n    \"\"\"Reduce globally striped two-leaf subtrees into compact roots.\"\"\"\n    worker = pl.tile.get_block_idx()\n    query_count = pl.tensor.dim(position_ids, 0)\n    global_group_base = 0\n    for query in pl.range(query_count):\n        batch_idx = query // S\n        position = pl.read(position_ids, [query])\n        cache_len = pl.read(kv_seq_lens, [batch_idx]) // COMPRESS_RATIO\n        visible_count = pl.max(\n            pl.min(\n                pl.min(cache_len, (position + 1) // COMPRESS_RATIO),\n                TOPK_MAX_CANDIDATES,\n            ),\n            0,\n        )\n        leaf_count = (\n            visible_count + TOPK_CANDIDATES_PER_LEAF - 1\n        ) // TOPK_CANDIDATES_PER_LEAF\n        group_count = (\n            leaf_count + TOPK_LEAVES_PER_GROUP - 1\n        ) // TOPK_LEAVES_PER_GROUP\n        base_mod = global_group_base % TOPK_GROUP_WORKERS\n        first_group = (worker + base_mod) % TOPK_GROUP_WORKERS\n        for group in pl.range(\n            first_group, group_count, TOPK_GROUP_WORKERS\n        ):\n            leaf_begin = group * TOPK_LEAVES_PER_GROUP\n            group_leaf_count = pl.min(\n                TOPK_LEAVES_PER_GROUP,\n                leaf_count - leaf_begin,\n            )\n            group_root_slot = (\n                query * TOPK_GROUPS_PER_QUERY + group\n            )\n            if group_leaf_count == 1:\n                logical_begin = (\n                    leaf_begin * TOPK_CANDIDATES_PER_LEAF\n                )\n                valid_count = pl.min(\n                    TOPK_CANDIDATES_PER_LEAF,\n                    visible_count - logical_begin,\n                )\n                indexer_topk_leaf(\n                    score_arena,\n                    pair_arena,\n                    query,\n                    logical_begin,\n                    valid_count,\n                    group_root_slot,\n                )\n            else:\n                scratch_base = (\n                    TOPK_GROUP_ROOT_ROWS\n                    + worker * TOPK_LEAVES_PER_GROUP\n                )\n                for group_leaf in pl.unroll(TOPK_LEAVES_PER_GROUP):\n                    leaf = leaf_begin + group_leaf\n                    logical_begin = (\n                        leaf * TOPK_CANDIDATES_PER_LEAF\n                    )\n                    valid_count = pl.min(\n                        TOPK_CANDIDATES_PER_LEAF,\n                        visible_count - logical_begin,\n                    )\n                    indexer_topk_leaf(\n                        score_arena,\n                        pair_arena,\n                        query,\n                        logical_begin,\n                        valid_count,\n                        scratch_base + group_leaf,\n                    )\n                merge2_top512_pairs(\n                    pair_arena,\n                    scratch_base,\n                    scratch_base + 1,\n                    group_root_slot,\n                )\n        global_group_base = global_group_base + group_count\n\n\n@pl.jit.incore\ndef indexer_topk_query_merge(\n    position_ids: pl.Tensor[[T_DYN], pl.INT32],\n    kv_seq_lens: pl.Tensor[[B_DYN], pl.INT32],\n    pair_arena: pl.Tensor[[TOPK_ARENA_ROWS, TOPK_PAIR_WIDTH], pl.FP32],\n    topk_scores: pl.Tensor[[T_DYN, IDX_TOPK], pl.FP32],\n    topk_indices: pl.Tensor[[T_DYN, IDX_TOPK], pl.INT32],\n):\n    \"\"\"Merge compact group roots and materialize each query's Top-512.\"\"\"\n    query = pl.tile.get_block_idx()\n    batch_idx = query // S\n    position = pl.read(position_ids, [query])\n    cache_len = pl.read(kv_seq_lens, [batch_idx]) // COMPRESS_RATIO\n    visible_count = pl.min(\n        pl.min(cache_len, (position + 1) // COMPRESS_RATIO),\n        TOPK_MAX_CANDIDATES,\n    )\n    pl.store(\n        pl.tile.full(\n            [1, IDX_TOPK],\n            dtype=pl.FP32,\n            value=FP32_NEG_INF,\n        ),\n        [query, 0],\n        topk_scores,\n    )\n    pl.store(\n        pl.tile.full(\n            [1, IDX_TOPK], dtype=pl.INT32, value=-1\n        ),\n        [query, 0],\n        topk_indices,\n    )\n\n    if visible_count > 0:\n        leaf_count = (\n            visible_count + TOPK_CANDIDATES_PER_LEAF - 1\n        ) // TOPK_CANDIDATES_PER_LEAF\n        group_count = (\n            leaf_count + TOPK_LEAVES_PER_GROUP - 1\n        ) // TOPK_LEAVES_PER_GROUP\n        arena_base = query * TOPK_GROUPS_PER_QUERY\n        if group_count > 1:\n            level1_count = (group_count + 1) // 2\n            merge_topk_level_pairs(\n                pair_arena,\n                arena_base,\n                group_count,\n                0,\n                0,\n            )\n            if level1_count > 1:\n                level2_count = (level1_count + 1) // 2\n                merge_topk_level_pairs(\n                    pair_arena,\n                    arena_base,\n                    level1_count,\n                    0,\n                    0,\n                )\n                if level2_count > 1:\n                    level3_count = (level2_count + 1) // 2\n                    merge_topk_level_pairs(\n                        pair_arena,\n                        arena_base,\n                        level2_count,\n                        0,\n                        0,\n                    )\n                    if level3_count > 1:\n                        merge_topk_level_pairs(\n                            pair_arena,\n                            arena_base,\n                            level3_count,\n                            0,\n                            0,\n                        )\n\n        root_slot = arena_base\n        root_pairs = pl.load(\n            pair_arena,\n            [root_slot, 0],\n            [1, TOPK_PAIR_WIDTH],\n        )\n        pl.store(\n            pl.tile.gather_mask(\n                root_pairs,\n                mask_pattern=pl.tile.MaskPattern.P0101,\n                output_dtype=pl.FP32,\n            ),\n            [query, 0],\n            topk_scores,\n        )\n        root_indices = pl.tile.gather_mask(\n            root_pairs,\n            mask_pattern=pl.tile.MaskPattern.P1010,\n            output_dtype=pl.INT32,\n        )\n        output_indices = pl.tile.full(\n            [1, IDX_TOPK], dtype=pl.INT32, value=-1\n        )\n        valid_topk = pl.min(visible_count, IDX_TOPK)\n        for lane in pl.range(valid_topk):\n            pl.tile.write(\n                output_indices,\n                [0, lane],\n                pl.tile.read(root_indices, [0, lane]),\n            )\n        pl.store(\n            output_indices, [query, 0], topk_indices\n        )\n\n\n@pl.jit.inline(auto_scope=False)\ndef indexer_score_topk_forest(\n    qr_hadamard_i8: pl.Tensor[\n        [T_PAD * IDX_N_HEADS, IDX_HEAD_DIM], pl.INT8\n    ],\n    qr_hadamard_scale_dq: pl.Tensor[\n        [T_PAD * IDX_N_HEADS, 1], pl.FP32\n    ],\n    weights: pl.Tensor[[T_PAD, IDX_N_HEADS], pl.FP32],\n    idx_kv_cache: pl.Tensor[\n        [IDX_CACHE_BLOCK_NUM_DYN, BLOCK_SIZE, 1, IDX_HEAD_DIM], pl.INT8\n    ],\n    idx_kv_scale: pl.Tensor[\n        [IDX_CACHE_BLOCK_NUM_DYN, BLOCK_SIZE, 1, 1], pl.FP32\n    ],\n    idx_block_table: pl.Tensor[[B_DYN, IDX_MAX_BLOCKS], pl.INT32],\n    position_ids: pl.Tensor[[T_DYN], pl.INT32],\n    kv_seq_lens: pl.Tensor[[B_DYN], pl.INT32],\n    topk_scores: pl.Out[\n        pl.Tensor[[T_DYN, IDX_TOPK], pl.FP32]\n    ],\n    topk_idxs: pl.Out[\n        pl.Tensor[[T_DYN, IDX_TOPK], pl.INT32]\n    ],\n    qh_quant_tid: pl.Scalar[pl.TASK_ID],\n    weights_tid: pl.Scalar[pl.TASK_ID],\n    cache_write_tid: pl.Scalar[pl.TASK_ID],\n):\n    \"\"\"Run exact Top-K with the score and pair arenas on separate rings.\"\"\"\n    bs = pl.tensor.dim(position_ids, 0)\n    b_dim = pl.tensor.dim(idx_block_table, 0)\n    idx_block_num = pl.tensor.dim(idx_kv_cache, 0)\n    idx_table_len = b_dim * IDX_MAX_BLOCKS\n    kv_cache_i8_flat = pl.reshape(\n        idx_kv_cache,\n        [idx_block_num * BLOCK_SIZE, IDX_HEAD_DIM],\n    )\n    kv_scale_flat = pl.reshape(\n        idx_kv_scale,\n        [idx_block_num * BLOCK_SIZE, 1],\n    )\n    idx_block_table_flat = pl.reshape(\n        idx_block_table,\n        [idx_table_len],\n    )\n    pair_arena = pl.create_tensor(\n        [TOPK_ARENA_ROWS, TOPK_PAIR_WIDTH], dtype=pl.FP32\n    )\n    with pl.scope():\n        score_arena = pl.create_tensor(\n            [bs, TOPK_MAX_CANDIDATES], dtype=pl.FP32\n        )\n        with pl.spmd(\n            TOPK_SCORE_WORKERS,\n            name_hint=\"indexer_score_leaf_wave\",\n            deps=[qh_quant_tid, weights_tid, cache_write_tid],\n            optimizations=[pl.split(pl.SplitMode.NONE, slot_num=2)],\n        ) as score_tid:\n            worker = pl.tile.get_block_idx()\n            query_count = pl.tensor.dim(position_ids, 0)\n            global_leaf_base = 0\n            for query in pl.range(query_count):\n                batch_idx = query // S\n                position = pl.read(position_ids, [query])\n                cache_len = (\n                    pl.read(kv_seq_lens, [batch_idx]) // COMPRESS_RATIO\n                )\n                visible_count = pl.max(\n                    pl.min(\n                        pl.min(\n                            cache_len,\n                            (position + 1) // COMPRESS_RATIO,\n                        ),\n                        TOPK_MAX_CANDIDATES,\n                    ),\n                    0,\n                )\n                leaf_count = (\n                    visible_count + TOPK_CANDIDATES_PER_LEAF - 1\n                ) // TOPK_CANDIDATES_PER_LEAF\n                base_mod = global_leaf_base % TOPK_SCORE_WORKERS\n                first_leaf = (worker + base_mod) % TOPK_SCORE_WORKERS\n                for leaf in pl.range(\n                    first_leaf, leaf_count, TOPK_SCORE_WORKERS\n                ):\n                    logical_begin = leaf * TOPK_CANDIDATES_PER_LEAF\n                    valid_count = pl.min(\n                        TOPK_CANDIDATES_PER_LEAF,\n                        visible_count - logical_begin,\n                    )\n                    query_head_begin = query * IDX_N_HEADS\n                    query_vector = qr_hadamard_i8[\n                        query_head_begin : query_head_begin + IDX_N_HEADS,\n                        0:IDX_HEAD_DIM,\n                    ]\n                    query_scale = pl.reshape(\n                        qr_hadamard_scale_dq[\n                            query_head_begin : query_head_begin + IDX_N_HEADS,\n                            0:1,\n                        ],\n                        [1, IDX_N_HEADS],\n                    )\n                    query_weight = weights[\n                        query : query + 1,\n                        0:IDX_N_HEADS,\n                    ]\n                    page_count = (\n                        valid_count + BLOCK_SIZE - 1\n                    ) // BLOCK_SIZE\n                    for page in pl.pipeline(0, page_count, stage=2):\n                        page_begin = page * BLOCK_SIZE\n                        logical_row = logical_begin + page_begin\n                        logical_page = logical_row // BLOCK_SIZE\n                        physical_block = pl.cast(\n                            pl.read(\n                                idx_block_table_flat,\n                                [\n                                    batch_idx * IDX_MAX_BLOCKS\n                                    + logical_page\n                                ],\n                            ),\n                            pl.INDEX,\n                        )\n                        physical_row = physical_block * BLOCK_SIZE\n                        kv_i8 = kv_cache_i8_flat[\n                            physical_row : physical_row + BLOCK_SIZE,\n                            0:IDX_HEAD_DIM,\n                        ]\n                        score_i32 = pl.matmul(\n                            kv_i8,\n                            query_vector,\n                            out_dtype=pl.INT32,\n                            b_trans=True,\n                        )\n                        score_fp32 = pl.cast(\n                            score_i32,\n                            target_type=pl.FP32,\n                            mode=\"none\",\n                        )\n                        score_fp32 = pl.col_expand_mul(\n                            score_fp32,\n                            query_scale,\n                        )\n                        score_fp32 = pl.maximum(score_fp32, 0.0)\n                        score_fp32 = pl.col_expand_mul(\n                            score_fp32,\n                            query_weight,\n                        )\n                        kv_scale = kv_scale_flat[\n                            physical_row : physical_row + BLOCK_SIZE,\n                            0:1,\n                        ]\n                        score = pl.mul(\n                            pl.row_sum(score_fp32),\n                            kv_scale,\n                        )\n                        score_row = pl.reshape(score, [1, BLOCK_SIZE])\n                        valid_rows = pl.min(\n                            BLOCK_SIZE,\n                            valid_count - page_begin,\n                        )\n                        score_valid = pl.fillpad(\n                            pl.set_validshape(score_row, 1, valid_rows),\n                            pad_value=pl.PadValue.min,\n                        )\n                        score_arena[\n                            query : query + 1,\n                            logical_row : logical_row + BLOCK_SIZE,\n                        ] = score_valid\n                global_leaf_base = global_leaf_base + leaf_count\n        with pl.spmd(\n            TOPK_GROUP_WORKERS,\n            name_hint=\"indexer_topk_group_wave\",\n            deps=[score_tid],\n        ) as topk_tid:\n            indexer_topk_group_wave(\n                position_ids,\n                kv_seq_lens,\n                score_arena,\n                pair_arena,\n            )\n        with pl.spmd(\n            bs,\n            name_hint=\"indexer_topk_query_merge\",\n            deps=[topk_tid],\n        ) as _score_tid:\n            indexer_topk_query_merge(\n                position_ids,\n                kv_seq_lens,\n                pair_arena,\n                topk_scores,\n                topk_idxs,\n            )\n\n    return topk_scores, topk_idxs\n\n\n@pl.jit.inline\ndef indexer(\n    x: pl.Tensor[[T_DYN, D], pl.BF16],\n    qr: pl.Tensor[[T_DYN, Q_LORA], pl.INT8],\n    qr_scale: pl.Tensor[[T_DYN, 1], pl.FP32],\n    wq_b: pl.Tensor[[Q_LORA, IDX_N_HEADS * IDX_HEAD_DIM], pl.INT8],\n    wq_b_scale: pl.Tensor[[IDX_N_HEADS * IDX_HEAD_DIM], pl.FP32],\n    weights_proj: pl.Tensor[[D, IDX_N_HEADS], pl.BF16],\n    # Interleave-duplicated (j>>1) cos and sign-folded sin, built once by the caller:\n    #   cos[j] = cos_half[j>>1];  sin[j] = sin_half[j>>1] * sign[j], sign = [-1,+1,...]\n    cos: pl.Tensor[[T_DYN, ROPE_HEAD_DIM], pl.FP32],\n    sin: pl.Tensor[[T_DYN, ROPE_HEAD_DIM], pl.FP32],\n    hadamard: pl.Tensor[[IDX_HEAD_DIM, IDX_HEAD_DIM], pl.BF16],\n    # C8 indexer cache: INT8 KV (quant-on-write) + per-position FP32 dequant scale; no bf16 cache.\n    idx_kv_cache: pl.InOut[pl.Tensor[[IDX_CACHE_BLOCK_NUM_DYN, BLOCK_SIZE, 1, IDX_HEAD_DIM], pl.INT8]],\n    idx_kv_scale: pl.InOut[pl.Tensor[[IDX_CACHE_BLOCK_NUM_DYN, BLOCK_SIZE, 1, 1], pl.FP32]],\n    idx_block_table: pl.Tensor[[B_DYN, IDX_MAX_BLOCKS], pl.INT32],\n    topk_scores: pl.Out[pl.Tensor[[T_DYN, IDX_TOPK], pl.FP32]],\n    topk_idxs: pl.Out[pl.Tensor[[T_DYN, IDX_TOPK], pl.INT32]],\n    position_ids: pl.Tensor[[T_DYN], pl.INT32],\n    kv_seq_lens: pl.Tensor[[B_DYN], pl.INT32],\n    late_dep: pl.Scalar[pl.TASK_ID],\n    cache_write_dep: pl.Scalar[pl.TASK_ID],\n):\n    bs = pl.tensor.dim(x, 0)\n    bs_heads = bs * IDX_N_HEADS\n    row_blocks = (bs + MM_ROW_TILE - 1) // MM_ROW_TILE\n    qr_acc_pad = pl.create_tensor([T_PAD, IDX_N_HEADS * IDX_HEAD_DIM], dtype=pl.INT32)\n    for qr_unit in pl.spmd(QR_OT_COUNT * row_blocks, name_hint=\"idx_qr_proj_matmul\", allow_early_resolve=True):\n        qr_rb = qr_unit // QR_OT_COUNT  # row block outermost\n        ot = qr_unit - qr_rb * QR_OT_COUNT\n        qr_r0 = qr_rb * MM_ROW_TILE\n        qr_rows = pl.min(MM_ROW_TILE, bs - qr_r0)\n        o_base = ot * Q_OUT_TILE\n        for ns in pl.range(0, Q_OUT_TILE, MM_N_TILE):\n            qr_acc = pl.create_tensor([MM_ROW_TILE, MM_N_TILE], dtype=pl.INT32)\n            for kb in pl.pipeline(0, Q_LORA // Q_TILE, stage=2):\n                q0 = kb * Q_TILE\n                qr_tile = pl.slice(qr, [MM_ROW_TILE, Q_TILE], [qr_r0, q0], valid_shape=[qr_rows, Q_TILE])\n                wq_tile = wq_b[q0 : q0 + Q_TILE, o_base + ns : o_base + ns + MM_N_TILE]\n                if q0 == 0:\n                    qr_acc = pl.matmul(qr_tile, wq_tile, out_dtype=pl.INT32)\n                else:\n                    qr_acc = pl.matmul_acc(qr_acc, qr_tile, wq_tile)\n            qr_acc_pad[qr_r0 : qr_r0 + MM_ROW_TILE, o_base + ns : o_base + ns + MM_N_TILE] = qr_acc\n    qr_proj = pl.create_tensor([bs, IDX_N_HEADS * IDX_HEAD_DIM], dtype=pl.FP32)\n    for ot in pl.spmd(IDX_N_HEADS * IDX_HEAD_DIM // Q_OUT_TILE, name_hint=\"idx_qr_proj_dequant\", allow_early_resolve=True):\n        o_base = ot * Q_OUT_TILE\n        wq_scale = pl.reshape(wq_b_scale[o_base : o_base + Q_OUT_TILE], [1, Q_OUT_TILE])\n        for dq_t0 in pl.range(0, bs, DEQUANT_T_TILE):\n            acc_fp32 = pl.cast(\n                qr_acc_pad[dq_t0 : dq_t0 + DEQUANT_T_TILE, o_base : o_base + Q_OUT_TILE],\n                target_type=pl.FP32, mode=\"none\")\n            qr_scale_tile = qr_scale[dq_t0 : dq_t0 + DEQUANT_T_TILE, :]\n            qr_dequant = pl.col_expand_mul(pl.row_expand_mul(acc_fp32, qr_scale_tile), wq_scale)\n            qr_proj[dq_t0 : dq_t0 + DEQUANT_T_TILE, o_base : o_base + Q_OUT_TILE] = qr_dequant\n\n    qr_proj_flat = pl.reshape(qr_proj, [bs_heads, IDX_HEAD_DIM])\n    # BF16 q for the Hadamard matmul: nope half rounded from the FP32 dequant, rope\n    # half rotated then rounded.\n    qr_bf16 = pl.create_tensor([bs_heads, IDX_HEAD_DIM], dtype=pl.BF16)\n    # spmd over ROPE_ROW_TILE-row blocks; token_idx = block base // ROPE_ROW_BLOCK\n    # picks the token-local cos/sin row. cos/sin arrive already interleave-duplicated and\n    # sign-folded (built once by the caller), and col_expand_mul folds the [1, ROPE_HEAD_DIM]\n    # row broadcast into the rotation multiply -- so no cos_il/sin_il tile is materialized\n    # and no per-block dup-gather runs.\n    #   out[j] = x[j]*cos_il[j] + x[j^1]*sin_il_signed[j]\n    #\n    # The j^1 lane-swap index permutes data, so no host table can hold it -- but it is\n    # block-invariant, and rebuilding it inside the spmd cost the same arange/trunc-cast/\n    # lane/arithmetic chain on all 16 blocks. Built once here instead (same form as the\n    # rope_swap scope in decode_sparse_attn_hca) and loaded per block. No pypto bitwise\n    # op is reachable at the tensor level, so the fp32 arithmetic chain is the only form.\n    rope_swap_idx_t = pl.create_tensor([ROPE_ROW_TILE, ROPE_HEAD_DIM], dtype=pl.INT32)\n    with pl.at(level=pl.Level.CORE_GROUP, name_hint=\"qr_rope_swap_idx\", allow_early_resolve=True):\n        sw_col = pl.col_expand_mul(\n            pl.full([ROPE_ROW_TILE, ROPE_HEAD_DIM], dtype=pl.FP32, value=1.0),\n            pl.cast(pl.arange(0, [1, ROPE_HEAD_DIM], dtype=pl.INT32), target_type=pl.FP32))\n        sw_dup_f = pl.cast(pl.cast(pl.mul(sw_col, 0.5), target_type=pl.INT32, mode=\"trunc\"), target_type=pl.FP32)\n        sw_lane = pl.sub(sw_col, pl.mul(sw_dup_f, 2.0))                                                # j%2\n        rope_swap_idx_t[0:ROPE_ROW_TILE, 0:ROPE_HEAD_DIM] = pl.cast(\n            pl.sub(pl.add(sw_col, 1.0), pl.mul(sw_lane, 2.0)), target_type=pl.INT32)                   # j^1\n\n    for idx in pl.spmd(bs_heads // ROPE_ROW_TILE, name_hint=\"qr_rope\", allow_early_resolve=True):\n        o0 = idx * ROPE_ROW_TILE\n        token_idx = o0 // ROPE_ROW_BLOCK\n        rope_swap_idx = rope_swap_idx_t[0:ROPE_ROW_TILE, 0:ROPE_HEAD_DIM]\n        cos_row = cos[token_idx : token_idx + 1, 0 : ROPE_HEAD_DIM]\n        sin_row = sin[token_idx : token_idx + 1, 0 : ROPE_HEAD_DIM]\n        qr_nope_slice = qr_proj_flat[o0 : o0 + ROPE_ROW_TILE, 0 : IDX_NOPE_HEAD_DIM]\n        qr_rope_slice = qr_proj_flat[o0 : o0 + ROPE_ROW_TILE, IDX_NOPE_HEAD_DIM : IDX_HEAD_DIM]\n        qr_swapped = pl.gather(qr_rope_slice, dim=-1, index=rope_swap_idx)\n        rope_rot = pl.add(\n            pl.col_expand_mul(qr_rope_slice, cos_row), pl.col_expand_mul(qr_swapped, sin_row))\n        qr_vec = pl.concat(pl.cast(qr_nope_slice, target_type=pl.BF16, mode=\"rint\"), pl.cast(rope_rot, target_type=pl.BF16, mode=\"rint\"))\n        qr_bf16[o0 : o0 + ROPE_ROW_TILE, :] = qr_vec\n\n    # cube-only scope: q @ hadamard lands in GM, keeping the vector amax/quant below\n    # in its own scope so the two run as separate cube and vector tasks.\n    qh_acc_gm = pl.create_tensor([bs_heads, IDX_HEAD_DIM], dtype=pl.FP32)\n    for idx in pl.spmd(bs_heads // QH_MM_TILE, name_hint=\"qr_hadamard_matmul\", allow_early_resolve=True):\n        o0 = idx * QH_MM_TILE\n        qh_acc = pl.matmul(qr_bf16[o0 : o0 + QH_MM_TILE, :], hadamard, out_dtype=pl.FP32)\n        qh_acc_gm[o0 : o0 + QH_MM_TILE, :] = qh_acc\n\n    qr_hadamard_i8 = pl.create_tensor(\n        [T_PAD * IDX_N_HEADS, IDX_HEAD_DIM], dtype=pl.INT8\n    )\n    qr_hadamard_scale_dq = pl.create_tensor(\n        [T_PAD * IDX_N_HEADS, 1], dtype=pl.FP32\n    )\n    with pl.spmd(\n        bs_heads // QH_QUANT_TILE,\n        name_hint=\"qr_hadamard_quant\",\n        allow_early_resolve=True,\n    ) as qh_quant_tid:\n        idx = pl.tile.get_block_idx()\n        o0 = idx * QH_QUANT_TILE\n        qh_amax = pl.full([1, QH_QUANT_TILE], dtype=pl.FP32, value=INT8_AMAX_EPS)\n        for h0 in pl.range(0, IDX_HEAD_DIM, QH_HEAD_DIM_TILE):\n            qh_a_f32 = qh_acc_gm[o0 : o0 + QH_QUANT_TILE, h0 : h0 + QH_HEAD_DIM_TILE]\n            qh_a_abs = pl.maximum(qh_a_f32, pl.neg(qh_a_f32))\n            qh_a_max = pl.reshape(pl.row_max(qh_a_abs), [1, QH_QUANT_TILE])\n            qh_amax = pl.maximum(qh_amax, qh_a_max)\n        qh_scale_quant_row = pl.div(pl.full([1, QH_QUANT_TILE], dtype=pl.FP32, value=INT8_SCALE_MAX), qh_amax)\n        qh_scale_dq = pl.reshape(pl.recip(qh_scale_quant_row), [QH_QUANT_TILE, 1])\n        qr_hadamard_scale_dq[o0 : o0 + QH_QUANT_TILE, :] = qh_scale_dq\n        qh_scale_quant = pl.reshape(qh_scale_quant_row, [QH_QUANT_TILE, 1])\n        for h1 in pl.range(0, IDX_HEAD_DIM, QH_HEAD_DIM_TILE):\n            qh_q_f32 = qh_acc_gm[o0 : o0 + QH_QUANT_TILE, h1 : h1 + QH_HEAD_DIM_TILE]\n            qh_q_scaled = pl.row_expand_mul(qh_q_f32, qh_scale_quant)\n            qh_q_i32 = pl.cast(qh_q_scaled, target_type=pl.INT32, mode=\"rint\")\n            qh_q_half = pl.cast(qh_q_i32, target_type=pl.FP16, mode=\"round\")\n            qh_i8 = pl.cast(qh_q_half, target_type=pl.INT8, mode=\"trunc\")\n            qr_hadamard_i8[o0 : o0 + QH_QUANT_TILE, h1 : h1 + QH_HEAD_DIM_TILE] = qh_i8\n\n    x_flat = x\n    weights = pl.create_tensor([T_PAD, IDX_N_HEADS], dtype=pl.FP32)\n    weights_partial = pl.create_tensor([WEIGHTS_OK * T_PAD, IDX_N_HEADS], dtype=pl.FP32)\n    # Deferred behind the caller's rms_norm dummy barrier: qkv's qr_proj_matmul is the\n    # critical path and must win the cores when rms_norm retires.\n    with pl.spmd(WEIGHTS_OK * row_blocks, name_hint=\"weights_proj\", deps=[late_dep]) as _weights_tid:\n        w_unit = pl.tile.get_block_idx()\n        w_rb = w_unit // WEIGHTS_OK  # row block outermost\n        kb = w_unit - w_rb * WEIGHTS_OK\n        w_r0 = w_rb * MM_ROW_TILE\n        w_rows = pl.min(MM_ROW_TILE, bs - w_r0)\n        k_base = kb * WEIGHTS_K_SLICE\n        weights_acc = pl.create_tensor([MM_ROW_TILE, IDX_N_HEADS], dtype=pl.FP32)\n        for db in pl.range(WEIGHTS_K_SLICE // D_TILE):\n            d0 = k_base + db * D_TILE\n            x_tile = pl.slice(x_flat, [MM_ROW_TILE, D_TILE], [w_r0, d0], valid_shape=[w_rows, D_TILE])\n            weights_proj_tile = weights_proj[d0 : d0 + D_TILE, :]\n            if db == 0:\n                weights_acc = pl.matmul(x_tile, weights_proj_tile, out_dtype=pl.FP32)\n            else:\n                weights_acc = pl.matmul_acc(weights_acc, x_tile, weights_proj_tile)\n        weights_partial[kb * T_PAD + w_r0 : kb * T_PAD + w_r0 + MM_ROW_TILE, :] = weights_acc\n\n    with pl.spmd(\n        row_blocks,\n        name_hint=\"weights_proj_reduce\",\n        allow_early_resolve=True,\n    ) as weights_tid:\n        w_rb = pl.tile.get_block_idx()\n        w_r0 = w_rb * MM_ROW_TILE\n        w_sum = weights_partial[w_r0 : w_r0 + MM_ROW_TILE, :]\n        for kb in pl.unroll(1, WEIGHTS_OK):\n            partial_r0 = kb * T_PAD + w_r0\n            w_sum = pl.add(w_sum, weights_partial[partial_r0 : partial_r0 + MM_ROW_TILE, :])\n        weights[w_r0 : w_r0 + MM_ROW_TILE, :] = pl.mul(w_sum, WEIGHTS_SCALE)\n\n    topk_scores, topk_idxs = indexer_score_topk_forest(\n        qr_hadamard_i8,\n        qr_hadamard_scale_dq,\n        weights,\n        idx_kv_cache,\n        idx_kv_scale,\n        idx_block_table,\n        position_ids,\n        kv_seq_lens,\n        topk_scores,\n        topk_idxs,\n        qh_quant_tid,\n        weights_tid,\n        cache_write_dep,\n    )\n    return topk_scores, topk_idxs\n\n\n@pl.jit\ndef indexer_test(\n    x: pl.Tensor[[T_DYN, D], pl.BF16],\n    qr: pl.Tensor[[T_DYN, Q_LORA], pl.INT8],\n    qr_scale: pl.Tensor[[T_DYN, 1], pl.FP32],\n    wq_b: pl.Tensor[[Q_LORA, IDX_N_HEADS * IDX_HEAD_DIM], pl.INT8],\n    wq_b_scale: pl.Tensor[[IDX_N_HEADS * IDX_HEAD_DIM], pl.FP32],\n    weights_proj: pl.Tensor[[D, IDX_N_HEADS], pl.BF16],\n    cos: pl.Tensor[[T_DYN, ROPE_HEAD_DIM], pl.FP32],\n    sin: pl.Tensor[[T_DYN, ROPE_HEAD_DIM], pl.FP32],\n    cmp_cos: pl.Tensor[[T_DYN, ROPE_HEAD_DIM], pl.FP32],\n    cmp_sin: pl.Tensor[[T_DYN, ROPE_HEAD_DIM], pl.FP32],\n    hadamard: pl.Tensor[[IDX_HEAD_DIM, IDX_HEAD_DIM], pl.BF16],\n    inner_kv: pl.Tensor[[T_DYN, INNER_HEAD_DIM], pl.FP32],\n    inner_compress_state: pl.Tensor[[INNER_STATE_BLOCK_NUM_DYN, INNER_STATE_BLOCK_SIZE, INNER_STATE_DIM], pl.FP32],\n    inner_compress_state_block_table: pl.Tensor[[B_DYN, INNER_STATE_MAX_BLOCKS], pl.INT32],\n    inner_wkv: pl.Tensor[[INNER_OUT_DIM, D], pl.BF16],\n    inner_wgate: pl.Tensor[[INNER_OUT_DIM, D], pl.BF16],\n    inner_ape: pl.Tensor[[COMPRESS_RATIO, INNER_OUT_DIM], pl.FP32],\n    inner_norm_w: pl.Tensor[[INNER_HEAD_DIM], pl.BF16],\n    idx_kv_cache: pl.InOut[pl.Tensor[[IDX_CACHE_BLOCK_NUM_DYN, BLOCK_SIZE, 1, IDX_HEAD_DIM], pl.INT8]],\n    idx_kv_scale: pl.InOut[pl.Tensor[[IDX_CACHE_BLOCK_NUM_DYN, BLOCK_SIZE, 1, 1], pl.FP32]],\n    idx_block_table: pl.Tensor[[B_DYN, IDX_MAX_BLOCKS], pl.INT32],\n    topk_scores: pl.Out[pl.Tensor[[T_DYN, IDX_TOPK], pl.FP32]],\n    topk_idxs: pl.Out[pl.Tensor[[T_DYN, IDX_TOPK], pl.INT32]],\n    position_ids: pl.Tensor[[T_DYN], pl.INT32],\n    idx_slot_mapping: pl.Tensor[[T_DYN], pl.INT64],\n    inner_state_slot_mapping: pl.Tensor[[T_DYN], pl.INT64],\n    kv_seq_lens: pl.Tensor[[B_DYN], pl.INT32],\n):\n    x.bind_dynamic(0, T_DYN)\n    qr.bind_dynamic(0, T_DYN)\n    qr_scale.bind_dynamic(0, T_DYN)\n    cos.bind_dynamic(0, T_DYN)\n    sin.bind_dynamic(0, T_DYN)\n    cmp_cos.bind_dynamic(0, T_DYN)\n    cmp_sin.bind_dynamic(0, T_DYN)\n    inner_kv.bind_dynamic(0, T_DYN)\n    inner_compress_state_block_table.bind_dynamic(0, B_DYN)\n    idx_block_table.bind_dynamic(0, B_DYN)\n    topk_scores.bind_dynamic(0, T_DYN)\n    topk_idxs.bind_dynamic(0, T_DYN)\n    position_ids.bind_dynamic(0, T_DYN)\n    idx_slot_mapping.bind_dynamic(0, T_DYN)\n    inner_state_slot_mapping.bind_dynamic(0, T_DYN)\n    kv_seq_lens.bind_dynamic(0, B_DYN)\n\n    # Standalone: no rms_norm producer, so the barrier fences nothing (ready on submit).\n    late_dep = pl.system.task_dummy(deps=[])\n    cache_write_dep = indexer_compressor(\n        x, inner_kv,\n        inner_compress_state, inner_compress_state_block_table,\n        inner_wkv, inner_wgate, inner_ape, inner_norm_w,\n        cmp_cos, cmp_sin, hadamard, idx_kv_cache, idx_kv_scale,\n        position_ids, idx_slot_mapping, inner_state_slot_mapping,\n        late_dep,\n    )\n    topk_scores, topk_idxs = indexer(\n        x,\n        qr,\n        qr_scale,\n        wq_b,\n        wq_b_scale,\n        weights_proj,\n        cos,\n        sin,\n        hadamard,\n        idx_kv_cache,\n        idx_kv_scale,\n        idx_block_table,\n        topk_scores,\n        topk_idxs,\n        position_ids,\n        kv_seq_lens,\n        late_dep,\n        cache_write_dep,\n    )\n    return topk_scores, idx_kv_cache, idx_kv_scale, topk_idxs\n\n\ndef gen_shared_weight(shape, dequant_std, chan_cv):\n    \"\"\"Synthesize a per-output-channel-symmetric INT8 weight + FP32 scale by simulating the\n    real DeepSeek-V4-Flash MXFP8 quant grid (e4m3, 128x128-block E8M0 scale), then re-quantizing\n    per-output-channel. Used for the indexer ``idx wq_b`` (and shared by decode_csa),\n    which follows the same FP8 grid as the shared experts: ~200 discrete levels, ~1.1% zero\n    spike, per-channel scale CV ~0.61. A plain randn INT8 misses that level/scale structure.\n    ``chan_cv`` (log-space source-gain std) injects the per-output-channel magnitude spread the\n    coarse 128-block scale leaves behind; per-channel INT8 is scale-invariant, so the grid sets\n    the level shape and ``dequant_std`` only sets the absolute scale magnitude.\n\n    ``shape`` last dim = reduction (in) dim; leading dims map to the per-output-channel scale\n    shape ([out, in] -> scale [out]).\n    \"\"\"\n    import torch\n\n    FP8_MAX, TINY = 448.0, 1e-20\n\n    def sim_fp8(W, block=128):   # e4m3 + 128x128-block E8M0 (round-up) scale on (out, in)\n        out, inn = W.shape\n        Wb = W.reshape(out // block, block, inn // block, block)\n        scale = torch.exp2(torch.ceil(torch.log2((Wb.abs().amax(dim=(1, 3), keepdim=True) / FP8_MAX).clamp_min(TINY))))\n        q = (Wb / scale).to(torch.float8_e4m3fn).float() * scale\n        return q.reshape(out, inn)\n\n    W = torch.randn(*shape) * torch.exp(chan_cv * torch.randn(*shape[:-1], 1))  # per-channel gain\n    Wq = sim_fp8(W)\n    amax = Wq.abs().amax(dim=-1, keepdim=True).clamp_min(INT8_AMAX_EPS)\n    scale = amax / INT8_SCALE_MAX\n    w_i8 = torch.round(Wq / scale).clamp_(-INT8_SCALE_MAX, INT8_SCALE_MAX).to(torch.int8)\n    scale = (scale * (dequant_std / (w_i8.float() * scale).std())).squeeze(-1).float()\n    return w_i8, scale\n\n\ndef golden_indexer(tensors, inner_full=None):\n    \"\"\"Torch reference for Indexer.forward decode branch; prefill `start_pos == 0` path is omitted.\n\n    ``inner_full`` supplies the cache half's stream-side inputs, which under CP is\n    the whole TP group's token stream rather than the rank's rows.\n    \"\"\"\n    import torch\n    from decode_indexer_compressor import golden_compressor\n    from utils import int8_quant_per_row\n\n    x = tensors[\"x\"].float()\n    qr = tensors[\"qr\"]\n    qr_scale = tensors[\"qr_scale\"].float()\n    wq_b = tensors[\"wq_b\"]\n    wq_b_scale = tensors[\"wq_b_scale\"].float()\n    weights_proj = tensors[\"weights_proj\"].float()\n    cos = tensors[\"cos\"]\n    sin = tensors[\"sin\"]\n    hadamard = tensors[\"hadamard\"].float()\n\n    kv_seq_lens = tensors[\"kv_seq_lens\"].to(torch.int64)\n\n    tokens = x.shape[0]\n    bsz, seqlen = tokens // S, S\n    x = x.view(tokens, D)\n    ratio, rd = COMPRESS_RATIO, ROPE_HEAD_DIM\n\n    q_i32 = qr.to(torch.int32) @ wq_b.to(torch.int32)\n    q = (q_i32.float() * qr_scale * wq_b_scale.view(1, -1)).view(\n        tokens, IDX_N_HEADS, IDX_HEAD_DIM\n    )\n    q_rope = q[..., -rd:]\n    q_rope_swapped = q_rope.unflatten(-1, (-1, 2)).flip(-1).flatten(-2)\n    q_rope = q_rope * cos[:, None, :] + q_rope_swapped * sin[:, None, :]\n    q = torch.cat([q[..., :-rd], q_rope], dim=-1)\n\n    q = q.to(torch.bfloat16).float() @ hadamard\n    # W8A8C16: q and Indexer Cache are quantized per row to INT8 for score matmul,\n    # then dequantized with q_scale * kv_scale.\n    # flash: fp4_act_quant on q (FP4 simulation).\n\n    inner_src = tensors if inner_full is None else inner_full\n    inner_tensors = {\n        \"x\": inner_src[\"x\"],\n        \"kv\": inner_src[\"inner_kv\"],\n        \"wkv\": tensors[\"inner_wkv\"],\n        \"wgate\": tensors[\"inner_wgate\"],\n        \"ape\": tensors[\"inner_ape\"],\n        \"norm_w\": tensors[\"inner_norm_w\"],\n        \"cos\": inner_src[\"cmp_cos\"],\n        \"sin\": inner_src[\"cmp_sin\"],\n        \"hadamard\": tensors[\"hadamard\"],\n        \"compress_state\": tensors[\"inner_compress_state\"],\n        \"compress_state_block_table\": inner_src[\"inner_compress_state_block_table\"],\n        \"idx_kv_cache\": tensors[\"idx_kv_cache\"],\n        \"idx_kv_scale\": tensors[\"idx_kv_scale\"],\n        \"position_ids\": inner_src[\"position_ids\"],\n        \"idx_slot_mapping\": inner_src[\"idx_slot_mapping\"],\n        \"inner_state_slot_mapping\": inner_src[\"inner_state_slot_mapping\"],\n    }\n    golden_compressor(inner_tensors)\n\n    weights = (x @ weights_proj) * WEIGHTS_SCALE\n\n    # C8 cache: pre-quantized INT8 KV + per-position dequant scale (no score-time re-quant)\n    idx_kv_cache_i8 = tensors[\"idx_kv_cache\"]\n    idx_kv_scale = tensors[\"idx_kv_scale\"].float()\n    idx_block_table = tensors[\"idx_block_table\"]\n    topk_scores = torch.full(\n        (tokens, IDX_TOPK), FP32_NEG_INF, dtype=torch.float32\n    )\n    topk_idxs = torch.full((tokens, IDX_TOPK), -1, dtype=torch.int32)\n    q_i8, q_scale = int8_quant_per_row(\n        q.reshape(tokens * IDX_N_HEADS, IDX_HEAD_DIM)\n    )\n    q_i8 = q_i8.view(tokens, IDX_N_HEADS, IDX_HEAD_DIM)\n    q_scale = q_scale.view(tokens, IDX_N_HEADS, 1)\n    flat_cache = idx_kv_cache_i8.reshape(-1, IDX_HEAD_DIM)\n    flat_scale = idx_kv_scale.reshape(-1, 1)\n\n    for b in range(bsz):\n        cache_len = min(\n            int(kv_seq_lens[b].item()) // ratio,\n            TOPK_MAX_CANDIDATES,\n        )\n        if cache_len <= 0:\n            continue\n        logical_rows = torch.arange(cache_len, dtype=torch.int64)\n        physical_pages = idx_block_table[\n            b, logical_rows // BLOCK_SIZE\n        ].to(torch.int64)\n        valid_pages = (physical_pages >= 0) & (\n            physical_pages < idx_kv_cache_i8.shape[0]\n        )\n        physical_rows = (\n            physical_pages.clamp(min=0) * BLOCK_SIZE\n            + logical_rows % BLOCK_SIZE\n        )\n        kv_i8 = flat_cache[physical_rows]\n        kv_scale = flat_scale[physical_rows]\n        for s in range(seqlen):\n            token = b * S + s\n            visible_len = min(\n                cache_len,\n                int(tensors[\"position_ids\"][token].item() + 1) // ratio,\n                TOPK_MAX_CANDIDATES,\n            )\n            if visible_len <= 0:\n                continue\n            running_scores = torch.empty(0, dtype=torch.float32)\n            running_indices = torch.empty(0, dtype=torch.int64)\n            for begin in range(0, visible_len, TOPK_CANDIDATES_PER_LEAF):\n                end = min(begin + TOPK_CANDIDATES_PER_LEAF, visible_len)\n                score_i32 = torch.einsum(\n                    \"hd,td->ht\",\n                    q_i8[token].to(torch.int32),\n                    kv_i8[begin:end].to(torch.int32),\n                )\n                score = score_i32.float() * q_scale[token]\n                score = (\n                    torch.relu(score) * weights[token].unsqueeze(-1)\n                ).sum(dim=0)\n                score = score * kv_scale[begin:end, 0]\n                score = torch.where(\n                    valid_pages[begin:end],\n                    score,\n                    torch.full_like(score, FP32_NEG_INF),\n                )\n                indices = torch.arange(begin, end, dtype=torch.int64)\n                merged_scores = torch.cat([running_scores, score])\n                merged_indices = torch.cat([running_indices, indices])\n                keep = min(IDX_TOPK, merged_scores.numel())\n                running_scores, selected = torch.topk(\n                    merged_scores, keep\n                )\n                running_indices = merged_indices[selected]\n            topk_scores[token, : running_scores.numel()] = running_scores\n            topk_idxs[token, : running_indices.numel()] = running_indices.to(\n                torch.int32\n            )\n\n    tensors[\"topk_scores\"][:] = topk_scores\n    tensors[\"topk_idxs\"][:] = topk_idxs\n\n\ndef build_tensor_specs(start_pos=None, batch=B):\n    tokens = batch * S\n    import torch  # type: ignore[import]\n    from utils import (\n        block_table,\n        compressed_slot_mapping,\n        csa_decode_start_set,\n        int8_quant_per_row,\n        kv_seq_lens_from_starts,\n        position_ids_from_starts,\n        resolve_start_positions,\n        token_local_rope,\n    )\n    from golden import TensorSpec\n\n    starts = resolve_start_positions(\n        start_pos,\n        batch=batch,\n        seq=S,\n        max_seq_len=MAX_SEQ_LEN,\n        default_fn=lambda: csa_decode_start_set(\n            batch=batch,\n            seq=S,\n            compress_ratio=COMPRESS_RATIO,\n            state_block_size=INNER_STATE_BLOCK_SIZE,\n            cache_tile=CACHE_TILE,\n        ),\n    )\n    positions = position_ids_from_starts(starts, seq=S)\n    kv_seq_lens = kv_seq_lens_from_starts(starts, seq=S)\n\n    state_block_num = batch * INNER_STATE_MAX_BLOCKS\n    state_block_table = torch.arange(\n        state_block_num - 1, -1, -1, dtype=torch.int32\n    ).reshape(batch, INNER_STATE_MAX_BLOCKS)\n    ring_rows = positions.to(torch.int64) % INNER_STATE_LEN\n    state_pages = torch.gather(\n        state_block_table.to(torch.int64),\n        1,\n        ring_rows // INNER_STATE_BLOCK_SIZE,\n    )\n    state_slots = (\n        state_pages * INNER_STATE_BLOCK_SIZE\n        + ring_rows % INNER_STATE_BLOCK_SIZE\n    )\n\n    max_candidate_rows = min(\n        int((kv_seq_lens.to(torch.int64) // COMPRESS_RATIO).max()),\n        TOPK_MAX_CANDIDATES,\n    )\n    max_request_pages = max(\n        1, (max_candidate_rows + BLOCK_SIZE - 1) // BLOCK_SIZE\n    )\n    idx_physical_blocks = batch * max_request_pages\n    idx_block_table = block_table(\n        batch=batch,\n        table_blocks=IDX_MAX_BLOCKS,\n        physical_blocks=idx_physical_blocks,\n    )\n    idx_slots = compressed_slot_mapping(\n        positions,\n        idx_block_table,\n        compress_ratio=COMPRESS_RATIO,\n        block_size=BLOCK_SIZE,\n    )\n\n    def interleave_rope(rope_cos, rope_sin):\n        rope_cos = rope_cos[:, : ROPE_HEAD_DIM // 2].repeat_interleave(\n            2, dim=-1\n        )\n        rope_sin = rope_sin[:, : ROPE_HEAD_DIM // 2].repeat_interleave(\n            2, dim=-1\n        )\n        rope_sign = torch.ones(ROPE_HEAD_DIM, dtype=torch.float32)\n        rope_sign[0::2] = -1.0\n        return rope_cos, rope_sin * rope_sign\n\n    rope_cos, rope_sin = token_local_rope(\n        M,\n        COMPRESS_RATIO,\n        positions.reshape(-1),\n        max_seq_len=MAX_SEQ_LEN,\n        dtype=torch.float32,\n    )\n    rope_cos, rope_sin = interleave_rope(rope_cos, rope_sin)\n    cmp_rope_positions = torch.where(\n        (positions.to(torch.int64) + 1) % COMPRESS_RATIO == 0,\n        positions.to(torch.int64) - (COMPRESS_RATIO - 1),\n        torch.zeros_like(positions, dtype=torch.int64),\n    )\n    cmp_rope_cos, cmp_rope_sin = token_local_rope(\n        M,\n        COMPRESS_RATIO,\n        cmp_rope_positions.reshape(-1),\n        max_seq_len=MAX_SEQ_LEN,\n        dtype=torch.float32,\n    )\n    cmp_rope_cos, cmp_rope_sin = interleave_rope(\n        cmp_rope_cos, cmp_rope_sin\n    )\n\n    def init_x():\n        return torch.rand(batch * S, D)\n    def init_qr():\n        return torch.rand(tokens, Q_LORA)\n    # weights_proj / inner-compressor BF16 weight std and RMSNorm gamma mean/std, averaged\n    # over DeepSeek-V4-Flash-0731 layers 8/32. idx wq_b uses the MXFP8 grid below.\n    def init_weights_proj():\n        return torch.randn(D, IDX_N_HEADS) * 0.2218\n    def init_cos():\n        return rope_cos.clone()\n    def init_sin():\n        return rope_sin.clone()\n    def init_cmp_cos():\n        return cmp_rope_cos.clone()\n    def init_cmp_sin():\n        return cmp_rope_sin.clone()\n    def init_hadamard():\n        return torch.rand(IDX_HEAD_DIM, IDX_HEAD_DIM) * (IDX_HEAD_DIM ** -0.5)\n    def init_inner_compress_state():\n        return torch.randn(\n            state_block_num,\n            INNER_STATE_BLOCK_SIZE,\n            INNER_STATE_DIM,\n        ) * 0.05\n    def init_inner_compress_state_block_table():\n        return state_block_table.clone()\n    def init_inner_wkv():\n        return torch.randn(INNER_OUT_DIM, D) * 0.0270\n    def init_inner_wgate():\n        return torch.randn(INNER_OUT_DIM, D) * 0.0513\n    def init_inner_ape():\n        return torch.randn(COMPRESS_RATIO, INNER_OUT_DIM) * 0.1524\n    def init_inner_norm_w():\n        return 0.6903 + 0.2663 * torch.randn(INNER_HEAD_DIM)\n    def init_idx_block_table():\n        return idx_block_table.clone()\n    def init_position_ids():\n        return positions.clone()\n    def init_kv_seq_lens():\n        return kv_seq_lens.clone()\n    def init_inner_state_slot_mapping():\n        return state_slots.clone()\n    def init_idx_slot_mapping():\n        return idx_slots.clone()\n\n    # idx wq_b: simulate the real MXFP8 (e4m3 + 128x128-block E8M0) grid (~200 levels, scaleCV\n    # ~0.61, ~1.1% zero spike) instead of a benign randn INT8. gen_shared_weight reduces over\n    # the last (in) dim, so build [out, in] then transpose.\n    wq_b_i8_T, wq_b_scale = gen_shared_weight(\n        (IDX_N_HEADS * IDX_HEAD_DIM, Q_LORA), dequant_std=0.108, chan_cv=0.56)\n    wq_b_i8 = wq_b_i8_T.t().contiguous()\n    qr_i8, qr_scale = int8_quant_per_row(init_qr())\n\n    # C8 indexer cache fixture: INT8 + scale from one bf16-rounded random draw\n    idx_kv_cache_bf16 = torch.rand(\n        idx_physical_blocks, BLOCK_SIZE, 1, IDX_HEAD_DIM\n    ).to(torch.bfloat16)\n    idx_kv_i8, idx_kv_sc = int8_quant_per_row(\n        idx_kv_cache_bf16.float().reshape(\n            idx_physical_blocks * BLOCK_SIZE, IDX_HEAD_DIM\n        )\n    )\n    idx_kv_i8 = idx_kv_i8.view(\n        idx_physical_blocks, BLOCK_SIZE, 1, IDX_HEAD_DIM\n    )\n    idx_kv_sc = idx_kv_sc.view(\n        idx_physical_blocks, BLOCK_SIZE, 1, 1\n    )\n\n    return [\n        TensorSpec(\"x\", [batch * S, D], torch.bfloat16, init_value=init_x),\n        TensorSpec(\"qr\", [tokens, Q_LORA], torch.int8, init_value=lambda: qr_i8),\n        TensorSpec(\"qr_scale\", [tokens, 1], torch.float32, init_value=lambda: qr_scale),\n        TensorSpec(\"wq_b\", [Q_LORA, IDX_N_HEADS * IDX_HEAD_DIM], torch.int8, init_value=lambda: wq_b_i8),\n        TensorSpec(\"wq_b_scale\", [IDX_N_HEADS * IDX_HEAD_DIM], torch.float32, init_value=lambda: wq_b_scale),\n        TensorSpec(\"weights_proj\", [D, IDX_N_HEADS], torch.bfloat16, init_value=init_weights_proj),\n        TensorSpec(\"cos\", [tokens, ROPE_HEAD_DIM], torch.float32, init_value=init_cos),\n        TensorSpec(\"sin\", [tokens, ROPE_HEAD_DIM], torch.float32, init_value=init_sin),\n        TensorSpec(\"cmp_cos\", [tokens, ROPE_HEAD_DIM], torch.float32, init_value=init_cmp_cos),\n        TensorSpec(\"cmp_sin\", [tokens, ROPE_HEAD_DIM], torch.float32, init_value=init_cmp_sin),\n        TensorSpec(\"hadamard\", [IDX_HEAD_DIM, IDX_HEAD_DIM], torch.bfloat16, init_value=init_hadamard),\n        TensorSpec(\"inner_kv\", [batch * S, INNER_HEAD_DIM], torch.float32),\n        TensorSpec(\"inner_compress_state\", [state_block_num, INNER_STATE_BLOCK_SIZE, INNER_STATE_DIM], torch.float32, init_value=init_inner_compress_state),\n        TensorSpec(\"inner_compress_state_block_table\", [batch, INNER_STATE_MAX_BLOCKS], torch.int32, init_value=init_inner_compress_state_block_table),\n        TensorSpec(\"inner_wkv\", [INNER_OUT_DIM, D], torch.bfloat16, init_value=init_inner_wkv),\n        TensorSpec(\"inner_wgate\", [INNER_OUT_DIM, D], torch.bfloat16, init_value=init_inner_wgate),\n        TensorSpec(\"inner_ape\", [COMPRESS_RATIO, INNER_OUT_DIM], torch.float32, init_value=init_inner_ape),\n        TensorSpec(\"inner_norm_w\", [INNER_HEAD_DIM], torch.bfloat16, init_value=init_inner_norm_w),\n        TensorSpec(\"idx_kv_cache\", [idx_physical_blocks, BLOCK_SIZE, 1, IDX_HEAD_DIM], torch.int8, init_value=lambda: idx_kv_i8),\n        TensorSpec(\"idx_kv_scale\", [idx_physical_blocks, BLOCK_SIZE, 1, 1], torch.float32, init_value=lambda: idx_kv_sc),\n        TensorSpec(\"idx_block_table\", [batch, IDX_MAX_BLOCKS], torch.int32, init_value=init_idx_block_table),\n        TensorSpec(\"topk_scores\", [tokens, IDX_TOPK], torch.float32),\n        TensorSpec(\"topk_idxs\", [tokens, IDX_TOPK], torch.int32),\n        TensorSpec(\"position_ids\", [batch * S], torch.int32, init_value=lambda: init_position_ids().reshape(-1)),\n        TensorSpec(\"idx_slot_mapping\", [batch * S], torch.int64, init_value=lambda: init_idx_slot_mapping().reshape(-1)),\n        TensorSpec(\"inner_state_slot_mapping\", [batch * S], torch.int64, init_value=lambda: init_inner_state_slot_mapping().reshape(-1)),\n        TensorSpec(\"kv_seq_lens\", [batch], torch.int32, init_value=init_kv_seq_lens),\n    ]\n\n\nif __name__ == \"__main__\":\n    import argparse\n    from golden import ratio_allclose, run, topk_pair_compare\n\n    parser = argparse.ArgumentParser()\n    parser.add_argument(\"-p\", \"--platform\", type=str, default=\"a2a3\",\n                        choices=[\"a2a3\", \"a2a3sim\", \"a5\", \"a5sim\"])\n    parser.add_argument(\"-d\", \"--device\", type=int, default=0)\n    parser.add_argument(\"-b\", \"--batch\", type=int, default=B,\n                        help=f\"runtime request count up to {B} (the compile-time upper bound). \"\n                             \"The batch axes are pl.dynamic, so one compiled program \"\n                             \"serves every value.\")\n    parser.add_argument(\"--enable-chip-swimlane\", type=int, default=0, choices=[0, 1, 2],\n                        help=\"chip swimlane level: 0=off, 1=AICore timing, 2=+AICPU timing.\")\n    parser.add_argument(\"--runtime-dir\", type=str, default=None)\n    parser.add_argument(\"--start-pos\", type=str, default=None,\n                        help=\"Fixture-only start position: one value for a uniform batch or \"\n                             \"a comma-separated value per request.\")\n    parser.add_argument(\"--dump-passes\", action=\"store_true\", default=False)\n    args = parser.parse_args()\n    if args.batch < 1 or args.batch > B:\n        parser.error(f\"--batch must be in [1, {B}], got {args.batch}\")\n    start_pos = None\n    if args.start_pos is not None:\n        try:\n            start_values = [int(value) for value in args.start_pos.split(\",\")]\n        except ValueError:\n            parser.error(\n                f\"--start-pos must contain integers, got {args.start_pos!r}\"\n            )\n        start_pos = start_values[0] if len(start_values) == 1 else start_values\n\n    result = run(\n        fn=indexer_test,\n        specs=build_tensor_specs(start_pos, batch=args.batch),\n        golden_fn=golden_indexer,\n        runtime_dir=args.runtime_dir,\n        compile_cfg=dict(dump_passes=args.dump_passes),\n        runtime_cfg=dict(\n            platform=args.platform,\n            device_id=args.device,\n            enable_chip_swimlane=args.enable_chip_swimlane,\n        ),\n        rtol=1e-3,\n        atol=1e-3,\n        compare_fn={\n            \"topk_scores\": ratio_allclose(\n                # Scores are diagnostic; sparse attention consumes the selected\n                # indices checked below. A3 reduction order may perturb one\n                # root score per query without changing the selected set.\n                atol=1e-4, rtol=1.0 / 128, max_error_ratio=0.001\n            ),\n            \"topk_idxs\": topk_pair_compare(\"topk_scores\"),\n            # C8 cache: history is exact; only the <=B boundary rows the compressor rewrote may\n            # differ by +/-1 LSB from the bf16 round of a fresh position.\n            \"idx_kv_cache\": ratio_allclose(atol=1, rtol=0, max_error_ratio=0.01),\n            \"idx_kv_scale\": ratio_allclose(atol=1e-4, rtol=1.0 / 128, max_error_ratio=0.01),\n        },\n    )\n    if not result.passed:\n        if result.error:\n            print(result.error)\n        raise SystemExit(1)\n", "decode_sparse_attn_csa.py": "# Copyright (c) PyPTO Contributors.\n# This program is free software, you can redistribute it and/or modify it under the terms and conditions of\n# CANN Open Software License Agreement Version 2.0 (the \"License\").\n# Please refer to the License for details. You may not use this file except in compliance with the License.\n# THIS SOFTWARE IS PROVIDED ON AN \"AS IS\" BASIS, WITHOUT WARRANTIES OF ANY KIND, EITHER EXPRESS OR IMPLIED,\n# INCLUDING BUT NOT LIMITED TO NON-INFRINGEMENT, MERCHANTABILITY, OR FITNESS FOR A PARTICULAR PURPOSE.\n# See LICENSE in the root of the software repository for the full text of the License.\n# -----------------------------------------------------------------------------------------------------------\n\"\"\"DeepSeek-V4 CSA sparse attention with grouped output projection (decode).\n\nRatio-4 compressed cache plus the sliding window, with the indexer top-k\nmasking folded in. The SWA and HCA variants live in sibling modules.\n\"\"\"\n\n\nimport pypto.language as pl\n\nfrom config import (\n    FLASH as M,\n    DECODE_BATCH,\n    TP,\n    DECODE_SEQ,\n    BLOCK_SIZE,\n    KV_ORI_BLOCK_NUM,\n)\n\n\n# Dynamic shape variables.\nB_DYN = pl.dynamic(\"B_DYN\")  # per-request axis (block tables)\nT_DYN = pl.dynamic(\"T_DYN\")  # T = B * S\nORI_BLOCK_NUM_DYN = pl.dynamic(\"ORI_BLOCK_NUM_DYN\")\nCMP_BLOCK_NUM_DYN = pl.dynamic(\"CMP_BLOCK_NUM_DYN\")\n\n# model config\nB = DECODE_BATCH // TP\nS = DECODE_SEQ\nT = B * S\nD = M.hidden_size\nH = M.num_attention_heads\nHEAD_DIM = M.head_dim\nROPE_DIM = M.qk_rope_head_dim\nHALF_ROPE = ROPE_DIM // 2\nNOPE_DIM = M.nope_head_dim\nWIN = M.sliding_window\nMAX_SEQ_LEN = M.max_position_embeddings\nIDX_TOPK = M.index_topk\nCMP_TOPK = IDX_TOPK\nSOFTMAX_SCALE = M.softmax_scale\nO_LORA = M.o_lora_rank\nO_GROUPS = M.o_groups\nHEADS_PER_GROUP = H // O_GROUPS\nO_GROUP_IN = HEADS_PER_GROUP * HEAD_DIM\nCOMPRESS_RATIO = 4\nCOMPRESS_RATIO_INV = 1.0 / COMPRESS_RATIO\nCSA_CMP_GE_BIAS = 1.0  # raw + 1, folded for the ge clamp\nNEG_INF = -1.0e20\n\n# paged KV cache\nORI_MAX_BLOCKS = (MAX_SEQ_LEN + BLOCK_SIZE - 1) // BLOCK_SIZE\nORI_BLOCK_NUM = KV_ORI_BLOCK_NUM\nCMP_MAX_BLOCKS = (MAX_SEQ_LEN // COMPRESS_RATIO + BLOCK_SIZE - 1) // BLOCK_SIZE\n\n# tiling\nH_TILE = 16\nQK_M_TILE = 32           # qk_pv M rows per QK/PV matmul; QK_M_TILE/H_TILE-way KV L1->L0 reuse\nATTN_K_TILE = 128\nNUM_QK_CORES = 24        # qk_pv dispatch lanes = a2a3 AIC count; re-sweep for other AIC counts\nT_PAD = ((T + 16 - 1) // 16) * 16  # T padded up to the 16-row cube M floor\nATTENTION_PUBLISH_WORKERS = 48\nATTENTION_PUBLISH_T_TILE = 8\nLOCAL_O_GROUPS = O_GROUPS // TP\nGROUP_T_PAD = TP * T_PAD\nATTENTION_WINDOW_ROWS = LOCAL_O_GROUPS * GROUP_T_PAD\nPUBLISH_GROUPS = H_TILE // HEADS_PER_GROUP\nROPE_CS_T_TILE = 8    # rope cos/sin row block; T is a multiple of 8 by the batch contract\nTOPK = WIN + CMP_TOPK\n# Floor to 2: a single sparse-K block miscompiles in pypto (S-stride cross-token\n# output mixup); a 2-block build with an all-invalid 2nd block is bit-exact.\nSPARSE_BLOCKS = max(2, (TOPK + ATTN_K_TILE - 1) // ATTN_K_TILE)\nPADDED_TOPK = SPARSE_BLOCKS * ATTN_K_TILE\nQK_ITEMS = T * SPARSE_BLOCKS   # qk_pv work items: one per (token, sparse block)\n# Page-contiguous runs one sliding-window K tile spans. WIN, not the K tile size,\n# caps how many window rows a tile can hold; BLOCK_SIZE only sets where the cuts\n# fall, being where physical contiguity breaks. So: those rows plus a worst-case\n# BLOCK_SIZE - 1 head offset, rounded up to pages -- 2 whenever WIN <= BLOCK_SIZE,\n# whatever ATTN_K_TILE is, and it grows on its own if either outgrows a page.\nSWA_TILE_WIN_ROWS = min(ATTN_K_TILE, WIN)\nSWA_RUNS = (SWA_TILE_WIN_ROWS + 2 * (BLOCK_SIZE - 1)) // BLOCK_SIZE\n# Token tile for the slot / bias vector work; the whole-T form would put\n# [T, IDX_TOPK] FP32 tiles well past the Vec limit.\nBIAS_T_TILE = min(T, 8)\nif T % BIAS_T_TILE != 0:\n    raise ValueError(\"CSA token capacity must contain complete bias tiles\")\nif H_TILE % HEADS_PER_GROUP != 0:\n    raise ValueError(f\"CSA head tile {H_TILE} must contain complete output groups\")\nif O_GROUPS % TP != 0:\n    raise ValueError(f\"output groups {O_GROUPS} must be divisible by TP size {TP}\")\nif LOCAL_O_GROUPS % PUBLISH_GROUPS != 0:\n    raise ValueError(\"local output groups must contain complete CSA publish tiles\")\nif T % ATTENTION_PUBLISH_T_TILE != 0:\n    raise ValueError(\"local token capacity must contain complete attention publish tiles\")\n\n\n@pl.jit.inline(auto_scope=False)\ndef sparse_attn_csa(\n    q: pl.Tensor[[T_DYN, H, HEAD_DIM], pl.BF16],\n    ori_kv: pl.Tensor[[ORI_BLOCK_NUM_DYN, BLOCK_SIZE, 1, HEAD_DIM], pl.BF16],\n    window_swa_indices: pl.Tensor[[T_DYN, WIN], pl.INT32],\n    cmp_kv: pl.Tensor[[CMP_BLOCK_NUM_DYN, BLOCK_SIZE, 1, HEAD_DIM], pl.BF16],\n    cmp_block_table: pl.Tensor[[B_DYN, CMP_MAX_BLOCKS], pl.INT32],\n    idx_topk: pl.Tensor[[T_DYN, IDX_TOPK], pl.INT32],\n    position_ids: pl.Tensor[[T_DYN, 1], pl.INT32],\n    freqs_cos: pl.Tensor[[T_DYN, ROPE_DIM], pl.BF16],\n    freqs_sin: pl.Tensor[[T_DYN, ROPE_DIM], pl.BF16],\n    cache_ready_dep: pl.Scalar[pl.TASK_ID],\n):\n    \"\"\"Plan and run CSA QK/PV over sparse blocks, and build inverse-RoPE metadata.\"\"\"\n    # Compressed index contract: -1 invalid, [0, ...) compressed KV slots.\n    ori_block_num = pl.tensor.dim(ori_kv, 0)\n    t_dim = pl.tensor.dim(q, 0)\n    t_heads = t_dim * H\n    t_blk = t_dim * (H // H_TILE) * SPARSE_BLOCKS * H_TILE\n    qk_items = t_dim * SPARSE_BLOCKS\n    rope_cs_blocks = t_dim // ROPE_CS_T_TILE\n    ori_kv_flat = pl.reshape(ori_kv, [ori_block_num * BLOCK_SIZE, HEAD_DIM])\n\n    # WAR marker (pypto-lib#481): a scalar-driven gather_row does not mark ori_kv\n    # add_inout by itself, so the enclosing layer's in-place KV-cache writeback would\n    # lose its WAR edge against the qk_pv gather read. add_inout is a param-level\n    # property, so this one no-op tile self-copy suffices.\n    with pl.at(level=pl.Level.CORE_GROUP, name_hint=\"kv_touch\", allow_early_resolve=True):\n        ori_kv_flat[0:1, 0:HEAD_DIM] = ori_kv_flat[0:1, 0:HEAD_DIM]\n\n    # qk_plan compacts the t_dim * SPARSE_BLOCKS (token, sparse-block) work items into\n    # qk_order[] -- non-empty tiles (valid_block_mask > 0) first, empty tiles\n    # appended -- through one running write cursor, so qk_pv's NUM_QK_CORES lanes\n    # take the heavy tiles one-per-lane before any lane takes a second.\n    sparse_bias = pl.create_tensor([t_dim, PADDED_TOPK], dtype=pl.FP32)\n    cmp_sparse_indices = pl.create_tensor([t_dim, CMP_TOPK], dtype=pl.INT32)\n    valid_block_mask = pl.create_tensor([t_dim, SPARSE_BLOCKS], dtype=pl.INT32)\n    qk_order = pl.create_tensor([QK_ITEMS], dtype=pl.INT32)\n    qk_wcur = pl.create_tensor([1], dtype=pl.INT32)\n    with pl.at(level=pl.Level.CORE_GROUP, name_hint=\"csa_slots_build_valid_qk_plan\") as qk_plan_tid:\n        # Compressed slots [0, IDX_TOPK): vectorized masked copy over a token tile, keeping\n        # raw iff 0 <= raw < floor((pos + 1) / COMPRESS_RATIO), as out = mask*(raw + 1) - 1.\n        for bias_t0 in pl.range(0, t_dim, BIAS_T_TILE):\n            c_raw = pl.cast(idx_topk[bias_t0 : bias_t0 + BIAS_T_TILE, 0:IDX_TOPK], target_type=pl.FP32)\n            c_pos = pl.cast(position_ids[bias_t0 : bias_t0 + BIAS_T_TILE, 0:1], target_type=pl.FP32)\n            c_pos_scaled = pl.mul(pl.add(c_pos, 1.0), COMPRESS_RATIO_INV)\n            c_pos_i32 = pl.cast(c_pos_scaled, target_type=pl.INT32, mode=\"trunc\")\n            c_pos_q = pl.cast(c_pos_i32, target_type=pl.FP32)\n            # Broadcast the per-token bound over IDX_TOPK cols.\n            c_upper_b = pl.row_expand_mul(pl.full([BIAS_T_TILE, IDX_TOPK], dtype=pl.FP32, value=1.0), c_pos_q)\n            c_ge = pl.minimum(pl.maximum(pl.add(c_raw, CSA_CMP_GE_BIAS), 0.0), 1.0)\n            c_lt = pl.minimum(pl.maximum(pl.sub(c_upper_b, c_raw), 0.0), 1.0)\n            c_mask = pl.mul(c_ge, c_lt)\n            c_out = pl.sub(pl.mul(c_mask, pl.add(c_raw, 1.0)), 1.0)\n            cmp_sparse_indices[bias_t0 : bias_t0 + BIAS_T_TILE, 0:IDX_TOPK] = pl.cast(c_out, target_type=pl.INT32)\n            # Block 0 (sliding-window) is always live; blocks 1.. from the compressed mask.\n            for c_t0 in pl.range(BIAS_T_TILE):\n                pl.write(valid_block_mask, [bias_t0 + c_t0, 0], pl.cast(1, pl.INT32))\n            for c_sb in pl.range(1, SPARSE_BLOCKS):\n                c_s0 = (c_sb - 1) * ATTN_K_TILE\n                c_blk_valid = pl.row_max(c_mask[:, c_s0 : c_s0 + ATTN_K_TILE])\n                for c_dt in pl.range(BIAS_T_TILE):\n                    c_valid = pl.cast(pl.read(c_blk_valid, [c_dt, 0]), target_type=pl.INT32)\n                    pl.write(valid_block_mask, [bias_t0 + c_dt, c_sb], c_valid)\n\n            # Additive softmax bias (0 valid / NEG_INF invalid) that qk_pv adds onto the\n            # scaled scores, so invalid lanes exp to ~0 with no per-block mask multiply.\n            v_win_f = pl.cast(window_swa_indices[bias_t0 : bias_t0 + BIAS_T_TILE, 0:WIN], target_type=pl.FP32)\n            # Index contract: raw == -1 invalid, raw >= 0 valid. min(idx, 0) is -1 for\n            # invalid / 0 for valid; * -NEG_INF gives NEG_INF / 0. c_out is the\n            # post-mask compressed slots (integer-valued), reused directly.\n            v_win_valid = pl.minimum(pl.maximum(pl.add(v_win_f, 1.0), 0.0), 1.0)\n            sparse_bias[bias_t0 : bias_t0 + BIAS_T_TILE, 0:WIN] = pl.mul(pl.sub(v_win_valid, 1.0), -NEG_INF)\n            sparse_bias[bias_t0 : bias_t0 + BIAS_T_TILE, WIN:TOPK] = pl.mul(pl.minimum(c_out, 0.0), -NEG_INF)\n            if PADDED_TOPK > TOPK:\n                sparse_bias[bias_t0 : bias_t0 + BIAS_T_TILE, TOPK:PADDED_TOPK] = pl.full(\n                    [BIAS_T_TILE, PADDED_TOPK - TOPK], dtype=pl.FP32, value=NEG_INF)\n\n        pl.write(qk_wcur, [0], pl.cast(0, pl.INT32))\n        # Pass 1: non-empty tiles to the front of qk_order.\n        for plan_t in pl.range(t_dim):\n            for plan_sb in pl.range(SPARSE_BLOCKS):\n                if pl.read(valid_block_mask, [plan_t, plan_sb]) > 0:\n                    plan_w = pl.read(qk_wcur, [0])\n                    pl.write(qk_order, [plan_w], pl.cast(plan_t * SPARSE_BLOCKS + plan_sb, pl.INT32))\n                    pl.write(qk_wcur, [0], pl.cast(plan_w + 1, pl.INT32))\n        # Pass 2: empty tiles appended to the tail.\n        for plan_t in pl.range(t_dim):\n            for plan_sb in pl.range(SPARSE_BLOCKS):\n                if pl.read(valid_block_mask, [plan_t, plan_sb]) <= 0:\n                    plan_w = pl.read(qk_wcur, [0])\n                    pl.write(qk_order, [plan_w], pl.cast(plan_t * SPARSE_BLOCKS + plan_sb, pl.INT32))\n                    pl.write(qk_wcur, [0], pl.cast(plan_w + 1, pl.INT32))\n\n    # One lane per core. Each lane walks its planned items and gathers the\n    # window/compressed KV rows into one L1 matmul operand; invalid lanes gather a\n    # finite row and are zeroed by the NEG_INF softmax bias.\n    cmp_block_num = pl.tensor.dim(cmp_kv, 0)\n    cmp_kv_flat = pl.reshape(cmp_kv, [cmp_block_num * BLOCK_SIZE, HEAD_DIM])\n    q_flat = pl.reshape(q, [t_heads, HEAD_DIM])\n    sparse_blk_mi = pl.create_tensor([t_blk, 1], dtype=pl.FP32)\n    sparse_blk_li = pl.create_tensor([t_blk, 1], dtype=pl.FP32)\n    sparse_blk_oi = pl.create_tensor([t_blk, HEAD_DIM], dtype=pl.FP32)\n\n    with pl.spmd(NUM_QK_CORES, name_hint=\"qk_pv\", deps=[qk_plan_tid, cache_ready_dep], allow_early_resolve=True) as qk_tid:\n        qk_core = pl.tile.get_block_idx()\n        # Items for this lane: qk_core, qk_core + NUM_QK_CORES, ...  The per-lane\n        # count is derived from the lane index (no stored per-core count); a lane\n        # with index >= qk_items runs zero iterations.\n        qk_lane_iters = (qk_items - qk_core + NUM_QK_CORES - 1) // NUM_QK_CORES\n        for qk_it in pl.range(qk_lane_iters):\n            qk_flat = qk_core + qk_it * NUM_QK_CORES\n            qk_item = pl.cast(pl.read(qk_order, [qk_flat]), pl.INDEX)\n            qk_t = qk_item // SPARSE_BLOCKS\n            qk_sb = qk_item - qk_t * SPARSE_BLOCKS\n            qk_b = qk_t // S\n            qk_token_base = qk_t * (H // H_TILE) * SPARSE_BLOCKS * H_TILE\n            qk_s0 = qk_sb * ATTN_K_TILE\n            qk_bias_row = sparse_bias[qk_t : qk_t + 1, qk_s0 : qk_s0 + ATTN_K_TILE]\n            qk_block_valid = pl.read(valid_block_mask, [qk_t, qk_sb])\n            if qk_block_valid > 0:\n                qk_kv = pl.create_l1([ATTN_K_TILE, HEAD_DIM], pl.BF16)\n                # Sliding-window rows of this tile: all ATTN_K_TILE of them at\n                # WIN == ATTN_K_TILE, none for a compressed tile.\n                qk_win_rows = pl.min(pl.max(WIN - qk_s0, 0), ATTN_K_TILE)\n                if qk_win_rows > 0:\n                    # The window is consecutive absolute positions and paged KV keeps one\n                    # page's positions in consecutive rows, so these rows are SWA_RUNS\n                    # page-contiguous runs -- one multi-row gather each (row count carried\n                    # by valid_shape) instead of a single-row DMA per row. Visible length\n                    # and start mirror the metadata producers\n                    # (decode_metadata.build_swa_metadata / utils.swa_indices_and_lens).\n                    qk_pos = pl.cast(pl.read(position_ids, [qk_t, 0]), pl.INDEX)\n                    qk_win_len = pl.min(qk_pos + 1, WIN)\n                    qk_win_start = qk_pos - qk_win_len + 1\n                    qk_run_rows = pl.min(pl.max(qk_win_len - qk_s0, 0), qk_win_rows)\n                    # qk_head is how far into its page this tile's first window row sits,\n                    # so run i holds the rows landing in the i-th page the tile touches:\n                    # [i * BLOCK_SIZE - qk_head, (i + 1) * BLOCK_SIZE - qk_head) clipped to\n                    # [0, qk_run_rows). Run 0 is the short one, every later run is page\n                    # aligned, and runs past the end clip empty -- no carried cursor.\n                    qk_head = (qk_win_start + qk_s0) % BLOCK_SIZE\n                    for qk_run in pl.unroll(SWA_RUNS):\n                        qk_run_lo = pl.max(qk_run * BLOCK_SIZE - qk_head, 0)\n                        qk_run_hi = pl.min((qk_run + 1) * BLOCK_SIZE - qk_head, qk_run_rows)\n                        if qk_run_hi > qk_run_lo:\n                            qk_run_raw = pl.read(window_swa_indices, [qk_t, qk_s0 + qk_run_lo])\n                            # An unmapped page (-1) falls back to row 0 like the tail below\n                            # -- every such slot is NEG_INF-masked by sparse_bias.\n                            qk_run_src = pl.cast(pl.max(qk_run_raw, 0), pl.INDEX)\n                            qk_kv = pl.gather_row(qk_kv, ori_kv_flat, [qk_run_lo, 0], [qk_run_src, 0],\n                                                  [ATTN_K_TILE, HEAD_DIM],\n                                                  valid_shape=[qk_run_hi - qk_run_lo, HEAD_DIM])\n                    qk_tail_n = qk_win_rows - qk_run_rows\n                    if qk_tail_n > 0:\n                        # Slots past the visible window still need finite data so their\n                        # NEG_INF-biased lanes exp to ~0 instead of reading stale L1.\n                        qk_kv = pl.gather_row(qk_kv, ori_kv_flat, [qk_run_rows, 0], [0, 0],\n                                              [ATTN_K_TILE, HEAD_DIM], valid_shape=[qk_tail_n, HEAD_DIM])\n                # Compressed rows stay per-row: the indexer top-k slots are scattered.\n                for qk_r in pl.range(qk_win_rows, ATTN_K_TILE):\n                    qk_cmp_k = qk_s0 + qk_r - WIN\n                    if qk_cmp_k < CMP_TOPK:\n                        qk_ridx = pl.read(cmp_sparse_indices, [qk_t, qk_cmp_k])\n                        if qk_ridx >= 0:\n                            qk_slot = qk_ridx\n                            qk_cblk = pl.cast(pl.read(cmp_block_table, [qk_b, qk_slot // BLOCK_SIZE]), pl.INDEX)\n                            qk_csrc = qk_cblk * BLOCK_SIZE + qk_slot % BLOCK_SIZE\n                            qk_kv = pl.gather_row(qk_kv, cmp_kv_flat, [qk_r, 0], [qk_csrc, 0], [1, HEAD_DIM])\n                        else:\n                            qk_kv = pl.gather_row(qk_kv, ori_kv_flat, [qk_r, 0], [0, 0], [1, HEAD_DIM])\n                    else:\n                        qk_kv = pl.gather_row(qk_kv, ori_kv_flat, [qk_r, 0], [0, 0], [1, HEAD_DIM])\n\n                # Cube-batch QK_M_TILE head rows per QK/PV matmul. The [QK_M_TILE, ...]\n                # softmax result slices back into H_TILE-row stores at the same offsets\n                # as the per-head-tile path (qk_h_idx == qk_hb * (QK_M_TILE // H_TILE) + qk_sub).\n                for qk_hb in pl.pipeline(H // QK_M_TILE, stage=2):\n                    qk_h0 = qk_hb * QK_M_TILE\n                    qk_head_row = qk_t * H + qk_h0\n                    qk_q_tile = q_flat[qk_head_row : qk_head_row + QK_M_TILE, 0 : HEAD_DIM]\n                    qk_raw = pl.matmul(qk_q_tile, qk_kv, b_trans=True, out_dtype=pl.FP32)\n                    qk_scaled = pl.mul(qk_raw, SOFTMAX_SCALE)\n                    # Broadcast-add the per-block bias directly (col_expand_add) instead\n                    # of col_expand into a dead pl.full(0) base + a separate add.\n                    qk_scores = pl.col_expand_add(qk_scaled, qk_bias_row)\n                    qk_mi = pl.row_max(qk_scores)\n                    # Invalid lanes (NEG_INF bias, zero kv rows) exp to ~0; all-invalid\n                    # blocks die in the merge alpha/beta -- no mask multiply needed.\n                    qk_exp = pl.exp(pl.row_expand_sub(qk_scores, qk_mi))\n                    qk_li = pl.row_sum(qk_exp)\n                    qk_exp_bf16 = pl.cast(qk_exp, target_type=pl.BF16, mode=\"rint\")\n                    qk_oi = pl.matmul(qk_exp_bf16, qk_kv, out_dtype=pl.FP32)\n                    for qk_sub in pl.unroll(QK_M_TILE // H_TILE):\n                        qk_h_idx = qk_hb * (QK_M_TILE // H_TILE) + qk_sub\n                        qk_r0 = qk_sub * H_TILE\n                        qk_blk_base = qk_token_base + qk_h_idx * SPARSE_BLOCKS * H_TILE\n                        qk_row = qk_blk_base + qk_sb * H_TILE\n                        sparse_blk_mi[qk_row : qk_row + H_TILE, 0 : 1] = qk_mi[qk_r0 : qk_r0 + H_TILE, 0 : 1]\n                        sparse_blk_li[qk_row : qk_row + H_TILE, 0 : 1] = qk_li[qk_r0 : qk_r0 + H_TILE, 0 : 1]\n                        sparse_blk_oi[qk_row : qk_row + H_TILE, 0 : HEAD_DIM] = qk_oi[qk_r0 : qk_r0 + H_TILE, 0 : HEAD_DIM]\n            else:\n                qk_oi_zero = pl.full([H_TILE, HEAD_DIM], dtype=pl.FP32, value=0.0)\n                for qk_h_idx in pl.range(H // H_TILE):\n                    qk_blk_base = qk_token_base + qk_h_idx * SPARSE_BLOCKS * H_TILE\n                    qk_row = qk_blk_base + qk_sb * H_TILE\n                    for qk_hr in pl.range(H_TILE):\n                        pl.write(sparse_blk_mi, [qk_row + qk_hr, 0], -3.0e38)\n                        pl.write(sparse_blk_li, [qk_row + qk_hr, 0], 0.0)\n                    sparse_blk_oi[qk_row : qk_row + H_TILE, 0 : HEAD_DIM] = qk_oi_zero\n\n    # Head-invariant interleaved cos and sign-folded sin, built once per token.\n    # The conjugate (inverse) rotation is out[j] = x[j]*cos_il[j] + x[j^1]*sign[j]*sin_il[j].\n    rope_cos_il = pl.create_tensor([T_PAD, ROPE_DIM], dtype=pl.FP32)\n    rope_sin_signed = pl.create_tensor([T_PAD, ROPE_DIM], dtype=pl.FP32)\n    # j^1 lane-swap index for merge_norm's rotation gather. Shaped [H_TILE, ROPE_DIM]\n    # because gather's index must match its source rows.\n    rope_swap_idx = pl.create_tensor([H_TILE, ROPE_DIM], dtype=pl.INT32)\n    with pl.at(level=pl.Level.CORE_GROUP, name_hint=\"rope_cs\", allow_early_resolve=True) as rope_tid:\n        sw_ones = pl.full([H_TILE, ROPE_DIM], dtype=pl.FP32, value=1.0)\n        sw_idx_f = pl.cast(pl.arange(0, [1, ROPE_DIM], dtype=pl.INT32), target_type=pl.FP32)\n        sw_col = pl.col_expand_mul(sw_ones, sw_idx_f)\n        sw_dup_i32 = pl.cast(pl.mul(sw_col, 0.5), target_type=pl.INT32, mode=\"trunc\")\n        sw_dup_f = pl.cast(sw_dup_i32, target_type=pl.FP32)\n        sw_lane = pl.sub(sw_col, pl.mul(sw_dup_f, 2.0))                                           # j%2\n        sw_swap_f = pl.sub(pl.add(sw_col, 1.0), pl.mul(sw_lane, 2.0))                             # j^1\n        rope_swap_idx[0:H_TILE, 0:ROPE_DIM] = pl.cast(sw_swap_f, target_type=pl.INT32)\n\n        cs_ones = pl.full([ROPE_CS_T_TILE, ROPE_DIM], dtype=pl.FP32, value=1.0)\n        cs_idx_f = pl.cast(pl.arange(0, [1, ROPE_DIM], dtype=pl.INT32), target_type=pl.FP32)\n        cs_col = pl.col_expand_mul(cs_ones, cs_idx_f)\n        cs_dup_i32 = pl.cast(pl.mul(cs_col, 0.5), target_type=pl.INT32, mode=\"trunc\")\n        cs_dup_f = pl.cast(cs_dup_i32, target_type=pl.FP32)\n        cs_dup_idx = pl.cast(cs_dup_f, target_type=pl.INT32)                                      # j>>1\n        cs_lane = pl.sub(cs_col, pl.mul(cs_dup_f, 2.0))                                           # j%2\n        cs_sign = pl.neg(pl.sub(pl.mul(cs_lane, 2.0), 1.0))                                       # [+1,-1,...] (conjugate)\n        for cs_rb in pl.range(rope_cs_blocks):\n            cs_t0 = cs_rb * ROPE_CS_T_TILE\n            cs_cos = pl.cast(freqs_cos[cs_t0 : cs_t0 + ROPE_CS_T_TILE, 0:HALF_ROPE], target_type=pl.FP32)\n            cs_sin = pl.cast(freqs_sin[cs_t0 : cs_t0 + ROPE_CS_T_TILE, 0:HALF_ROPE], target_type=pl.FP32)\n            rope_cos_il[cs_t0 : cs_t0 + ROPE_CS_T_TILE, 0:ROPE_DIM] = pl.gather(cs_cos, dim=-1, index=cs_dup_idx)\n            cs_sin_il = pl.gather(cs_sin, dim=-1, index=cs_dup_idx)\n            rope_sin_signed[cs_t0 : cs_t0 + ROPE_CS_T_TILE, 0:ROPE_DIM] = pl.mul(cs_sin_il, cs_sign)\n\n    return (\n        sparse_blk_mi,\n        sparse_blk_li,\n        sparse_blk_oi,\n        rope_cos_il,\n        rope_sin_signed,\n        rope_swap_idx,\n        qk_tid,\n        rope_tid,\n    )\n\n\n@pl.jit.inline\ndef sparse_attn_csa_tp1(\n    q: pl.Tensor[[T_DYN, H, HEAD_DIM], pl.BF16],\n    ori_kv: pl.Tensor[[ORI_BLOCK_NUM_DYN, BLOCK_SIZE, 1, HEAD_DIM], pl.BF16],\n    window_swa_indices: pl.Tensor[[T_DYN, WIN], pl.INT32],\n    cmp_kv: pl.Tensor[[CMP_BLOCK_NUM_DYN, BLOCK_SIZE, 1, HEAD_DIM], pl.BF16],\n    cmp_block_table: pl.Tensor[[B_DYN, CMP_MAX_BLOCKS], pl.INT32],\n    idx_topk: pl.Tensor[[T_DYN, IDX_TOPK], pl.INT32],\n    position_ids: pl.Tensor[[T_DYN, 1], pl.INT32],\n    attn_sink: pl.Tensor[[H], pl.FP32],\n    freqs_cos: pl.Tensor[[T_DYN, ROPE_DIM], pl.BF16],\n    freqs_sin: pl.Tensor[[T_DYN, ROPE_DIM], pl.BF16],\n    o_packed_heads: pl.Tensor[[O_GROUPS * T_PAD, O_GROUP_IN], pl.BF16],\n    cache_ready_dep: pl.Scalar[pl.TASK_ID],\n) -> tuple[pl.Tensor, pl.Scalar[pl.TASK_ID]]:\n    \"\"\"Write CSA heads as ``[group, T_PAD, O_GROUP_IN]`` slabs.\n\n    Only the first runtime ``t_dim`` rows in each group are valid. The\n    returned task ID covers every write to the packed output tensor.\n    \"\"\"\n    (\n        sparse_blk_mi, sparse_blk_li, sparse_blk_oi,\n        rope_cos_il, rope_sin_signed, rope_swap_idx,\n        qk_tid, rope_tid,\n    ) = sparse_attn_csa(\n        q,\n        ori_kv,\n        window_swa_indices,\n        cmp_kv,\n        cmp_block_table,\n        idx_topk,\n        position_ids,\n        freqs_cos,\n        freqs_sin,\n        cache_ready_dep,\n    )\n    t_dim = pl.tensor.dim(q, 0)\n\n    with pl.spmd(t_dim * (H // H_TILE), name_hint=\"merge_norm\", deps=[qk_tid, rope_tid]) as merge_tid:\n        m_idx = pl.tile.get_block_idx()\n        m_t = m_idx // (H // H_TILE)\n        m_h_idx = m_idx - m_t * (H // H_TILE)\n        m_h0 = m_h_idx * H_TILE\n        m_blk_base = m_idx * SPARSE_BLOCKS * H_TILE\n        m_mi = sparse_blk_mi[m_blk_base : m_blk_base + H_TILE, 0 : 1]\n        m_li = sparse_blk_li[m_blk_base : m_blk_base + H_TILE, 0 : 1]\n        m_oi = sparse_blk_oi[m_blk_base : m_blk_base + H_TILE, 0 : HEAD_DIM]\n\n        for m_sb in pl.pipeline(1, SPARSE_BLOCKS, stage=2):\n            m_row = m_blk_base + m_sb * H_TILE\n            m_cur_mi = sparse_blk_mi[m_row : m_row + H_TILE, 0 : 1]\n            m_cur_li = sparse_blk_li[m_row : m_row + H_TILE, 0 : 1]\n            m_cur_oi = sparse_blk_oi[m_row : m_row + H_TILE, 0 : HEAD_DIM]\n            m_mi_new = pl.maximum(m_mi, m_cur_mi)\n            m_alpha = pl.exp(pl.sub(m_mi, m_mi_new))\n            m_beta = pl.exp(pl.sub(m_cur_mi, m_mi_new))\n            m_li = pl.add(pl.mul(m_alpha, m_li), pl.mul(m_beta, m_cur_li))\n            m_oi = pl.add(pl.row_expand_mul(m_oi, m_alpha), pl.row_expand_mul(m_cur_oi, m_beta))\n            m_mi = m_mi_new\n\n        n_sink_bias = pl.reshape(attn_sink[m_h0 : m_h0 + H_TILE], [H_TILE, 1])\n        n_sink_tile = pl.add(pl.sub(m_mi, m_mi), n_sink_bias)\n        n_denom = pl.add(m_li, pl.exp(pl.sub(n_sink_tile, m_mi)))\n        n_full = pl.row_expand_div(m_oi, n_denom)[0 : H_TILE, 0 : HEAD_DIM]\n        n_bf16 = pl.cast(n_full, target_type=pl.BF16, mode=\"rint\")\n\n        # Inverse RoPE on this head-tile's fp32 rope segment: cos_il / sign*sin are\n        # head-invariant per token, rope_swap_idx (j^1) pairs the interleaved real/imag lanes.\n        m_rope = n_full[0 : H_TILE, NOPE_DIM : HEAD_DIM]\n        m_cos_il = rope_cos_il[m_t : m_t + 1, 0 : ROPE_DIM]\n        m_sin_signed = rope_sin_signed[m_t : m_t + 1, 0 : ROPE_DIM]\n        m_swapped = pl.gather(m_rope, dim=-1, index=rope_swap_idx[0:H_TILE, 0:ROPE_DIM])\n        m_rot = pl.add(pl.col_expand_mul(m_rope, m_cos_il), pl.col_expand_mul(m_swapped, m_sin_signed))\n        n_rope_bf16 = pl.cast(m_rot, target_type=pl.BF16, mode=\"rint\")\n        n_full_bf16 = pl.concat(n_bf16[:, : NOPE_DIM], n_rope_bf16)\n\n        for n_hi in pl.unroll(H_TILE):\n            n_pack_row = ((m_h0 + n_hi) // HEADS_PER_GROUP) * T_PAD + m_t\n            n_col = ((m_h0 + n_hi) % HEADS_PER_GROUP) * HEAD_DIM\n            # One HEAD_DIM-wide store per head row: nope and inverse-RoPE halves concat on chip.\n            o_packed_heads[n_pack_row : n_pack_row + 1, n_col : n_col + HEAD_DIM] = n_full_bf16[n_hi : n_hi + 1, :]\n\n    return o_packed_heads, merge_tid\n\n\n@pl.jit\ndef sparse_attn_csa_test(\n    q: pl.Tensor[[T_DYN, H, HEAD_DIM], pl.BF16],\n    ori_kv: pl.Tensor[[ORI_BLOCK_NUM_DYN, BLOCK_SIZE, 1, HEAD_DIM], pl.BF16],\n    window_swa_indices: pl.Tensor[[T_DYN, WIN], pl.INT32],\n    cmp_kv: pl.Tensor[[CMP_BLOCK_NUM_DYN, BLOCK_SIZE, 1, HEAD_DIM], pl.BF16],\n    cmp_block_table: pl.Tensor[[B_DYN, CMP_MAX_BLOCKS], pl.INT32],\n    idx_topk: pl.Tensor[[T_DYN, IDX_TOPK], pl.INT32],\n    position_ids: pl.Tensor[[T_DYN, 1], pl.INT32],\n    attn_sink: pl.Tensor[[H], pl.FP32],\n    freqs_cos: pl.Tensor[[T_DYN, ROPE_DIM], pl.BF16],\n    freqs_sin: pl.Tensor[[T_DYN, ROPE_DIM], pl.BF16],\n    o_packed_heads: pl.Out[pl.Tensor[[O_GROUPS, T_PAD, O_GROUP_IN], pl.BF16]],\n):\n    q.bind_dynamic(0, T_DYN)\n    window_swa_indices.bind_dynamic(0, T_DYN)\n    cmp_block_table.bind_dynamic(0, B_DYN)\n    idx_topk.bind_dynamic(0, T_DYN)\n    position_ids.bind_dynamic(0, T_DYN)\n    freqs_cos.bind_dynamic(0, T_DYN)\n    freqs_sin.bind_dynamic(0, T_DYN)\n\n    cache_ready_dep = pl.system.task_dummy(deps=[])\n    o_packed_flat = pl.reshape(o_packed_heads, [O_GROUPS * T_PAD, O_GROUP_IN])\n    o_packed_flat, _ = sparse_attn_csa_tp1(\n        q,\n        ori_kv, window_swa_indices,\n        cmp_kv, cmp_block_table, idx_topk,\n        position_ids, attn_sink,\n        freqs_cos, freqs_sin,\n        o_packed_flat, cache_ready_dep,\n    )\n    return o_packed_heads\n\n\ndef golden_sparse_attn(tensors):\n    \"\"\"Torch reference for the CSA sparse-attention heads.\"\"\"\n    import torch\n\n    q = tensors[\"q\"].float()\n    tokens = q.shape[0]\n    batch = tokens // S\n    ori_kv = tensors[\"ori_kv\"].float()\n    window_swa_indices = tensors[\"window_swa_indices\"]\n    cmp_kv = tensors[\"cmp_kv\"].float()\n    cmp_block_table = tensors[\"cmp_block_table\"]\n    # Compressed slots: keep raw indexer topk iff 0 <= raw < floor((pos + 1) / COMPRESS_RATIO), else -1.\n    raw = tensors[\"idx_topk\"][:, :CMP_TOPK].to(torch.int64)\n    bound = ((tensors[\"position_ids\"][:, 0].to(torch.int64) + 1) // COMPRESS_RATIO).unsqueeze(1)\n    keep = (raw >= 0) & (raw < bound)\n    cmp_sparse_indices = torch.where(keep, raw, torch.full_like(raw, -1)).to(torch.int32)\n    attn_sink = tensors[\"attn_sink\"].float()\n    cos = tensors[\"freqs_cos\"].float()\n    sin = tensors[\"freqs_sin\"].float()\n\n    o = torch.zeros(tokens, H, HEAD_DIM)\n\n    # Per-query-token attention. The window prefix is driven by window_swa_indices;\n    # cmp_sparse_indices contains compressed-cache slots only.\n    for t in range(tokens):\n        b = t // S\n        kv_rows = []\n        valid = []\n\n        for raw in window_swa_indices[t].tolist():\n            slot = int(raw)\n            if slot >= 0:\n                blk_id = slot // BLOCK_SIZE\n                intra = slot % BLOCK_SIZE\n                kv_rows.append(ori_kv[blk_id, intra, 0])\n                valid.append(True)\n            else:\n                kv_rows.append(torch.zeros(HEAD_DIM, dtype=ori_kv.dtype))\n                valid.append(False)\n\n        for raw in cmp_sparse_indices[t].tolist():\n            if raw < 0:\n                kv_rows.append(torch.zeros(HEAD_DIM, dtype=ori_kv.dtype))\n                valid.append(False)\n                continue\n            cmp_slot = int(raw)\n            blk_id = int(cmp_block_table[b, cmp_slot // BLOCK_SIZE].item())\n            intra = cmp_slot % BLOCK_SIZE\n            kv_rows.append(cmp_kv[blk_id, intra, 0])\n            valid.append(True)\n\n        if not any(valid):\n            continue\n\n        pad_k = PADDED_TOPK - TOPK\n        if pad_k:\n            kv_rows.extend(torch.zeros(HEAD_DIM, dtype=ori_kv.dtype) for _ in range(pad_k))\n            valid.extend(False for _ in range(pad_k))\n\n        kv_b = torch.stack(kv_rows, dim=0)\n        valid_b = torch.tensor(valid, dtype=torch.bool)\n        q_t = q[t]\n\n        block_mi = []\n        block_li = []\n        block_oi = []\n        for tile_start in range(0, PADDED_TOPK, ATTN_K_TILE):\n            kv_tile = kv_b[tile_start:tile_start + ATTN_K_TILE]\n            valid_tile = valid_b[tile_start:tile_start + ATTN_K_TILE]\n            scores = (q_t @ kv_tile.T) * SOFTMAX_SCALE\n            scores = scores.masked_fill(~valid_tile.unsqueeze(0), NEG_INF)\n            mi = scores.max(dim=-1, keepdim=True).values\n            exp_scores = torch.exp(scores - mi).masked_fill(~valid_tile.unsqueeze(0), 0.0)\n            li = exp_scores.sum(dim=-1, keepdim=True)\n            oi = exp_scores.to(torch.bfloat16).float() @ kv_tile.to(torch.bfloat16).float()\n            block_mi.append(mi)\n            block_li.append(li)\n            block_oi.append(oi)\n\n        score_max = block_mi[0]\n        li = block_li[0]\n        oi_num = block_oi[0]\n        for mi_cur, li_cur, oi_cur in zip(block_mi[1:], block_li[1:], block_oi[1:]):\n            score_max_new = torch.maximum(score_max, mi_cur)\n            alpha = torch.exp(score_max - score_max_new)\n            beta = torch.exp(mi_cur - score_max_new)\n            li = alpha * li + beta * li_cur\n            oi_num = alpha * oi_num + beta * oi_cur\n            score_max = score_max_new\n\n        denom = li + torch.exp(attn_sink.unsqueeze(-1) - score_max)\n        o[t] = oi_num / denom\n\n    rope_pair = o[..., NOPE_DIM:].unflatten(-1, (-1, 2))\n    rope_even = rope_pair[..., 0]\n    rope_odd = rope_pair[..., 1]\n    cos_half = cos[:, :HALF_ROPE].unsqueeze(1)\n    sin_half = sin[:, :HALF_ROPE].unsqueeze(1)\n    inv_even = (rope_even * cos_half + rope_odd * sin_half).to(torch.bfloat16).float()\n    inv_odd = (rope_odd * cos_half - rope_even * sin_half).to(torch.bfloat16).float()\n    o_rope = torch.stack([inv_even, inv_odd], dim=-1).flatten(-2)\n    o = torch.cat([o[..., :NOPE_DIM], o_rope], dim=-1).to(torch.bfloat16)\n\n    # Pack as [group, T_PAD, group-input]; rows past the runtime token count are\n    # capacity padding the kernel never writes.\n    packed = tensors[\"o_packed_heads\"]\n    packed[:, :tokens] = o.float().view(tokens, O_GROUPS, O_GROUP_IN).permute(1, 0, 2).to(torch.bfloat16)\n\ndef build_tensor_specs(\n    causal_regression_fixture: bool = False,\n    short_window_fixture: bool = False,\n    mixed_topk_fixture: bool = False,\n    cache_window_replacement_fixture: bool = False,\n    start_pos=None,\n    batch: int = B,\n):\n    \"\"\"Build deterministic demo tensors for the CSA standalone harness.\"\"\"\n    import torch\n    from golden import TensorSpec\n    from utils import (\n        block_table,\n        csa_decode_start_set,\n        position_ids_from_starts,\n        resolve_start_positions,\n        swa_indices_and_lens,\n        token_local_rope,\n    )\n\n    tokens = batch * S\n    starts = resolve_start_positions(\n        start_pos,\n        batch=batch,\n        seq=S,\n        max_seq_len=MAX_SEQ_LEN,\n        default_fn=lambda: csa_decode_start_set(\n            batch=batch,\n            seq=S,\n            compress_ratio=COMPRESS_RATIO,\n        ),\n    )\n    positions = position_ids_from_starts(starts, seq=S)\n    visible_rows = ((positions.to(torch.int64) + 1) // COMPRESS_RATIO).reshape(-1)\n    max_visible_rows = int(visible_rows.max().item())\n    active_cmp_pages = max(1, (max_visible_rows + BLOCK_SIZE - 1) // BLOCK_SIZE)\n    cmp_block_num = batch * active_cmp_pages\n    shared_rope_cos, shared_rope_sin = token_local_rope(\n        M,\n        COMPRESS_RATIO,\n        positions.reshape(-1),\n        max_seq_len=MAX_SEQ_LEN,\n        dtype=torch.bfloat16,\n    )\n    shared_window_block_table = block_table(batch=batch, table_blocks=ORI_MAX_BLOCKS, physical_blocks=ORI_BLOCK_NUM)\n    shared_swa_indices = swa_indices_and_lens(\n        positions,\n        shared_window_block_table,\n        block_size=BLOCK_SIZE,\n        window=WIN,\n    )[0].contiguous()\n\n    def init_q():\n        \"\"\"Initialize the query tensor used by the decode attention stage.\"\"\"\n        q = torch.rand(tokens, H, HEAD_DIM) - 0.5\n        if causal_regression_fixture:\n            q[0].fill_(1.0)\n        return q\n\n    def init_ori_kv():\n        \"\"\"Initialize the sliding-window KV cache pages.\"\"\"\n        kv = torch.rand(ORI_BLOCK_NUM, BLOCK_SIZE, 1, HEAD_DIM) - 0.5\n        if causal_regression_fixture:\n            sentinel_row = int(shared_swa_indices[0, -1].item())\n            if sentinel_row >= 0:\n                kv.reshape(-1, 1, HEAD_DIM)[sentinel_row, 0].fill_(8.0)\n        if cache_window_replacement_fixture:\n            kv[0, 16, 0].fill_(0.0)\n            kv[0, 16, 0, 0] = 4.0\n        return kv\n\n    def init_window_swa_indices():\n        \"\"\"Lower the window through the same producer the model uses.\n\n        Indexing the block table by window slot instead of absolute position\n        would keep every row of a WIN == BLOCK_SIZE window inside one page, so\n        the fixture could not tell a correct page-run split from a broken one.\n        Going through swa_indices_and_lens straddles a page boundary whenever\n        init_position_ids is not page-aligned, which it is not.\n        \"\"\"\n        return shared_swa_indices.clone()\n\n    def init_cmp_kv():\n        \"\"\"Initialize the compressed-cache KV pages.\"\"\"\n        return torch.rand(cmp_block_num, BLOCK_SIZE, 1, HEAD_DIM) - 0.5\n\n    def init_attn_sink():\n        \"\"\"Initialize the per-head sink logits to zero.\"\"\"\n        return torch.zeros(H)\n\n    def init_window_block_table():\n        \"\"\"Build the demo block table for the sliding-window cache pages.\"\"\"\n        return shared_window_block_table.clone()\n\n    def init_cmp_block_table():\n        \"\"\"Build the demo block table for the compressed-cache pages.\"\"\"\n        return block_table(batch=batch, table_blocks=CMP_MAX_BLOCKS, physical_blocks=cmp_block_num)\n\n    def init_cmp_sparse_indices():\n        \"\"\"Build length-aware logical Top-K candidates across each visible range.\"\"\"\n        indices = torch.full((tokens, CMP_TOPK), -1, dtype=torch.int32)\n        for token, visible in enumerate(visible_rows.tolist()):\n            valid = min(CMP_TOPK, int(visible))\n            if short_window_fixture:\n                valid = min(valid, 17)\n            if valid == 0:\n                continue\n            if valid == int(visible) or mixed_topk_fixture:\n                candidates = torch.arange(valid, dtype=torch.int64)\n            elif valid == 1:\n                candidates = torch.zeros(1, dtype=torch.int64)\n            else:\n                candidates = torch.div(\n                    torch.arange(valid, dtype=torch.int64) * (int(visible) - 1),\n                    valid - 1,\n                    rounding_mode=\"floor\",\n                )\n            indices[token, :valid] = candidates.to(torch.int32)\n        if cache_window_replacement_fixture:\n            indices[:, :] = -1\n        if causal_regression_fixture:\n            indices[0, :] = -1\n        return indices\n\n    def init_idx_topk():\n        \"\"\"Raw logical Top-K output produced by the standalone indexer.\"\"\"\n        return init_cmp_sparse_indices()\n\n    def init_position_ids():\n        return positions.reshape(tokens, 1).contiguous()\n\n    def init_cos():\n        \"\"\"Build the split-half cosine table used by the inverse-RoPE reference.\"\"\"\n        return shared_rope_cos.clone()\n\n    def init_sin():\n        \"\"\"Build the split-half sine table used by the inverse-RoPE reference.\"\"\"\n        return shared_rope_sin.clone()\n\n    return [\n        TensorSpec(\"q\", [tokens, H, HEAD_DIM], torch.bfloat16, init_value=init_q),\n        TensorSpec(\"ori_kv\", [ORI_BLOCK_NUM, BLOCK_SIZE, 1, HEAD_DIM], torch.bfloat16, init_value=init_ori_kv),\n        TensorSpec(\"window_swa_indices\", [tokens, WIN], torch.int32, init_value=init_window_swa_indices),\n        TensorSpec(\"cmp_kv\", [cmp_block_num, BLOCK_SIZE, 1, HEAD_DIM], torch.bfloat16, init_value=init_cmp_kv),\n        TensorSpec(\"cmp_block_table\", [batch, CMP_MAX_BLOCKS], torch.int32, init_value=init_cmp_block_table),\n        TensorSpec(\"idx_topk\", [tokens, IDX_TOPK], torch.int32, init_value=init_idx_topk),\n        TensorSpec(\"position_ids\", [tokens, 1], torch.int32, init_value=init_position_ids),\n        TensorSpec(\"attn_sink\", [H], torch.float32, init_value=init_attn_sink),\n        TensorSpec(\"freqs_cos\", [tokens, ROPE_DIM], torch.bfloat16, init_value=init_cos),\n        TensorSpec(\"freqs_sin\", [tokens, ROPE_DIM], torch.bfloat16, init_value=init_sin),\n        TensorSpec(\"o_packed_heads\", [O_GROUPS, T_PAD, O_GROUP_IN], torch.bfloat16),\n    ]\n\n\nif __name__ == \"__main__\":\n    import argparse\n    from golden import ratio_allclose, run\n\n    parser = argparse.ArgumentParser()\n    parser.add_argument(\"-p\", \"--platform\", type=str, default=\"a2a3\", choices=[\"a2a3\", \"a2a3sim\", \"a5\", \"a5sim\"])\n    parser.add_argument(\"-d\", \"--device\", type=int, default=0)\n    parser.add_argument(\"-b\", \"--batch\", type=int, default=B,\n                        help=f\"runtime request count up to {B} (the compile-time upper bound). \"\n                             \"The token axis is pl.dynamic, so one compiled program \"\n                             \"serves every value.\")\n    parser.add_argument(\"--start-pos\", type=str, default=None,\n                        help=\"Fixture-only start position: one value for a uniform batch or \"\n                             \"a comma-separated value per request.\")\n    parser.add_argument(\"--causal-regression-fixture\", action=\"store_true\", default=False,\n                        help=\"Amplify the S=2 future-window-slot regression.\")\n    parser.add_argument(\"--short-window-fixture\", action=\"store_true\", default=False,\n                        help=\"Use a short-window topk row with valid prefix + -1 padding.\")\n    parser.add_argument(\"--mixed-topk-fixture\", action=\"store_true\", default=False,\n                        help=\"Use -1-padded window slots with valid compressed raw indices.\")\n    parser.add_argument(\"--cache-window-replacement-fixture\", action=\"store_true\", default=False,\n                        help=\"Place a sentinel row inside the cache window prefix.\")\n    parser.add_argument(\"--golden-data\", type=str, default=None)\n    parser.add_argument(\"--enable-chip-swimlane\", type=int, nargs=\"?\", const=1, default=0, choices=(0, 1, 2))\n    parser.add_argument(\"--enable-dep-gen\", action=\"store_true\", default=False,\n                        help=\"Capture PTO2 dependency edges (deps.json) for the swimlane converter.\")\n    parser.add_argument(\"--enable-pmu\", nargs=\"?\", const=2, default=0, type=int, choices=[0, 1, 2, 4])\n    parser.add_argument(\"--dump-passes\", action=\"store_true\", default=False)\n    args = parser.parse_args()\n    if args.batch < 1 or args.batch > B:\n        parser.error(f\"--batch must be in [1, {B}], got {args.batch}\")\n    start_pos = None\n    if args.start_pos is not None:\n        try:\n            start_values = [int(value.strip()) for value in args.start_pos.split(\",\") if value.strip() != \"\"]\n        except ValueError:\n            parser.error(f\"--start-pos must contain integers, got {args.start_pos!r}\")\n        if not start_values:\n            parser.error(\"--start-pos must contain at least one integer\")\n        if len(start_values) not in (1, args.batch):\n            parser.error(f\"--start-pos needs 1 or {args.batch} values, got {len(start_values)}\")\n        start_pos = start_values[0] if len(start_values) == 1 else start_values\n\n    print(f\"compress_ratio={COMPRESS_RATIO} -> TOPK={TOPK} SPARSE_BLOCKS={SPARSE_BLOCKS} PADDED_TOPK={PADDED_TOPK}\", flush=True)\n\n    result = run(\n        fn=sparse_attn_csa_test,\n        specs=build_tensor_specs(\n            args.causal_regression_fixture,\n            args.short_window_fixture,\n            args.mixed_topk_fixture,\n            args.cache_window_replacement_fixture,\n            start_pos=start_pos,\n            batch=args.batch,\n        ),\n        golden_fn=golden_sparse_attn,\n        golden_data=args.golden_data,\n        compile_cfg=dict(dump_passes=args.dump_passes),\n        runtime_cfg=dict(\n            platform=args.platform,\n            device_id=args.device,\n            enable_chip_swimlane=args.enable_chip_swimlane,\n            enable_dep_gen=args.enable_dep_gen,\n            enable_pmu=args.enable_pmu,\n        ),\n        rtol=1e-3,\n        atol=1e-3,\n        compare_fn={\n            \"o_packed_heads\": ratio_allclose(\n                atol=1e-4, rtol=1.0 / 128,\n                valid_rows=args.batch * S, valid_axis=1,\n            ),\n        },\n    )\n    if not result.passed:\n        if result.error:\n            print(result.error)\n        raise SystemExit(1)\n"});
